    'A Claude session was undone: %d rows restored, %d removed, %d left because they changed since.' => 'Relace Clauda byla vrácena: obnoveno řádků %d, odstraněno %d, ponecháno %d, protože se mezitím změnily.',
    'A SECURITY update %s is available – install it in Settings → Backups.' => 'Je k dispozici BEZPEČNOSTNÍ aktualizace %s – nainstalujete ji v Nastavení → Zálohy.',
    'A TV or a tablet in the reception, showroom or waiting room opens the address below and rotates slides by itself: the latest news, items of the chosen collections and today\'s opening hours. The address has a secret part, so nobody finds the screen by guessing; it is not indexed and sets no cookies.' => 'Televize nebo tablet na recepci, v showroomu či čekárně otevře adresu níže a sám střídá snímky: nejnovější novinky, položky zvolených kolekcí a dnešní otevírací dobu. Adresa má tajnou část, takže obrazovku nikdo nenajde hádáním; neindexuje se a nenastavuje cookies.',
    'A backup on the same server as the site does not help if you lose the hosting. Each new database backup can therefore upload itself elsewhere. Media are not copied this way – download them as a ZIP from time to time.' => 'Záloha na stejném serveru jako web nepomůže, když o hosting přijdete. Každá nová záloha databáze se proto může sama nahrát jinam. Média se tímto způsobem nekopírují – stahujte si je občas jako ZIP.',
    'A backup on the same server as the site does not help if you lose the hosting. Each new database backup therefore uploads itself elsewhere, and the media/ folder is copied to the same place – only new and changed files, in the background.' => 'Záloha na stejném serveru jako web nepomůže, když přijdete o hosting. Každá nová záloha databáze se proto nahraje jinam a na stejné místo se kopíruje i složka media/ – jen nové a změněné soubory, na pozadí.',
    'A band with four bold numbers in the primary colour.' => 'Pás se čtyřmi výraznými čísly v hlavní barvě.',
    'A big number with a label that counts up when shown (years of experience, customers, projects).' => 'Velké číslo s popiskem, které se při zobrazení napočítá (roky praxe, zákazníci, projekty).',
    'A big number with a label that counts up when shown (years of experience, customers, projects). The number may be a fact or a computed token, so it stays true.' => 'Velké číslo s popiskem, které se po zobrazení napočítá (roky zkušeností, zákazníci, zakázky). Číslem může být fakt nebo počítaná značka, aby zůstalo pravdivé.',
    'A blueprint sets the site up for a kind of business: the ready-made collections it needs, the facts to fill in, questions for the owner, checks in the site audit and instructions for Claude.' => 'Oborový plán připraví web pro určitý druh podnikání: hotové kolekce, které potřebuje, fakty k doplnění, otázky pro majitele, kontroly v auditu webu a pokyny pro Clauda.',
    'A bold hero on a dark background – set a background image in the section style.' => 'Výrazný úvod s tmavým pozadím – obrázek pozadí nastavíte ve stylu sekce.',
    'A bold offer with a code and a button.' => 'Výrazná nabídka s kódem a tlačítkem.',
    'A booking calendar, form or player from Calendly, Google, Microsoft Forms, Tally, Typeform, Airtable, Spotify or SoundCloud – loads after a click.' => 'Rezervační kalendář, formulář nebo přehrávač z Calendly, Googlu, Microsoft Forms, Tally, Typeformu, Airtable, Spotify nebo SoundCloudu – načte se po kliknutí.',
    'A booking is made' => 'Provede se rezervace',
    'A business website usually consists of Home, About us, Services and Contact.' => 'Firemní web obvykle tvoří Úvod, O nás, Služby a Kontakt.',
    'A call that fails is retried after 1, 5 and 30 minutes and after 2 and 12 hours. Records are deleted after 30 days; the content of a delivered call is not kept.' => 'Nedoručené volání se zkusí znovu po 1, 5 a 30 minutách a po 2 a 12 hodinách. Záznamy se mažou po 30 dnech; obsah doručeného volání se neuchovává.',
    'A class shares its look between elements on all pages. Click a class to edit it.' => 'Třída sdílí vzhled mezi prvky na všech stránkách. Klepnutím na třídu ji upravíte.',
    'A click goal needs the address the link or button leads to.' => 'Cíl „klik“ potřebuje adresu, kam odkaz nebo tlačítko vede.',
    'A click on a link or button that leads to the address you give.' => 'Klik na odkaz nebo tlačítko, které vede na vámi zadanou adresu.',
    'A colleague wrote a new request for Claude: %s' => 'Kolega napsal nový požadavek pro Clauda: %s',
    'A collection is a list of similar things with their own fields – testimonials, team members, products, branches, a price list. Put them on the site with the Collection list element in the builder; each item can also have its own page.' => 'Kolekce je seznam podobných věcí s vlastními poli – reference, členové týmu, produkty, pobočky, ceník. Na web je dostanete prvkem Výpis kolekce v builderu, každá položka může mít i vlastní stránku.',
    'A collection with a date field (events, courses) shows only the upcoming items.' => 'Kolekce s polem termínu (akce, kurzy) ukazuje jen nadcházející položky.',
    'A coloured box with a heading, a sentence and a button.' => 'Barevný box s nadpisem, větou a tlačítkem.',
    'A coloured call to action above a two-column footer.' => 'Barevná výzva k akci nad patičkou ve dvou sloupcích.',
    'A comment on the draft of “%s” arrived from a preview link.' => 'Ke konceptu „%s“ přišel komentář z odkazu na náhled.',
    'A component cannot be created from this element.' => 'Z tohoto prvku komponenta vzniknout nemůže.',
    'A component is a block you use in several places – a service card, a contact strip, a call to action. In the builder, select an element and choose “Save as component”; when you edit it later, it changes everywhere at once.' => 'Komponenta je blok, který používáte na víc místech – karta služby, kontaktní pruh, výzva. V builderu vyberte prvek a zvolte „Uložit jako komponentu“; když ji pak upravíte, změní se všude najednou.',
    'A component is a shared template: editing it under Components changes it everywhere it is used. The element on this page is replaced by the component.' => 'Komponenta je společná předloha: úprava v Komponentách se projeví všude, kde je použitá. Prvek na stránce se nahradí jejím použitím.',
    'A component or section keeps a stable key (from its name): a site updates its copy instead of adding another.' => 'Komponenta nebo sekce má stálý klíč (z názvu): web svou kopii aktualizuje, místo aby přidal další.',
    'A connection ends %s – connect Claude again before then (a personal token: create a new one in My account).' => 'Jedno napojení skončí %s – do té doby Clauda připojte znovu (osobní token: vytvořte nový v Můj účet).',
    'A container has no content of its own – put elements into it and set its look in the Style tab.' => 'Kontejner nemá vlastní obsah – vložte do něj prvky, vzhled nastavíte v záložce Styl.',
    'A container loads whatever its owner sets up in it.' => 'Kontejner načte, co v něm jeho vlastník nastaví.',
    'A conversion is a form sent or a newsletter sign-up in the pop-up. The counters work without cookies and without any visitor data.' => 'Konverze je odeslaný formulář nebo přihlášení k odběru v okně. Počitadla fungují bez cookies a bez údajů o návštěvnících.',
    'A corner panel with a contact form, opened by a link or button to it.' => 'Panel v rohu s kontaktním formulářem, otevře ho odkaz nebo tlačítko.',
    'A corner panel with the date, the place and a registration link.' => 'Panel v rohu s datem, místem a odkazem na registraci.',
    'A custom link needs both text and an address.' => 'Vlastní odkaz potřebuje text i adresu.',
    'A customer sent a testimonial (a hidden draft reference).' => 'Zákazník poslal referenci (skrytý koncept).',
    'A dark gallery: near-black background, light type and a warm accent. Photos and videos take the stage.' => 'Tmavá galerie: téměř černé pozadí, světlé písmo a teplý akcent. Fotografie a videa v hlavní roli.',
    'A delivery to an outside service failed after all retries.' => 'Doručení do externí služby selhalo i po všech opakováních.',
    'A delivery to an outside service failed: %s' => 'Doručení do externí služby selhalo: %s',
    'A demo gallery with %d generated pictures was created.' => 'Byla vytvořena ukázková galerie s %d vygenerovanými obrázky.',
    'A design including visualisation and budget.' => 'Návrh včetně vizualizace a rozpočtu.',
    'A design made for you' => 'Návrh přesně pro vás',
    'A developer’s guide is in docs/EXTENSIONS.md. This Talea offers extension API %d.' => 'Návod pro vývojáře je v docs/EXTENSIONS.md. Tato Talea nabízí rozhraní pro doplňky ve verzi %d.',
    'A familiar blog layout: a contact bar above the menu, blue links and a calm serif.' => 'Známý blogový layout: kontaktní lišta nad menu, modré odkazy a klidné patkové písmo.',
    'A feature that is off takes its menu item, its fields and its checks with it.' => 'Vypnutá funkce s sebou bere položku v menu, pole a kontroly.',
    'A few sentences about me' => 'Pár vět o mně',
    'A few short steps and your website is running. Everything can be changed later in the administration.' => 'Pár krátkých kroků a váš web běží. Vše lze později změnit v administraci.',
    'A few words about you' => 'Pár slov o vás',
    'A fixed completion date' => 'Pevný termín dokončení',
    'A fleet console is another Talea installation that shows all your sites on one screen. This site sends it a signed report every hour – version, health, background jobs, backups, enquiries waiting and visits, never names or the content of enquiries. The console cannot get into this site.' => 'Konzole webů je jiná instalace Talea, která ukazuje všechny vaše weby na jedné obrazovce. Tento web jí každou hodinu pošle podepsané hlášení – verzi, stav, úlohy na pozadí, zálohy, poptávky čekající na odpověď a návštěvy, nikdy jména ani obsah poptávek. Konzole se do tohoto webu dostat nemůže.',
    'A floating arrow back to the top of the page – put it in the footer.' => 'Plovoucí šipka zpět na začátek stránky – vložte ji do patičky.',
    'A focus keyword for each page and news item, a score from 0 to 100 and a list of what to fix, right where you edit.' => 'Hlavní klíčové slovo pro každou stránku a novinku, skóre od 0 do 100 a seznam toho, co opravit, přímo tam, kde upravujete.',
    'A focus keyword, a score from 0 to 100 and a list of what to fix for every page, news item and collection item.' => 'Hlavní klíčové slovo, skóre od 0 do 100 a seznam toho, co opravit, u každé stránky, novinky a položky kolekce.',
    'A form is sent' => 'Odešle se formulář',
    'A form on the page is submitted.' => 'Odešle se formulář na stránce.',
    'A form sent and a booking made are counted when the visitor submits the form on this page.' => 'Odeslaný formulář a provedená rezervace se počítají, když návštěvník na této stránce odešle formulář.',
    'A full-width band with centred content.' => 'Pás přes celou šířku stránky s obsahem uprostřed.',
    'A future date = the news item is published automatically at that time.' => 'Budoucí datum = novinka se vydá sama v daný čas.',
    'A gallery holds at most 1000 images.' => 'Galerie pojme nejvýše 1000 obrázků.',
    'A grid of photos that open full screen when clicked.' => 'Mřížka fotek, které se po klepnutí otevřou přes celou obrazovku.',
    'A grid of six images – work samples, premises, products.' => 'Mřížka šesti obrázků – ukázky práce, prostory, výrobky.',
    'A group needs text.' => 'Skupina potřebuje text.',
    'A group of elements stacked or side by side – a card, a row of buttons.' => 'Skupina prvků pod sebou nebo vedle sebe – karta, řada tlačítek.',
    'A group with this name already exists.' => 'Skupina s tímto názvem už existuje.',
    'A guarantee on all work' => 'Záruka na veškerou práci',
    'A guide or price list in exchange for contact details – the form goes to Enquiries.' => 'Nabídka průvodce nebo ceníku výměnou za kontakt – formulář jde do Poptávek.',
    'A guide to the site for language models.' => 'Průvodce webem pro jazykové modely.',
    'A heading and a longer text split into two columns.' => 'Nadpis a delší text rozdělený do dvou sloupců.',
    'A heading and a text – build the rest in the builder.' => 'Nadpis a text – zbytek poskládáte v builderu.',
    'A heading and a video across the content width.' => 'Nadpis a video přes celou šířku obsahu.',
    'A heading and three cards with the main reasons to choose you.' => 'Nadpis a tři karty s hlavními důvody, proč si vybrat vás.',
    'A heading, a sentence and a form – messages arrive in Enquiries and by email.' => 'Nadpis, věta a formulář – zprávy chodí do Poptávek a e-mailem.',
    'A heading, a sentence and the booking form – appointments arrive in Bookings and by email.' => 'Nadpis, věta a rezervační formulář – termíny přijdou do Rezervací a e-mailem.',
    'A heading, a short text and an e-mail field with confirmed sign-up.' => 'Nadpis, krátký text a pole pro e-mail s potvrzením odběru.',
    'A hidden page does not appear in the menu on the site.' => 'Skrytá stránka se v menu na webu neukáže.',
    'A kept' => 'A zachováno',
    'A link has no text – a screen reader has nothing to read.' => 'Odkaz nemá text – čtečka obrazovky nemá co přečíst.',
    'A link or button is clicked' => 'Klikne se na odkaz nebo tlačítko',
    'A link or button to #popup-%s opens the pop-up at any time – even when it does not show on its own.' => 'Odkaz nebo tlačítko s adresou #popup-%s okno otevře kdykoli – i když se samo neukazuje.',
    'A link to a trustworthy source helps readers and search engines.' => 'Odkaz na důvěryhodný zdroj pomáhá čtenářům i vyhledávačům.',
    'A list of points – with bullets, numbers or ticks.' => 'Výčet bodů – s odrážkami, čísly nebo fajfkami.',
    'A list of services with a short description and a “from” price.' => 'Seznam služeb s krátkým popisem a cenou „od“.',
    'A look is a ready set of colours (with a dark mode), fonts, scale and shapes plus a header and a footer. Applying it goes to the draft look: preview the whole site, then publish or discard. Pages, news, menus and settings stay as they are.' => 'Vzhled je hotová sada barev (s tmavým režimem), písem, měřítka a tvarů spolu se záhlavím a zápatím. Použití jde do konceptu vzhledu: prohlédněte si celý web a pak vzhled zveřejněte, nebo zahoďte. Stránky, novinky, menu a nastavení zůstanou beze změny.',
    'A mail service fills in the server, the port and the encryption. The user name and the password stay yours to paste – the service’s SMTP credentials, not its API key unless the service says so.' => 'Poštovní služba doplní server, port a šifrování. Uživatelské jméno a heslo vložíte sami – přihlašovací údaje SMTP služby, ne její API klíč, pokud služba neříká jinak.',
    'A mailbox at your host, Google Workspace, Seznam, or a service such as Brevo, Mailgun, Amazon SES… Recommended for newsletters.' => 'Schránka u hostingu, Google Workspace, Seznam, nebo služba Brevo, Mailgun, Amazon SES… Doporučeno pro newslettery.',
    'A map with the company address – loads only after a click (privacy, speed).' => 'Mapa s adresou firmy – načte se až po klepnutí (soukromí, rychlost).',
    'A member account of the site (%s)' => 'Členský účet webu (%s)',
    'A message that fails to send is retried after 5 minutes, 30 minutes, 2 and 12 hours. Records are deleted after 30 days; message content is not kept.' => 'Zpráva, kterou se nepodaří odeslat, se zkouší znovu za 5 minut, 30 minut, 2 a 12 hodin. Záznamy se mažou po 30 dnech; obsah zpráv se neuchovává.',
    'A monitoring tool can read the status as JSON. Create an access token first.' => 'Dohledový nástroj může stav číst jako JSON. Nejprve vytvořte přístupový token.',
    'A narrow strip: a sentence on the left, a button on the right.' => 'Úzký pruh: věta vlevo, tlačítko vpravo.',
    'A new request for Claude: %s' => 'Nový požadavek pro Clauda: %s',
    'A new secret has been created. Paste it into every receiver that checks the signature.' => 'Nový klíč je vytvořený. Vložte ho do každého příjemce, který ověřuje podpis.',
    'A new version %s is available – install it in Settings → Backups.' => 'Je k dispozici nová verze %s – nainstalujete ji v Nastavení → Zálohy.',
    'A new workshop and the first employees.' => 'Nová dílna a první zaměstnanci.',
    'A newsletter that is being sent or was sent cannot be changed.' => 'Newsletter, který se odesílá nebo už odešel, nejde měnit.',
    'A note needs a text.' => 'Poznámka potřebuje text.',
    'A note needs a title.' => 'Poznámka potřebuje název.',
    'A notice that is or was posted cannot be hidden – it stays on the board until its takedown date and then in the archive. Change the dates instead.' => 'Oznámení, které je nebo bylo vyvěšeno, nelze skrýt – zůstává na desce do dne sejmutí a potom v archivu. Změňte místo toho data.',
    'A number is shown with the thousands separator of the language, a date in its format, an amount as 1 500 CZK (enter 1500 CZK).' => 'Číslo se ukáže s oddělovačem tisíců podle jazyka, datum v jeho formátu, částka jako 1 500 CZK (zadejte 1500 CZK).',
    'A page can still differ under its own Advanced settings.' => 'Stránka se může lišit ve svém vlastním pokročilém nastavení.',
    'A page for each course with its start and end, the place, the price, the capacity and a description; the list shows only the courses still to come, the nearest first.' => 'Stránka pro každý kurz se začátkem a koncem, místem, cenou, kapacitou a popisem; výpis ukazuje jen kurzy, které teprve přijdou, nejbližší první.',
    'A page for each machine with a photo, the model, a table of parameters, the year, a datasheet to download and its availability.' => 'Stránka pro každý stroj s fotkou, modelem, tabulkou parametrů, rokem, technickým listem ke stažení a dostupností.',
    'A page for each property for sale or to let with a photo, the price, the location, the floor and plot area, the layout, the energy rating, parameters and a map; the list filters by offer.' => 'Stránka pro každou nemovitost na prodej nebo k pronájmu s fotkou, cenou, lokalitou, užitnou plochou a plochou pozemku, dispozicí, energetickou třídou, parametry a mapou; výpis filtruje podle typu nabídky.',
    'A page for each room, apartment or cottage with a photo, how many guests it takes, the beds, the size, the price per night from, the amenities and a booking link.' => 'Stránka pro každý pokoj, apartmán nebo chatu s fotkou, počtem hostů, lůžky, velikostí, cenou za noc od, vybavením a odkazem na rezervaci.',
    'A page for each service with a summary, an image, a description and a price from; the list shows cards with the summary.' => 'Stránka pro každou službu se shrnutím, obrázkem, popisem a cenou od; výpis ukazuje karty se shrnutím.',
    'A page has up to five focus keywords. Remove one to add another.' => 'Stránka má nejvýše pět klíčových slov. Pro přidání dalšího jedno odeberte.',
    'A page in the trash uses this address – restore it or delete it permanently.' => 'Tuto adresu má stránka v koši – obnovte ji, nebo ji smažte natrvalo.',
    'A page is reached' => 'Dosáhne se stránky',
    'A page or a collection already uses this URL.' => 'Tuto adresu už používá stránka nebo kolekce.',
    'A page with this URL already exists.' => 'Stránka s touto adresou už existuje.',
    'A page, news item or category may have the same address as one in another language version (/contact and /en/contact). Redirects of changed addresses then keep the language prefix. Switching it off is refused while two language versions share an address.' => 'Stránka, novinka nebo kategorie smí mít stejnou adresu jako ta v jiné jazykové verzi (/kontakt a /en/kontakt). Přesměrování změněných adres si pak ponechají jazykový prefix. Vypnout to nejde, dokud si dvě jazykové verze dělí adresu.',
    'A page, news item, collection item or pop-up asks for a review (its review-by day has come).' => 'Stránka, novinka, položka kolekce nebo pop-up okno žádají o kontrolu (nastal den „zkontrolovat do“).',
    'A page, news item, collection item or pop-up was true until a past day and hid itself.' => 'Stránka, novinka, položka kolekce nebo pop-up okno platily do minulého dne a samy se skryly.',
    'A path from Media, e.g. media/2026/10/agency.svg – click the file in Media to open it, its address starts with media/.' => 'Cesta z Médií, např. media/2026/10/agentura.svg – soubor otevřete kliknutím v Médiích, jeho adresa začíná media/.',
    'A path on the site (/contact) or a full https:// address.' => 'Cesta na webu (/kontakt) nebo celá adresa https://.',
    'A path on this site that no longer exists.' => 'Cesta na tomto webu, která už neexistuje.',
    'A person whose column stays empty keeps the weekly hours.' => 'Když sloupec osoby zůstane prázdný, platí její týdenní hodiny.',
    'A personal project manager' => 'Osobní správce zakázky',
    'A photo or illustration from Media, optionally with a caption and link.' => 'Fotka nebo ilustrace z Médií, volitelně s popiskem a odkazem.',
    'A pill in the corner with a short message, a button that opens a contact form and a WhatsApp link – the form panel is created with it.' => 'Lišta v rohu s krátkou zprávou, tlačítkem, které otevře kontaktní formulář, a odkazem na WhatsApp – panel s formulářem se vytvoří s ní.',
    'A product\'s variant, quantity and a button that adds it to the enquiry basket, with a box to compare products.' => 'Varianta a množství produktu a tlačítko, které ho přidá do poptávky, s políčkem pro porovnání produktů.',
    'A quiet white portfolio: a centred logo, fine serif headings and large images. For photographers and artists.' => 'Klidné bílé portfolio: centrované logo, jemná patková písma a velké obrázky. Pro fotografy a umělce.',
    'A quote or customer testimonial with a name.' => 'Citát nebo reference zákazníka se jménem.',
    'A redirect is only used when nothing exists at the old address. It is created automatically when the address of a page, news item or category changes.' => 'Přesměrování se použije jen tehdy, když na staré adrese nic není. Při změně adresy stránky, novinky nebo kategorie vzniká samo.',
    'A redirect needs a target.' => 'Přesměrování potřebuje cíl.',
    'A restored enquiry comes back as it was; after 30 days in the trash it is deleted permanently with its attachments.' => 'Obnovená poptávka se vrátí beze změny; po 30 dnech v koši se smaže natrvalo i s přílohami.',
    'A reusable block – editing the component updates it everywhere it is used.' => 'Znovupoužitelný blok – úprava komponenty se projeví všude, kde je použitá.',
    'A role with this name already exists.' => 'Role s tímto názvem už existuje.',
    'A row of logos of companies you work with.' => 'Řada log firem, se kterými spolupracujete.',
    'A rule' => 'Pravidlo',
    'A scheduled newsletter can be changed only by someone who may send newsletters – unschedule it first.' => 'Naplánovaný newsletter může měnit jen ten, kdo smí newslettery odesílat – nejdřív zrušte naplánování.',
    'A scheduled run works through the requests %s.' => 'Plánovaný běh vyřizuje požadavky %s.',
    'A second main heading' => 'Druhý hlavní nadpis',
    'A section or an element of a page' => 'Sekce nebo prvek stránky',
    'A short description of the service and who it is for.' => 'Krátký popis služby a pro koho je.',
    'A short file at /llms.txt that lists your pages for AI assistants that read websites.' => 'Krátký soubor na /llms.txt, který vypisuje vaše stránky pro AI asistenty čtoucí weby.',
    'A short label, a big headline and a button – all centred.' => 'Krátký štítek, velký nadpis a tlačítko – vše na středu.',
    'A short text for the window.' => 'Krátký text okna.',
    'A sign-in link that turns into the member’s name and a sign-out button once they are signed in.' => 'Odkaz „Přihlásit se“, který se po přihlášení změní na jméno člena a tlačítko pro odhlášení.',
    'A simple icon (check, phone, star…) – set its colour and size with the style.' => 'Jednoduchá ikona (fajfka, telefon, hvězda…) – barvu a velikost nastavíte stylem.',
    'A site in several languages: each further version (e.g. /cs/…) has its own pages, categories and news, a language switcher and hreflang tags. Pick the languages in Settings → General.' => 'Web ve více jazycích: každá další verze (/en/…) má své stránky, kategorie a novinky, přepínač jazyků a značky hreflang. Jazyky vyberete v Nastavení → Základní.',
    'A site reports the version it applied with its next report; a site that did not switch the kit on shows none.' => 'Web nahlásí použitou verzi se svým příštím hlášením; web, který sadu nezapnul, žádnou neukazuje.',
    'A slim bar at the top with a short message and a link.' => 'Úzká lišta nahoře s krátkou zprávou a odkazem.',
    'A small button on every page: larger text, higher contrast, underlined links, reduced motion. Remembered in the visitor’s browser, no cookies.' => 'Malé tlačítko na každé stránce: větší písmo, vyšší kontrast, podtržené odkazy, omezený pohyb. Pamatuje si prohlížeč návštěvníka, bez cookies.',
    'A small square image shown on the browser tab and in bookmarks. 256×256 px is enough.' => 'Malý čtvercový obrázek na kartě prohlížeče a v záložkách. Stačí 256×256 px.',
    'A square photo, 300 × 300 px is enough.' => 'Čtvercová fotka, stačí 300 × 300 px.',
    'A starter site brings Home, About us, Services and Contact pages with sample texts and its own style – edit the content in the builder and the style in Site appearance.' => 'Startovací web přinese stránky Úvod, O nás, Služby a Kontakt s ukázkovými texty a svůj styl – obsah pak upravíte v builderu, styl ve Vzhledu webu.',
    'A strip with four short promises – delivery, guarantee, deadline, payment.' => 'Pruh se čtyřmi krátkými sliby – doprava, záruka, termín, platba.',
    'A style is a ready set of colours, fonts, sizes and corner radius. Pick one with a click and fine-tune it in the other tabs – the content of the site does not change.' => 'Styl je hotová sada barev, písem, velikostí a zaoblení. Vyberte ho jedním klikem a v dalších záložkách dolaďte – obsah webu se nemění.',
    'A subpage has an address under its parent (/services/kitchens) and appears in its breadcrumbs.' => 'Podstránka má adresu pod nadřazenou (/sluzby/kuchyne) a ukáže se v jejích drobečcích.',
    'A summary of what happened to the website %s in %s: counts, titles and page addresses only – no personal data.' => 'Shrnutí toho, co se dělo na webu %s v období %s: jen počty, názvy a adresy stránek – žádné osobní údaje.',
    'A table has no header cells (th) – screen readers cannot tell what the columns mean.' => 'Tabulka nemá záhlaví (th) – čtečky obrazovky nepoznají, co sloupce znamenají.',
    'A template builds the page from ready-made sections with sample texts and opens it in the builder.' => 'Šablona poskládá stránku z hotových sekcí s ukázkovými texty a otevře ji v builderu.',
    'A template is a clean skeleton – colours, fonts and spacing come from your design system. It goes into the draft of the part: adjust it in the builder and publish it; until then visitors see the published version.' => 'Šablona je čistá kostra – barvy, písma a mezery si bere z vašeho design systému. Uloží se do konceptu části: upravte ji v builderu a publikujte; do té doby návštěvníci vidí publikovanou podobu.',
    'A testimonial the person sent stays in References – remove it there if they ask.' => 'Reference, kterou člověk poslal, zůstává v Referencích – smažte ji tam, pokud o to požádá.',
    'A text fact cannot begin with an address scheme other than http, https, mailto or tel (javascript:, data:…). For a link use the type web address.' => 'Textový údaj nesmí začínat schématem adresy jiným než http, https, mailto nebo tel (javascript:, data:…). Pro odkaz použijte typ webová adresa.',
    'A text page without the builder.' => 'Textová stránka bez builderu.',
    'A thin bar with the phone and e-mail above the logo and the menu.' => 'Tenká lišta s telefonem a e-mailem nad logem a menu.',
    'A thin horizontal line between parts of the content.' => 'Tenká vodorovná čára mezi částmi obsahu.',
    'A three-letter code (EUR, CZK, USD). Without it the price is not passed on.' => 'Třípísmenný kód (EUR, CZK, USD). Bez něj se cena nepředá.',
    'A title and an intro sentence for the top of a subpage.' => 'Nadpis a úvodní věta na začátek podstránky.',
    'A token works without the password and without two-factor sign-in. If you are changing the password because you suspect misuse, leave this ticked and create the connection again afterwards.' => 'Token funguje bez hesla i bez dvoufázového přihlášení. Měníte-li heslo kvůli podezření na zneužití, nechte zaškrtnuté a napojení pak vytvořte znovu.',
    'A translation into this language already exists – here it is.' => 'Překlad do tohoto jazyka už existuje – tady je.',
    'A two-minute video says more than a long text. Paste the video address in the Content panel.' => 'Dvouminutové video řekne víc než dlouhý text. Vložte adresu videa v panelu Obsah.',
    'A variant applies only to the selected pages; elsewhere the default stays. For example a landing page with a simpler header. If you leave the variant empty in the builder, the page will have no header (footer).' => 'Varianta platí jen na vybraných stránkách, jinde zůstává výchozí podoba. Třeba landing page s jednodušším záhlavím. Když v builderu necháte variantu prázdnou, stránka záhlaví (patičku) mít nebude.',
    'A versatile services website: benefits, numbers, testimonials, news.' => 'Univerzální web služeb: výhody, čísla, reference, novinky.',
    'A visitor reaches the page you choose. Counted only for visitors who accepted the cookie bar, because the browser has to remember the variant between the two pages.' => 'Návštěvník dosáhne vámi zvolené stránky. Počítá se jen u návštěvníků, kteří přijali cookie lištu, protože si prohlížeč musí verzi mezi oběma stránkami pamatovat.',
    'A webhook sends data to another service the moment something happens on the site – a new enquiry to a CRM or Slack, a published news item to Make, Zapier or n8n, which then share it on social networks.' => 'Webhook pošle data jiné službě ve chvíli, kdy se na webu něco stane – novou poptávku do CRM nebo Slacku, vydanou novinku do Make, Zapieru nebo n8n, které ji pak sdílejí na sociální sítě.',
    'A website search field – for the header, the 404 page or a listing.' => 'Pole pro hledání na webu – do záhlaví, na stránku 404 nebo k výpisu.',
    'A whole page' => 'Celá stránka',
    'A window over the page for a newsletter sign-up, a download, an announcement or an offer. You build the content in the builder and set when and where it shows. The counters work without cookies.' => 'Okno přes stránku pro přihlášení k newsletteru, materiál ke stažení, oznámení nebo akci. Obsah poskládáte v builderu, v nastavení určíte, kdy a kde se ukáže. Počitadla fungují bez cookies.',
    'A window over the page – opened by a button linking to the window\'s anchor, or automatically after a while.' => 'Okno přes stránku – otevře ho tlačítko s odkazem na kotvu okna, nebo samo po chvíli.',
    'A wrapper around the news item – a call to action or more news below the text, for example.' => 'Obálka kolem textu novinky – třeba výzva k akci nebo další novinky pod textem.',
    'A wrapper around the news list, category, tag and search results.' => 'Obálka kolem výpisu novinek, kategorie, štítku a hledání.',
    'A wrapper around the page-not-found message – e.g. with links onward.' => 'Obálka kolem hlášení, že stránka neexistuje – třeba s odkazy dál.',
    'A year of free service' => 'Rok servisu zdarma',
    'A/B tests: automatic promotion of a winner' => 'A/B testy: automatické povýšení vítěze',
    'A/B tests: visitors see one of two versions of some content, chosen at random on every page view; nothing is stored in their browser. Only after they accept the cookie bar is the version remembered in the browser (local storage, key tl-x) so that the page does not change between visits. Views and goals (a form sent, a click, a booking, a page reached) are counted per version and day, without any data about the visitor.' => 'A/B testy: návštěvníci vidí jednu ze dvou verzí některého obsahu, vybranou náhodně při každém zobrazení stránky; v prohlížeči se nic neukládá. Teprve po souhlasu v cookie liště si prohlížeč verzi pamatuje (local storage, klíč tl-x), aby se stránka mezi návštěvami neměnila. Zobrazení a cíle (odeslaný formulář, klik, rezervace, dosažená stránka) se počítají po verzích a dnech, bez jakýchkoli údajů o návštěvníkovi.',
    'AI connection' => 'Napojení na AI',
    'AI connections' => 'Napojení AI',
    'AI search engines and assistants' => 'AI vyhledávače a asistenti',
    'AI sessions' => 'Relace AI',
    'AI settings' => 'Nastavení AI',
    'API key' => 'Klíč API',
    'API token' => 'API token',
    'About' => 'O mně',
    'About a quarter of the tools are listed – pages, the builder, collections, media, the look and the audit. Claude finds every other tool it may use (news, redirects, settings, bookings, newsletters…) when it needs it, with the same limits, change log and undo. Much less to load in every conversation.' => 'Nabízí se asi čtvrtina nástrojů – stránky, builder, kolekce, média, vzhled a audit. Všechny ostatní nástroje, které smí použít (novinky, přesměrování, nastavení, rezervace, newslettery…), si Claude najde, když je potřebuje, se stejnými limity, záznamem změn a vrácením. V každé konverzaci je co načítat mnohem méně.',
    'About the author' => 'O autorovi',
    'About the company' => 'O firmě',
    'About us' => 'O nás',
    'About us, Services, Contact – and pick the home page in Settings.' => 'O nás, Služby, Kontakt – a v Nastavení vyberte, která bude úvodní.',
    'Accept' => 'Přijmout',
    'Accept all' => 'Přijmout vše',
    'Accept forms when the provider is down' => 'Přijmout formuláře, když poskytovatel neodpovídá',
    'Access' => 'Přístup',
    'Access to areas' => 'Přístup do sekcí',
    'Access to personal data: %d administration account(s); two-step sign-in %s.' => 'Přístup k osobním údajům: %d účet(ů) administrace; dvoufázové přihlášení %s.',
    'Accessibility' => 'Přístupnost',
    'Accessibility check' => 'Kontrola přístupnosti',
    'Accessibility options' => 'Možnosti přístupnosti',
    'Accessibility statement' => 'Prohlášení o přístupnosti',
    'Accessibility toolbar for visitors' => 'Lišta přístupnosti pro návštěvníky',
    'Accessibility toolbar: text size, contrast, underlined links, reduced motion (local storage)' => 'Lišta přístupnosti: velikost písma, kontrast, podtržené odkazy, omezený pohyb (úložiště prohlížeče)',
    'Account' => 'Účet',
    'Account and tools' => 'Účet a nástroje',
    'Account: %s' => 'Účet: %s',
    'Accounts and access' => 'Účty a přístup',
    'Acknowledgement e-mail' => 'E-mail s potvrzením přijetí',
    'Action' => 'Akce',
    'Actions' => 'Akce',
    'Active' => 'Aktivní',
    'Active redirects' => 'Aktivní přesměrování',
    'Add' => 'Přidat',
    'Add a Form element in the page builder (or the ready-made Enquiry form section) – it will appear here with its answers.' => 'Přidejte v editoru stránky prvek Formulář (nebo hotovou sekci Poptávkový formulář) – objeví se tu i s odpověďmi.',
    'Add a Form element in the page builder (or the ready-made Enquiry form section) – submitted messages will appear here and arrive by email.' => 'Přidejte na web prvek Formulář v builderu stránek (nebo hotovou sekci Poptávkový formulář) – odeslané zprávy se objeví tady a přijdou i e-mailem.',
    'Add a description for blind visitors (alt text) to the images: what the image shows.' => 'U obrázků doplňte popis pro nevidomé (alt): co na obrázku je.',
    'Add a field' => 'Přidat pole',
    'Add a focus keyword below to get a score.' => 'Přidejte níže klíčové slovo a stránka dostane hodnocení.',
    'Add a passkey from this device' => 'Přidat klíč z tohoto zařízení',
    'Add a service' => 'Přidat službu',
    'Add a service (what and how long) and a person who offers it. Then put the Booking element on a page – visitors pick a service, a person, a day and a free time.' => 'Přidejte službu (co a jak dlouho) a člověka, který ji nabízí. Pak vložte na stránku prvek Rezervace – návštěvníci si vyberou službu, člověka, den a volný čas.',
    'Add a sign-up form' => 'Vložit přihlašovací formulář',
    'Add a site' => 'Přidat web',
    'Add a type' => 'Přidat typ',
    'Add as keyword' => 'Přidat jako klíčové slovo',
    'Add at least one product to the enquiry.' => 'Přidejte do poptávky aspoň jeden produkt.',
    'Add group' => 'Přidat skupinu',
    'Add images (JPG, PNG, WebP)' => 'Přidat obrázky (JPG, PNG, WebP)',
    'Add item' => 'Přidat položku',
    'Add language versions in Settings → General; this screen then shows which translations are missing.' => 'Jazykové verze přidáte v Nastavení → Základní; tato obrazovka pak ukáže, které překlady chybí.',
    'Add our new colleague to the team page – the photo and a short bio are attached.' => 'Přidejte novou kolegyni na stránku týmu – fotku a krátký medailonek přikládám.',
    'Add page' => 'Přidat stránku',
    'Add people first.' => 'Nejdřív přidejte lidi.',
    'Add photos in the Content panel.' => 'Přidejte fotky v panelu Obsah.',
    'Add row' => 'Přidat řádek',
    'Add services first.' => 'Nejdřív přidejte služby.',
    'Add social networks under Settings.' => 'Sociální sítě doplníte v Nastavení.',
    'Add the Newsletter sign-up element to a page. Only people who confirm by the link in the e-mail count as subscribers.' => 'Vložte na stránku prvek Přihlášení k newsletteru. Za odběratele se počítají jen lidé, kteří přihlášení potvrdí odkazem v e-mailu.',
    'Add the exception' => 'Přidat výjimku',
    'Add the first item – then put it on the site with the Collection list element in the builder.' => 'Přidejte první položku – na web ji pak dostanete prvkem Výpis kolekce v builderu.',
    'Add the reply' => 'Přidat odpověď',
    'Add them in the news editor in the Tags field. Here you can then merge them and turn them into topic pages.' => 'Přidáte je v editoru novinky v poli Štítky. Tady je pak půjde slučovat a měnit na stránky témat.',
    'Add to calendar' => 'Přidat do kalendáře',
    'Add to enquiry' => 'Přidat do poptávky',
    'Add to enquiry – shows on the pages and cards of a products collection.' => 'Přidat do poptávky – ukáže se na stránkách a kartách kolekce produktů.',
    'Add user' => 'Přidat uživatele',
    'Add variant' => 'Přidat variantu',
    'Add what makes you different and what you are proud of.' => 'Doplňte, čím se lišíte od ostatních a na co jste hrdí.',
    'Add what the site does not know about (paper files, accounting, other systems) and keep the record with your documentation; print it from the browser.' => 'Doplňte, o čem web neví (papírové spisy, účetnictví, další systémy), a uložte záznam ke své dokumentaci; vytisknete ho z prohlížeče.',
    'Add-on' => 'Doplněk',
    'Add-ons' => 'Doplňky',
    'Add-ons are code from other developers. Copy an add-on into the folder extensions/<name>/ on your hosting and switch it on here. An add-on runs with the same rights as Talea – switch on only code you trust, from a source you know. Talea never uploads or downloads add-ons by itself.' => 'Doplňky jsou kód jiných vývojářů. Doplněk zkopírujte na hostingu do složky extensions/<název>/ a zapněte ho tady. Doplněk běží se stejnými právy jako Talea – zapínejte jen kód, kterému věříte, ze zdroje, který znáte. Talea sama doplňky nikdy nenahrává ani nestahuje.',
    'Add-ons are switched off in config.php (safe mode) – none is loaded.' => 'Doplňky jsou vypnuté v config.php (nouzový režim) – žádný se nenačítá.',
    'Add-ons do not run in the public demo.' => 'Ve veřejné ukázce doplňky neběží.',
    'Added' => 'Přidáno',
    'Added to the enquiry.' => 'Přidáno do poptávky.',
    'Address' => 'Adresa',
    'Address and contact' => 'Adresa a kontakt',
    'Address and contacts on the left, opening hours on the right.' => 'Adresa a kontakty vlevo, otevírací doba vpravo.',
    'Address contains' => 'Adresa obsahuje',
    'Address contains:' => 'Adresa obsahuje:',
    'Address for the client:' => 'Adresa pro klienta:',
    'Address of the booking page, form or track (copied from the service)' => 'Adresa rezervační stránky, formuláře nebo skladby (zkopírovaná ze služby)',
    'Address of the link or button' => 'Adresa odkazu nebo tlačítka',
    'Address of the old site' => 'Adresa starého webu',
    'Address of the page it is about' => 'Adresa stránky, které se to týká',
    'Address of the place' => 'Adresa místa',
    'Address of the site' => 'Adresa webu',
    'Address or coordinates (empty = company address from Settings)' => 'Adresa nebo souřadnice (prázdné = adresa firmy z Nastavení)',
    'Address, location, phone, e-mail, opening hours, photo and a page for each branch or store; the Store locator element lists them with search, the nearest one and a map.' => 'Adresa, poloha, telefon, e-mail, otevírací doba, fotka a stránka pro každou pobočku nebo prodejnu; prvek Vyhledávač poboček je vypíše s hledáním, nejbližší pobočkou a mapou.',
    'Address, order and visibility' => 'Adresa, pořadí a zobrazení',
    'Address, phone and opening hours appear on the contact page, in the footer and to search engines.' => 'Adresa, telefon a otevírací doba se ukážou na kontaktu, v patičce i vyhledávačům.',
    'Address, phone, e-mail and opening hours.' => 'Adresa, telefon, e-mail a otevírací doba.',
    'Address, phone, email, company ID, opening hours, map, copyright or social networks from Settings.' => 'Adresa, telefon, e-mail, IČO, otevírací doba, mapa, copyright nebo sociální sítě z Nastavení.',
    'Address: %s' => 'Adresa: %s',
    'Addresses' => 'Adresy',
    'Addresses another language version already had (%s)' => 'Adresy, které už měla jiná jazyková verze (%s)',
    'Addresses blocked for a while by the firewall' => 'Adresy dočasně zablokované firewallem',
    'Addresses from the Newsletter sign-up element. Only people who confirmed by the link in the e-mail count as subscribers. Send them news under Newsletters, or with your own tool – the export includes the unsubscribe link.' => 'Adresy z prvku Odběr novinek. Za odběratele se počítá, kdo přihlášení potvrdil odkazem v e-mailu. Novinky jim pošlete v Newsletterech, nebo svým nástrojem – export obsahuje i odkaz na odhlášení.',
    'Addresses from the Newsletter sign-up element. Only people who confirmed by the link in the e-mail count as subscribers. Send with your own tool – the export includes the unsubscribe link.' => 'Adresy z prvku Odběr novinek. Za odběratele se počítá, kdo přihlášení potvrdil odkazem v e-mailu. Rozesílejte svým nástrojem – export obsahuje i odkaz na odhlášení.',
    'Addresses on your site that repeatedly ended with “page not found” this week: %d. Visitors came from an old link or a typo – send each one to the right page with a redirect, or ignore it.' => 'Adresy na vašem webu, které tento týden opakovaně skončily „stránka nenalezena“: %d. Návštěvníci přišli ze starého odkazu nebo s překlepem – každou pošlete přesměrováním na správnou stránku, nebo ji ignorujte.',
    'Addresses that visitors repeatedly could not find show up here.' => 'Adresy, které návštěvníci opakovaně nenašli, se zobrazí tady.',
    'Addresses visitors asked for that do not exist. Redirect the ones people really use; ignore the rest.' => 'Adresy, které návštěvníci požadovali a neexistují. Přesměrujte ty, které lidé opravdu používají, zbytek ignorujte.',
    'Addresses visitors could not find (404)' => 'Adresy, které návštěvníci nenašli (404)',
    'Addresses waiting for a decision were removed; ignored ones stay ignored.' => 'Adresy čekající na rozhodnutí byly odstraněny, ignorované zůstávají ignorované.',
    'Adds the collections, facts and checks such a business needs.' => 'Přidá kolekce, fakta a kontroly, které takový podnik potřebuje.',
    'Adds the fact to the company in the structured data (schema.org) search engines and AI assistants read.' => 'Přidá fakt k firmě do strukturovaných dat (schema.org), která čtou vyhledávače a AI asistenti.',
    'Admin menu' => 'Menu administrace',
    'Administration' => 'Správa',
    'Administration language' => 'Jazyk administrace',
    'Administration of the site' => 'Administrace webu',
    'Administrator' => 'Správce',
    'Advanced' => 'Pokročilé',
    'Advertising pixels' => 'Reklamní pixely',
    'Advertising pixels (remarketing)' => 'Reklamní pixely (remarketing)',
    'Advertising, SEO offers, nonsense, scams.' => 'Reklama, nabídky SEO, nesmysly, podvody.',
    'Advertising: shows and measures ads' => 'Reklama: zobrazuje a měří reklamy',
    'Advertising: tells visitors apart across sites' => 'Reklama: rozlišuje návštěvníky napříč weby',
    'After a number of pages in the visit' => 'Po zadaném počtu stránek v návštěvě',
    'After a number of seconds' => 'Po zadaném počtu sekund',
    'After a number of seconds without activity' => 'Po zadaném počtu sekund nečinnosti',
    'After a sign-up is confirmed (double opt-in), the site adds the address to the list in your service and removes it after unsubscribing. Sending, deliverability and unsubscribing from e-mails stay with the service. The transfer runs in the background – visitors do not wait.' => 'Po potvrzení odběru (double opt-in) přidá web adresu do seznamu ve vaší službě, po odhlášení ji odebere. Rozesílání, doručitelnost a odhlašování z e-mailů zůstávají u služby. Přenos běží na pozadí – návštěvník nečeká.',
    'After allowing it you return to the application at %s. You can revoke the connection at any time in My account → Connected applications.' => 'Po povolení se vrátíte do aplikace na adrese %s. Připojení kdykoli zrušíte v Můj účet → Připojené aplikace.',
    'After booking, go to a page (empty = thank-you message in place of the form; a request that still needs confirmation always shows its message)' => 'Po rezervaci přejít na stránku (prázdné = poděkování místo formuláře; žádost, která ještě čeká na potvrzení, vždy ukáže svou zprávu)',
    'After consent to analytics' => 'Po souhlasu s měřením',
    'After consent to analytics or marketing' => 'Po souhlasu s měřením nebo marketingem',
    'After consent to marketing' => 'Po souhlasu s marketingem',
    'After scrolling part of the page' => 'Po odrolování části stránky',
    'After sending, e-mail this file to the visitor (a file from Media; the form needs an e-mail field). A file in Media stays reachable by its own address – this stops casual sharing, not a determined person.' => 'Po odeslání poslat návštěvníkovi e-mailem tento soubor (soubor z Médií; formulář potřebuje pole e-mail). Soubor v Médiích zůstává dostupný na své vlastní adrese – brání to běžnému sdílení, ne odhodlanému člověku.',
    'After sending, go to a page (empty = thank-you message in place of the form)' => 'Po odeslání přejít na stránku (prázdné = poděkování na místě formuláře)',
    'After that period' => 'Po uplynutí této doby',
    'After the number (e.g. “ %”, “+”, “ years”)' => 'Za číslem (např. „ %“, „+“, „ let“)',
    'After this day the item hides itself. Empty = always.' => 'Po tomto dni se položka sama skryje. Prázdné = platí stále.',
    'After this day the news item hides itself. Empty = always.' => 'Po tomto dni se novinka sama skryje. Prázdné = platí stále.',
    'After this day the page hides itself. Empty = always.' => 'Po tomto dni se stránka sama skryje. Prázdné = platí stále.',
    'After this day the page hides itself. Leave empty to keep it visible.' => 'Po tomto dni se stránka sama skryje. Nechte prázdné, aby zůstala viditelná.',
    'After this day the pop-up switches itself off. Empty = always.' => 'Po tomto dni se pop-up okno samo vypne. Prázdné = platí stále.',
    'After “visible until” the page hides itself; on “review by” the site audit reminds you to check it.' => 'Po dni „viditelné do“ se stránka sama skryje; v den „zkontrolovat do“ vám audit webu připomene, abyste ji zkontrolovali.',
    'Alert e-mails' => 'Upozornění e-mailem',
