    'All looks – the ones that fit %s best come first. Open one to try its colours and fonts on your site.' => 'Všechny vzhledy – nejdřív ty, které se nejlépe hodí k tématu %s. Otevřete jeden a vyzkoušejte jeho barvy a písma na svém webu.',
