    'Allow the site in search engines' => 'Web smí být ve vyhledávačích',
    'Almost on the first page' => 'Téměř na první stránce',
    'Already redirected' => 'Již přesměrováno',
    'Also has access to: %s.' => 'Dál má přístup k: %s.',
    'Also overwrite later changes' => 'Přepsat i pozdější změny',
    'Also switches on and prepares: %s.' => 'Navíc zapne a připraví: %s.',
    'Also:' => 'Dále:',
    'Alternating image and text' => 'Obrázek a text střídavě',
    'Always-on core: Pages, Collections, Media, Site appearance, Site parts, Menu, Components, Pop-ups, Users and roles, Import and export, Change log and Settings.' => 'Vždy zapnuté jádro: Stránky, Kolekce, Média, Vzhled webu, Části webu, Menu, Komponenty, Pop-up okna, Uživatelé a role, Import a export, Protokol změn a Nastavení.',
    'Always-on core: Pages, Collections, Media, Site appearance, Site parts, Menu, Components, Users and Settings.' => 'Vždy zapnuté jádro: Stránky, Kolekce, Média, Vzhled webu, Části webu, Menu, Komponenty, Uživatelé a Nastavení.',
    'Amazon SES region' => 'Oblast Amazon SES',
    'Amenities' => 'Vybavení',
    'An ALL-CAPS headline is hard to read and screen readers may spell it out.' => 'Titulek psaný VERZÁLKAMI se špatně čte a čtečky ho mohou hláskovat.',
    'An H1–H6 heading or a highlighted line.' => 'Nadpis H1–H6 nebo zvýrazněný řádek.',
    'An account not used for %d days was suspended (%s).' => 'Účet nepoužitý %d dní byl pozastaven (%s).',
    'An account of the administration (%s) – change or remove it in Users; it is not erased here.' => 'Účet administrace (%s) – změňte nebo smažte ho v Uživatelích; zde se nemaže.',
    'An address from Make, Zapier, IFTTT or n8n. When a news item is published, the system sends it the title, lead, address and image – the service then shares it on Facebook, X, Mastodon, Slack and so on.' => 'Adresa ze služby Make, Zapier, IFTTT nebo n8n. Po vydání novinky na ni systém pošle titulek, perex, adresu a obrázek – služba je pak sama sdílí na Facebook, X, Mastodon, do Slacku apod.',
    'An address that asks for /wp-login.php, /.env and similar addresses of other systems 5 times in an hour is blocked for 24 hours.' => 'Adresa, která se během hodiny pětkrát zeptá na /wp-login.php, /.env a podobné adresy jiných systémů, se na 24 hodin zablokuje.',
    'An author usually has only News, an editor all content sections, an administrator everything. With a custom role, the role\'s sections apply.' => 'Autor má běžně jen Novinky, editor všechny obsahové sekce, správce vše. U vlastní role platí sekce z role.',
    'An e-mail address or an https:// page where people report security problems of this site. It is published at /.well-known/security.txt (RFC 9116); empty = no file.' => 'E-mailová adresa nebo stránka https://, kam lidé hlásí bezpečnostní problémy tohoto webu. Zveřejní se v /.well-known/security.txt (RFC 9116); prázdné = soubor nevznikne.',
    'An e-mail field with subscription confirmation – you will find the addresses under Subscribers in the administration.' => 'Pole pro e-mail s potvrzením odběru – adresy najdete v administraci v Odběratelích.',
    'An editor or site administrator publishes the news item.' => 'Novinku vydá editor nebo správce webu.',
    'An editorial reading layout: warm paper, a serif text face and a narrow text column. For blogs and magazines.' => 'Redakční čtenářský layout: teplý papír, patkové písmo a úzký sloupec textu. Pro blogy a magazíny.',
    'An elegant look, clients, service packages and the team.' => 'Elegantní vzhled, klienti, balíčky služeb a tým.',
    'An embedded frame (iframe) has no title.' => 'Vložený rámec (iframe) nemá titulek.',
    'An embedded video or frame has no name (title attribute).' => 'Vložené video nebo rámec nemá název (atribut title).',
    'An empty field means the same text as in the default language.' => 'Prázdné pole znamená stejný text jako ve výchozím jazyce.',
    'An enquiry or question – submitted messages are in Enquiries and arrive by email.' => 'Poptávka nebo dotaz – odeslané zprávy najdete v Poptávkách a přijdou i e-mailem.',
    'An estimate from your answers – the final price follows in our reply.' => 'Odhad podle vašich odpovědí – konečnou cenu pošleme v odpovědi.',
    'An exact address wins over the other kinds. With a regular expression, $1 in the target is the first captured part. Starts with: a target ending in a slash keeps the rest of the address.' => 'Přesná adresa má přednost před ostatními druhy. U regulárního výrazu je $1 v cíli první zachycená část. Začíná na: cíl končící lomítkem převezme zbytek adresy.',
    'An existing customer with a problem or question.' => 'Stávající zákazník s problémem nebo dotazem.',
    'An expired token stops working on its own; you then create a new one. A token nobody uses for %d days is reported in System status.' => 'Token po vypršení přestane fungovat sám; pak si vytvoříte nový. Token, který nikdo %d dní nepoužije, hlásí Stav systému.',
    'An hour with an expert at your place or online.' => 'Hodina s odborníkem u vás nebo online.',
    'An icon shows before the text. The description and group columns (a group inside a submenu with its own items) appear in a mega menu – the Navigation element with “Submenu as a wide panel”.' => 'Ikona se ukáže před textem. Popis a sloupce skupin (skupina uvnitř podmenu s vlastními položkami) se zobrazí v mega menu – prvek Navigace s volbou „Podmenu jako široký panel“.',
    'An image and text about who you are and how you started.' => 'Obrázek a text o tom, kdo jste a jak jste začínali.',
    'An image in the text has no description for blind visitors (alt).' => 'Obrázek v textu nemá popis pro nevidomé (alt).',
    'An image with numbered points – a tap on a point shows its label and text (a product, a floor plan, a map of premises).' => 'Obrázek s číslovanými body – klepnutí na bod ukáže jeho název a text (produkt, půdorys, plán areálu).',
    'An introduction and a button, no news – for an offer, an event or an invitation.' => 'Úvod a tlačítko, bez příspěvků – pro nabídku, akci nebo pozvánku.',
    'An invitation has been sent to %s.' => 'Pozvánka byla odeslána na %s.',
    'An invitation needs an e-mail.' => 'Pozvánka potřebuje e-mail.',
    'An invitation to join the team with open positions and a link.' => 'Pozvánka do týmu s volnými pozicemi a odkazem.',
    'An item of another collection links two collections – a person to a branch, a reference to a service: choose the type and the linked collection. {{key}} shows the linked item\'s name, {{key_url}} its page. On the page of the linked item, a Collection list filtered by the field with the value {{seo}} lists everything linked to it.' => 'Položka jiné kolekce propojí dvě kolekce – člověka s pobočkou, referenci se službou: zvolte typ a propojenou kolekci. {{klic}} ukáže název propojené položky, {{klic_url}} její stránku. Na stránce propojené položky vypíše Výpis kolekce filtrovaný podle pole s hodnotou {{seo}} všechno, co je s ní propojené.',
    'An item points at a page that no longer exists.' => 'Položka vede na stránku, která už neexistuje.',
    'An item without a link that only opens a submenu' => 'Položka bez odkazu, která jen otevírá podmenu',
    'An outside service was connected.' => 'Byla napojena externí služba.',
    'Analytics' => 'Měření',
    'Analytics and tags' => 'Analytika a značky',
    'Analytics is turned off. Turn it on in Settings → Analytics.' => 'Měření je vypnuté. Zapnete ho v Nastavení → Měření.',
    'Analytics or marketing codes run without a cookie bar – visitors in the EU must consent first.' => 'Kódy analytiky nebo marketingu běží bez cookie lišty – návštěvníci v EU musí nejdřív souhlasit.',
    'Analytics – anonymous traffic measurement' => 'Analytické – anonymní měření návštěvnosti',
    'Anchor (id for a #… link)' => 'Kotva (id pro odkaz #…)',
    'And the second part here. On phones the columns stack by themselves.' => 'A sem druhou. Na telefonu se sloupce samy seřadí pod sebe.',
    'Announcement' => 'Oznámení',
    'Announcement bar' => 'Oznamovací lišta',
    'Anonymise' => 'Anonymizovat',
    'Anonymised' => 'Anonymizováno',
    'Another experiment is running on this page and covers the same content. End it first.' => 'Na této stránce už běží jiný experiment se stejným obsahem. Nejdřív ho ukončete.',
    'Another page already uses this focus keyword.' => 'Toto klíčové slovo už používá jiná stránka.',
    'Another redirect already uses this old address.' => 'Jiné přesměrování už tuto starou adresu používá.',
    'Another service via a webhook (Make, Zapier, n8n)' => 'Jiná služba přes webhook (Make, Zapier, n8n)',
    'Another user already has this username.' => 'Toto přihlašovací jméno už používá jiný uživatel.',
    'Another window already uses the address “%s”.' => 'Adresu „%s“ už používá jiné okno.',
    'Answer' => 'Odpověď',
    'Answer a few questions and get a look, pages with text and what your kind of business needs – all as drafts. Texts need your own AI key.' => 'Odpovězte na pár otázek a získáte vzhled, stránky s texty a to, co váš obor potřebuje – vše jako koncepty. Texty vyžadují váš vlastní klíč AI.',
    'Answer a few questions and the assistant prepares a first version of your site: a look, the pages with their text and what your kind of business needs. Everything arrives as a draft – nothing is published until you do it.' => 'Odpovězte na pár otázek a asistent připraví první verzi vašeho webu: vzhled, stránky s texty a to, co váš obor potřebuje. Vše přijde jako koncept – nic se nezveřejní, dokud to neuděláte vy.',
    'Answered' => 'Zodpovězeno',
    'Answers' => 'Odpovědi',
    'Answers to this form will appear here and arrive by email.' => 'Odpovědi na tento formulář se objeví tady a přijdou e-mailem.',
    'Answers: %s' => 'Odpovědi: %s',
    'Anyone available' => 'Kdokoli volný',
    'Anyone who must have it and has not turned it on yet can only reach My account after signing in until they set it up.' => 'Kdo ho povinně má a ještě si ho nezapnul, se po přihlášení dostane jen do Můj účet, dokud ho nenastaví.',
    'Anyone with the link can see the draft without signing in – including changes you make later. Search engines do not index it.' => 'Kdo dostane odkaz, uvidí koncept bez přihlášení – i změny, které uděláte později. Vyhledávače ho neindexují.',
    'Anyone with the private link' => 'Kdokoli se soukromým odkazem',
    'Anything else.' => 'Cokoli jiného.',
    'Appearance' => 'Vzhled',
    'Applications sent from the pages of a Job openings collection carry CVs and are usually kept only for a limited time after the selection. 0 = like other enquiries.' => 'Žádosti odeslané ze stránek kolekce Volná místa obsahují životopisy a obvykle se uchovávají jen omezenou dobu po výběrovém řízení. 0 = jako ostatní poptávky.',
    'Applications to job openings arrive as enquiries from the job pages, with CVs as attachments.' => 'Reakce na pracovní pozice přicházejí jako poptávky ze stránek pozic, s CV jako přílohami.',
    'Applied' => 'Použité',
    'Applied as a draft look: you preview the whole site and publish it yourself.' => 'Použije se jako koncept vzhledu: celý web si prohlédnete a zveřejníte sami.',
    'Applies for a job.' => 'Hlásí se na pracovní místo.',
    'Apply' => 'Použít',
    'Apply a blueprint' => 'Použít oborový plán',
    'Apply as a draft' => 'Použít jako koncept',
    'Apply for this job' => 'Reagovat na pozici',
    'Apply the blueprint %s? It creates its collections with hidden list pages and adds its facts, questions and checks. You can take it off again.' => 'Použít oborový plán %s? Vytvoří své kolekce se skrytými stránkami výpisu a přidá svá fakta, otázky a kontroly. Kdykoli ho můžete zase odebrat.',
    'Apply the result' => 'Použít výsledek',
    'Appointment' => 'Termín',
    'Appointments this month' => 'Termíny v tomto měsíci',
    'Apps connected to this account (the Claude connector) are disconnected with the new password – connect them again in the Claude app.' => 'Aplikace připojené k tomuto účtu (konektor Claude) se novým heslem odpojí – připojte je znovu v aplikaci Claude.',
    'April' => 'duben',
    'Arabic' => 'arabské',
    'Archive' => 'Archiv',
    'Archived reports' => 'Uložené zprávy',
    'Area' => 'Oblast',
    'Area served' => 'Oblast působnosti',
    'Arrow' => 'Šipka',
    'Arrow position' => 'Umístění šipek',
    'Art' => 'Umění',
    'Article' => 'Článek',
    'As Markdown (to copy)' => 'Jako Markdown (ke zkopírování)',
    'Ask AI' => 'Zeptejte se AI',
    'Ask Claude to make a blueprint for your kind of business: it asks you what it needs to know, shows you the draft and applies it only when you agree. In the Claude app, the prompt is called draft_blueprint.' => 'Požádejte Clauda, ať pro váš obor oborový plán připraví: zeptá se, co potřebuje vědět, ukáže vám návrh a použije ho, až když souhlasíte. V aplikaci Claude se ta výzva jmenuje draft_blueprint.',
    'Ask Claude to translate it' => 'Požádat Clauda o překlad',
    'Ask for a testimonial by e-mail' => 'Požádat o referenci e-mailem',
    'Asked for a review by %s.' => 'Žádá o kontrolu do %s.',
    'Asks for a review on this day.' => 'V tento den žádá o kontrolu.',
    'Aspect ratio' => 'Poměr stran',
    'Assistant' => 'Asistent',
    'At a glance' => 'Na první pohled',
    'At least %d views of each version' => 'Aspoň %d zobrazení každé verze',
    'At least %d%% probability that one version is better' => 'Aspoň %d %% pravděpodobnost, že je jedna verze lepší',
    'At least 10 characters.' => 'Alespoň 10 znaků.',
    'At least 10 characters. Two-factor sign-in stays on.' => 'Alespoň 10 znaků. Dvoufázové přihlášení zůstává zapnuté.',
    'At least one outgoing link is followed by search engines.' => 'Alespoň jeden odchozí odkaz vyhledávače sledují.',
    'At most %d characters; a link counts as %d.' => 'Nejvýš %d znaků; odkaz se počítá jako %d.',
    'Attach files' => 'Přiložit soubory',
    'Attachments' => 'Přílohy',
    'Attributes (name=value, one per line; data-…, aria-…, title, lang, role, rel)' => 'Atributy (název=hodnota, na řádek; data-…, aria-…, title, lang, role, rel)',
    'August' => 'srpen',
    'Author' => 'Autor',
    'Authors' => 'Autoři',
    'Automatic backup %s' => 'Automatická záloha %s',
    'Automatic backup once a week' => 'Automatická záloha jednou týdně',
    'Automatic backups' => 'Automatické zálohy',
    'Automatic suspension' => 'Automatické pozastavení',
    'Automatic: guardrails met after %d days (%d and %d views, probability %d%%, uplift %d%%).' => 'Automaticky: pojistky splněny po %d dnech (%d a %d zobrazení, pravděpodobnost %d %%, zlepšení %d %%).',
    'Availability' => 'Dostupnost',
    'Available until' => 'Dostupné do',
    'Available until (empty = no end)' => 'Dostupné do (prázdné = bez konce)',
    'Average place in search' => 'Průměrná pozice ve vyhledávání',
    'Average position' => 'Průměrná pozice',
    'Awaiting publication' => 'Čekají na vydání',
    'Award' => 'Ocenění',
    'B applied' => 'B použito',
    'B beats A with a probability of %s; the expected uplift is %s (likely between %s and %s). The result can be trusted.' => 'B překonává A s pravděpodobností %s; očekávané zlepšení je %s (pravděpodobně mezi %s a %s). Výsledku lze věřit.',
    'B is better: %d%% probability' => 'B je lepší: pravděpodobnost %d %%',
    'B must also be at least %d%% better to replace A' => 'B musí být navíc aspoň o %d %% lepší, aby nahradilo A',
    'B replaces the original and is published. The previous version stays in the page’s versions and you can undo the promotion here.' => 'B nahradí původní verzi a je zveřejněna. Předchozí verze zůstane ve verzích stránky a povýšení můžete tady vrátit.',
    'B replaces the original in the page’s draft; someone who may publish has to publish it.' => 'B nahradí původní verzi v konceptu stránky; zveřejnit ji musí někdo s oprávněním publikovat.',
    'Back' => 'Zpět',
    'Back to %s' => 'Zpět na %s',
    'Back to Import and export' => 'Zpět na Import a export',
    'Back to automatic menu' => 'Vrátit na automatické menu',
    'Back to draft' => 'Zpět do konceptu',
    'Back to editing' => 'Zpět k úpravám',
    'Back to element' => 'Zpět na prvek',
    'Back to enquiries' => 'Zpět na poptávky',
    'Back to items' => 'Zpět na položky',
    'Back to media' => 'Zpět na média',
    'Back to news' => 'Zpět na novinky',
    'Back to overview' => 'Zpět na přehled',
    'Back to pages' => 'Zpět na stránky',
    'Back to roles' => 'Zpět na role',
    'Back to sign-in' => 'Zpět na přihlášení',
    'Back to the administration' => 'Zpět do administrace',
    'Back to the appearance' => 'Zpět na vzhled webu',
    'Back to the dashboard' => 'Zpět na hlavní stránku administrace',
