    'Before and after' => 'Před a po',
    'Before anyone is notified, the assistant reads each new enquiry. Spam is kept under the Spam filter in Enquiries and sends no e-mail, webhook or delivery; the sender sees the usual thank-you. If the assistant cannot be reached, the enquiry goes through as usual. The text of each enquiry is sent to the AI provider – mention it in your privacy policy.' => 'Než kdokoli dostane upozornění, asistent si každou novou poptávku přečte. Spam zůstane pod filtrem Spam v Poptávkách a neodejde žádný e-mail, webhook ani předání; odesílatel uvidí obvyklé poděkování. Když asistent není k dispozici, poptávka projde jako obvykle. Text každé poptávky se posílá poskytovateli AI – uveďte to v zásadách ochrany osobních údajů.',
    'Before handing over' => 'Před předáním',
    'Before the number (e.g. “+”)' => 'Před číslem (např. „+“)',
    'Before you point the domain to this site, check the old site against it: every old address must lead somewhere, and no page may lose its search engine description, its form or most of its images. Nothing is changed – the check only reads.' => 'Než doménu nasměrujete na tento web, porovnejte s ním starý web: každá stará adresa musí někam vést a žádná stránka nesmí přijít o popis pro vyhledávače, formulář ani většinu obrázků. Nic se nemění – kontrola jen čte.',
    'Before → after:' => 'Předtím → potom:',
    'Behind Cloudflare, say so in Settings → General (The site runs behind).' => 'Za Cloudflarem to uveďte v Nastavení → Obecné (Web běží za).',
    'Benefits' => 'Výhody',
    'Benefits with a list' => 'Výhody se seznamem',
    'Between %s%% and %s%% reads naturally.' => 'Mezi %s %% a %s %% text působí přirozeně.',
    'Big quote' => 'Velký citát',
    'Billing period' => 'Období platby',
    'Bing, Seznam and Yandex will then index them within minutes.' => 'Bing, Seznam a Yandex je pak zaindexují během minut.',
    'Black' => 'Černá',
    'Blank pop-up' => 'Prázdné okno',
    'Blank the name, e-mail, phone and note of this booking? The row stays for statistics.' => 'Vymazat jméno, e-mail, telefon a poznámku této rezervace? Řádek zůstane pro statistiky.',
    'Blank the name, e-mail, phone, message and attachments of this enquiry? The row stays for statistics.' => 'Vymazat jméno, e-mail, telefon, zprávu a přílohy této poptávky? Řádek zůstane pro statistiku.',
