    'Brand voice, words to use or avoid, house rules. Every Claude connection gets them when it connects, and they are its resource talea://instructions.' => 'Tón značky, slova, která používat a kterým se vyhnout, pravidla domu. Každé napojení Clauda je dostane při připojení a má je jako zdroj talea://instructions.',
