    'Card size: %s (the same for the whole site).' => 'Velikost karty: %s (stejná pro celý web).',
    'Cards from a collection (testimonials, team, products…) – the inside is the template for one item, {{fields}} fill in automatically.' => 'Karty z kolekce (reference, tým, produkty…) – vnitřek je vzor jedné položky, {{pole}} se doplní samo.',
    'Cards of finished projects with an image, name and location.' => 'Karty hotových zakázek s obrázkem, názvem a místem.',
