    'Changes not published' => 'Změny nejsou zveřejněné',
    'Changes one Claude connection makes in a row (with less than %d minutes between them) form a session. Undo puts back everything the session changed – pages, builds and drafts, news, collection items, menus, settings, the look – as it was before. Sessions are kept %d days.' => 'Změny, které jedno napojení Clauda udělá za sebou (s odstupem do %d minut), tvoří relaci. Vrácení obnoví vše, co relace změnila – stránky, stavby a koncepty, novinky, položky kolekcí, menu, nastavení, vzhled – do stavu před ní. Relace se uchovávají %d dní.',
    'Changes per connection and hour' => 'Změn za hodinu na jedno napojení',
    'Changes save automatically as a draft. Visitors see them only after Publish – before that we warn you about missing links, descriptions and low contrast.' => 'Změny se ukládají samy jako koncept. Návštěvníci je uvidí až po Publikovat – předtím vás upozorníme na chybějící odkazy, popisky a slabý kontrast.',
    'Changes that undo cannot follow' => 'Změny, které vrácení nedokáže sledovat',
    'Changes to the core are not supported; an update restores the original files (Backups).' => 'Úpravy jádra se nepodporují; do původní podoby je vrátí aktualizace (Zálohy).',
    'Changes to the site' => 'Změny na webu',
    'Changing it does not convert dates already saved: they keep their clock time.' => 'Změna už uložená data nepřepočítá: ponechají si hodinový čas.',
