    'Choose a service. Then all it needs is its ID – Talea takes care of the script, the cookie bar and the privacy policy.' => 'Vyberte službu. Pak stačí její ID – o skript, cookie lištu a zásady ochrany soukromí se postará Talea.',
    'Choose a type of structured data.' => 'Vyberte typ strukturovaných dat.',
    'Choose a video in MP4 or WebM format.' => 'Vyberte video ve formátu MP4 nebo WebM.',
    'Choose all that apply: the matching features are switched on and their pages prepared as drafts.' => 'Vyberte vše, co platí: odpovídající funkce se zapnou a jejich stránky se připraví jako koncepty.',
    'Choose an image' => 'Vyberte obrázek',
