    'Choose at least one news item, or send the latest news.' => 'Vyberte aspoň jednu novinku, nebo pošlete nejnovější.',
    'Choose at least one thing for the kit: the design system, a class, a component or a section.' => 'Vyberte do sady alespoň jednu věc: design systém, třídu, komponentu nebo sekci.',
