    'Class' => 'Třída',
    'Class changes apply to all elements with this class across the site – immediately after saving, without publishing.' => 'Změny třídy se projeví u všech prvků s touto třídou na celém webu – hned po uložení, bez publikování.',
    'Class name: lowercase letters without accents, digits and hyphens (e.g. card, card--highlighted).' => 'Název třídy: malá písmena bez diakritiky, číslice a pomlčky (např. karta, karta--zvyraznena).',
    'Class saved with a warning' => 'Třída uložena s upozorněním',
