    'Claude (MCP)' => 'Claude (MCP)',
    'Claude (MCP): administrators’ assistants work with the content; enquiries are shown to them as the Enquiries screen shows them.' => 'Claude (MCP): asistenti správců pracují s obsahem; poptávky vidí tak, jak je ukazuje obrazovka Poptávky.',
    'Claude builds pages, writes news drafts, adds hidden collection items, proposes exceptions to the opening hours, sorts enquiries and prepares look changes – you review and publish them. Nothing on the live site changes without you.' => 'Claude staví stránky, píše koncepty novinek, přidává skryté položky kolekcí, navrhuje výjimky z otevírací doby, třídí poptávky a připravuje změny vzhledu – vy je zkontrolujete a zveřejníte. Bez vás se na živém webu nic nezmění.',
    'Claude can check free times and set up services and people; reading bookings is recorded in the change log.' => 'Claude umí zjistit volné termíny a nastavit služby a lidi; čtení rezervací se zapisuje do protokolu změn.',
    'Claude connected' => 'Claude připojený',
    'Claude connection' => 'Napojení Clauda',
    'Claude connection – how to connect' => 'Napojení na Claude – jak připojit',
    'Claude connections after %d days' => 'napojení Clauda po %d dnech',
    'Claude has not called the site for %d days. The connection stays valid; ask Claude something about the site to check it.' => 'Claude web nevolal už %d dní. Napojení zůstává platné; pro kontrolu se Clauda na něco k webu zeptejte.',
    'Claude idle' => 'Claude nečinný',
    'Claude is connected' => 'Claude je připojený',
    'Claude is connected, but idle' => 'Claude je připojený, ale nečinný',
    'Claude is not connected' => 'Claude není připojený',
    'Claude may delete, trash and discard drafts' => 'Claude smí mazat, vyhazovat do koše a zahazovat koncepty',
    'Claude never runs on the site: the site holds no Claude sign-in and creates no tokens here – the routine lives in your Claude account and connects with the token you give it.' => 'Claude nikdy neběží na webu: web nemá žádné přihlášení ke Claudovi a tokeny zde nevytváří – rutina žije ve vašem účtu Claude a připojuje se tokenem, který jí dáte.',
    'Claude not connected' => 'Claude nepřipojený',
    'Claude reads it as a job to do as drafts – it never publishes anything by itself; you or an administrator review and publish the drafts.' => 'Claude to čte jako úkol, který udělá v konceptech – sám nikdy nic nezveřejní; koncepty zkontrolujete a zveřejníte vy nebo správce.',
    'Claude reads pages, settings, the audit and the change log, and suggests changes. It changes nothing.' => 'Claude čte stránky, nastavení, audit a protokol změn a navrhuje úpravy. Nic nemění.',
    'Claude reads the reply with the request the next time it works on the site.' => 'Claude si odpověď přečte s požadavkem, až bude příště pracovat na webu.',
    'Claude sends you here to sign in and confirm access. It then works with your account\'s permissions – builds and news are saved as drafts.' => 'Claude vás pošle sem přihlásit a potvrdit přístup. Pracuje pak s právy vašeho účtu – stavby a novinky ukládá jako koncept.',
    'Claude sends you here to sign in. You choose what it may do: save drafts for you to publish (recommended), also publish, or only read.' => 'Claude vás pošle sem k přihlášení. Vyberete, co smí: ukládat koncepty, které zveřejníte vy (doporučeno), také zveřejňovat, nebo jen číst.',
