    'Colours, fonts, sizes and typography styles in the W3C Design Tokens format (DTCG). A Talea export can be loaded back in full; from another tool the colours are taken.' => 'Barvy, písma, velikosti a typografické styly ve formátu W3C Design Tokens (DTCG). Export Talea se dá načíst zpět celý, z jiného nástroje se převezmou barvy.',
