    'Connect Claude as described below – the connector in the Claude app, or a personal token from My account.' => 'Připojte Clauda podle návodu níže – konektorem v aplikaci Claude, nebo osobním tokenem z Můj účet.',
    'Connect Claude to this site with a drafts-only token or connection: My account → Claude connection, access “drafts only”. A drafts-only connection can read the site and save drafts, and the two tools the routine needs (get_due_agent_runs, report_agent_run) – it cannot publish, delete or send.' => 'Připojte Clauda k tomuto webu tokenem nebo připojením jen pro koncepty: Můj účet → Připojení Clauda, přístup „jen koncepty“. Takové připojení umí web číst, ukládat koncepty a volat dva nástroje, které rutina potřebuje (get_due_agent_runs, report_agent_run) – nemůže publikovat, mazat ani odesílat.',
    'Connect Google Search Console or Bing Webmaster Tools in Administration → Connections; the queries and pages arrive with the daily job.' => 'Napojte Google Search Console nebo Bing Webmaster Tools v Administrace → Napojení; dotazy a stránky přinese denní úloha.',
