    'Each person creates and revokes their own connections in' => 'Každý si svá napojení vytváří a ruší v nabídce',
    'Each post, page and category arrives in its language version and is linked to its original in the default language.' => 'Každý příspěvek, stránka a kategorie přijde ve své jazykové verzi a je propojena s originálem ve výchozím jazyce.',
