    'Engine' => 'Vyhledávač',
    'Enough data, but no clear difference: B beats A with a probability of %s. Let it run longer or end the test and keep the original.' => 'Dat je dost, ale rozdíl není jasný: B překonává A s pravděpodobností %s. Nechte test běžet déle, nebo ho ukončete a ponechte původní verzi.',
    'Enquiries' => 'Poptávky',
    'Enquiries / sign-ups' => 'Poptávky / přihlášky',
    'Enquiries and events to Make, Zapier or your own system, signed.' => 'Poptávky a události do Make, Zapieru nebo vlastního systému, podepsané.',
