    'Enquiries permanently deleted: %d.' => 'Natrvalo smazáno poptávek: %d.',
    'Enquiries received' => 'Přijaté poptávky',
    'Enquiries resolved: %d.' => 'Vyřízeno poptávek: %d.',
    'Enquiries restored: %d.' => 'Obnoveno poptávek: %d.',
    'Enquiries to a sheet' => 'Poptávky do tabulky',
    'Enquiries waiting' => 'Čekající poptávky',
    'Enquiries with their attachments, the subscription (also in the connected mailing service), queued e-mails and testimonial requests are deleted. Backups keep older copies until they expire.' => 'Smažou se poptávky s přílohami, odběr (i v napojené mailingové službě), e-maily ve frontě a žádosti o referenci. Zálohy si starší kopie drží, dokud nevyprší.',
    'Enquiries with their attachments, the subscription (also in the connected mailing service), queued e-mails, testimonial requests and bookings are deleted. Backups keep older copies until they expire.' => 'Smažou se poptávky s přílohami, odběr (i v napojené rozesílací službě), e-maily ve frontě, žádosti o reference a rezervace. Zálohy drží starší kopie, dokud nevyprší.',
    'Enquiries: %d' => 'Poptávky: %d',
    'Enquiry' => 'Poptávka',
    'Enquiry form' => 'Poptávkový formulář',
    'Enquiry in the administration: %s' => 'Poptávka v administraci: %s',
    'Enquiry settings saved.' => 'Nastavení poptávek bylo uloženo.',
    'Enquiry status' => 'Stav poptávek',
    'Enquiry triage' => 'Třídění poptávek',
    'Enter a valid e-mail address of the person, or leave it empty.' => 'Zadejte platnou e-mailovou adresu člověka, nebo ji nechte prázdnou.',
    'Enter a valid e-mail address, or leave it empty.' => 'Zadejte platnou e-mailovou adresu, nebo ji nechte prázdnou.',
    'Enter a valid e-mail address.' => 'Zadejte platnou e-mailovou adresu.',
    'Enter a valid phone number, or leave it empty.' => 'Zadejte platné telefonní číslo, nebo ho nechte prázdné.',
    'Enter at least 3 characters.' => 'Zadejte alespoň 3 znaky.',
    'Enter every time as YYYY-MM-DD HH:MM.' => 'Zadejte každý termín jako RRRR-MM-DD HH:MM.',
    'Enter the Raynet instance name in Connections.' => 'Zadejte název instance Raynet v Napojení.',
    'Enter the address of a site on any platform – Wix, Webnode, Jimdo, Squarespace, Joomla, Drupal or WordPress without an export. Its pages become builder pages with their images, and the old addresses redirect to the new ones. The pages stay hidden until you check and publish them; the design is not copied – the pages take this site’s look.' => 'Zadejte adresu webu na jakékoli platformě – Wix, Webnode, Jimdo, Squarespace, Joomla, Drupal nebo WordPress bez exportu. Z jeho stránek se stanou stránky v builderu i s obrázky a staré adresy se přesměrují na nové. Stránky zůstanou skryté, dokud je nezkontrolujete a nezveřejníte; vzhled se nekopíruje – stránky převezmou vzhled tohoto webu.',
    'Enter the address of the collection including its folder, e.g. https://www.example.com/blog – the old address of an item is that address followed by /slug, and the redirects count on it.' => 'Zadejte adresu kolekce včetně její složky, např. https://www.example.com/blog – stará adresa položky je tato adresa a /slug, přesměrování s ní počítají.',
    'Enter the address of the site, e.g. https://www.example.com.' => 'Zadejte adresu webu, např. https://www.example.com.',
    'Enter the client ID and secret of your OAuth app first.' => 'Nejdřív zadejte ID klienta a tajný klíč své aplikace OAuth.',
    'Enter the code' => 'Při objednávce zadejte kód',
    'Enter the company domain of Pipedrive in Connections.' => 'Zadejte doménu firmy v Pipedrive v Napojení.',
    'Enter the correct password to turn it off.' => 'Pro vypnutí zadejte správné heslo.',
    'Enter the date as YYYY-MM-DD HH:MM.' => 'Zadejte datum ve tvaru RRRR-MM-DD HH:MM.',
    'Enter the dates as YYYY-MM-DD; the last day must not be before the first one.' => 'Zadejte data jako RRRR-MM-DD; poslední den nesmí být před prvním.',
    'Enter the day as YYYY-MM-DD and the time as HH:MM.' => 'Zadejte den jako RRRR-MM-DD a čas jako HH:MM.',
    'Enter the day off as YYYY-MM-DD (and HH:MM for a part of a day); the end must not be before the start.' => 'Zadejte volno jako RRRR-MM-DD (a HH:MM pro část dne); konec nesmí být před začátkem.',
    'Enter the gallery name.' => 'Zadejte název galerie.',
    'Enter the group name.' => 'Zadejte název skupiny.',
    'Enter the hours of the exception, e.g. 9:00-12:00 (more ranges with a comma), or mark the days as closed.' => 'Zadejte hodiny výjimky, např. 9:00-12:00 (víc rozsahů čárkou), nebo dny označte jako zavřené.',
    'Enter the last day as YYYY-MM-DD.' => 'Zadejte poslední den jako RRRR-MM-DD.',
    'Enter the last day as a date.' => 'Zadejte poslední den jako datum.',
    'Enter the name of the customer.' => 'Zadejte jméno zákazníka.',
    'Enter the name of the person.' => 'Zadejte jméno člověka.',
    'Enter the name of the service.' => 'Zadejte název služby.',
    'Enter the name of your business.' => 'Zadejte název svého podniku.',
    'Enter the old address and the target. The target is a path on this site or a full https://… address.' => 'Vyplňte starou adresu a cíl. Cíl je cesta na tomto webu, nebo celá adresa https://….',
    'Enter the page title.' => 'Vyplňte název stránky.',
    'Enter the public address of the site, e.g. https://www.example.com – not an internal address.' => 'Zadejte veřejnou adresu webu, např. https://www.example.com – ne vnitřní adresu.',
    'Enter the site address in Administration → Connections.' => 'Zadejte adresu webu v Administrace → Napojení.',
    'Enter the six-digit code from your authenticator app. No phone? Use one of your backup codes.' => 'Zadejte šestimístný kód z ověřovací aplikace. Nemáte telefon? Použijte jeden ze záložních kódů.',
    'Enter the six-digit code shown by the app:' => 'Opište šestimístný kód, který aplikace ukazuje:',
    'Enter the tag name.' => 'Vyplňte název štítku.',
    'Enter the user name or e-mail of your account. We will send you a link for setting a new password.' => 'Zadejte přihlašovací jméno nebo e-mail svého účtu. Pošleme vám odkaz pro nastavení nového hesla.',
    'Enter this address:' => 'Jako adresu zadejte:',
    'Enter times for at least one day, or choose "When the person works".' => 'Zadejte časy alespoň pro jeden den, nebo zvolte „Když osoba pracuje“.',
    'Enter your current password to add a passkey.' => 'K přidání přihlašovacího klíče zadejte své současné heslo.',
    'Enter your current password to change the e-mail address. Nothing was saved.' => 'Ke změně e-mailu zadejte své současné heslo. Nic se neuložilo.',
    'Erase' => 'Vymazat',
    'Erase everything listed above for good? This cannot be undone.' => 'Vymazat vše uvedené natrvalo? Nelze to vrátit.',
    'Erased: %d enquiries, %d subscriptions, %d e-mails in the queue, %d testimonial requests.' => 'Vymazáno: poptávky %d, odběry %d, e-maily ve frontě %d, žádosti o referenci %d.',
    'Error' => 'Chyba',
    'Error log' => 'Záznam chyb',
    'Errors in the last 24 hours' => 'Chyby za posledních 24 hodin',
    'Errors were found that prevent the site from running properly.' => 'Nalezeny chyby, které brání správnému provozu.',
    'Essentials' => 'Základní sada',
    'Event' => 'Událost',
    'Event invitation' => 'Pozvánka na událost',
    'Events' => 'Události',
    'Every call carries the headers X-Talea-Timestamp and X-Talea-Signature (sha256=HMAC-SHA256 of “timestamp.body” with this secret). A receiver that checks the signature knows the call came from your site and was not changed. Keep the secret private.' => 'Každé volání nese hlavičky X-Talea-Timestamp a X-Talea-Signature (sha256=HMAC-SHA256 z „časová značka.tělo“ s tímto klíčem). Příjemce, který podpis ověří, ví, že volání přišlo z vašeho webu a nikdo ho nezměnil. Klíč nikomu neukazujte.',
    'Every creation and change of the notice and the day it was posted and taken down. The log is append-only – nothing in it can be edited or deleted.' => 'Každé založení a změna oznámení a den, kdy bylo vyvěšeno a sejmuto. Do protokolu se jen přidává – nic v něm nelze upravit ani smazat.',
    'Every day' => 'Každý den',
    'Every day something changed on the site, otherwise once a week – while an administrator works in the administration or cron runs. The last 10 backups are kept.' => 'Každý den, kdy se na webu něco změnilo, jinak jednou týdně – když správce pracuje v administraci nebo běží cron. Uchovává se posledních 10 záloh.',
    'Every file is used somewhere on the site.' => 'Každý soubor je někde na webu použitý.',
    'Every image has a description (alt).' => 'Každý obrázek má popis (alt).',
    'Every image has a description for blind visitors (alt).' => 'Každý obrázek má popis pro nevidomé (alt).',
    'Every item always has a name. Add the fields you need – in the builder you insert them with a {{key}} tag. An empty label removes the field; the key of a saved field never changes.' => 'Každá položka má vždy název. Přidejte pole, která potřebujete – v builderu je vložíte značkou {{klíč}}. Prázdný popisek pole odebere; klíč už uloženého pole se nemění.',
    'Every month' => 'Každý měsíc',
    'Every newly published news item becomes a post with its image and a “Learn more” button.' => 'Každá nově zveřejněná novinka se stane příspěvkem s obrázkem a tlačítkem „Více informací“.',
    'Every news item belongs to one category – without it, the news item cannot be saved.' => 'Každá novinka patří do jedné kategorie – bez ní novinka nepůjde uložit.',
    'Every page, news item and collection item also as plain text without navigation – for language models and AI search engines.' => 'Každá stránka, novinka a položka kolekce i jako prostý text bez navigace – pro jazykové modely a AI vyhledávače.',
    'Every published page has appeared in search.' => 'Každá zveřejněná stránka se už ve vyhledávání objevila.',
    'Every score' => 'Jakékoli skóre',
    'Every service has its own page. Here you see what is connected and when it runs: right away, or only after the visitor agrees in the cookie bar.' => 'Každá služba má vlastní stránku. Tady vidíte, co je napojené a kdy to běží: hned, nebo až po souhlasu návštěvníka v cookie liště.',
    'Every time the trigger is met' => 'Pokaždé, když se spouštěč splní',
    'Every tool this connection may use is listed up front. More to load in every conversation.' => 'Všechny nástroje, které toto připojení smí použít, jsou nabízeny hned. V každé konverzaci je co načítat více.',
    'Every week' => 'Každý týden',
    'Everyone can see the item.' => 'Položku vidí všichni.',
    'Everyone can see the page.' => 'Stránku vidí všichni.',
    'Everyone off from' => 'Všichni volno od',
    'Everything about the person is erased for all bookings of one e-mail address in Enquiries → Personal data request.' => 'Vše o člověku ze všech rezervací jedné e-mailové adresy se maže v Poptávky → Žádost o osobní údaje.',
    'Everything in Standard' => 'Vše ze Standardu',
    'Everything is fine.' => 'Vše v pořádku.',
    'Everything is published.' => 'Vše je publikováno.',
    'Everything moved: every old address leads to a published page and nothing was lost.' => 'Všechno se přeneslo: každá stará adresa vede na zveřejněnou stránku a nic se neztratilo.',
    'Everything the blueprint checks is in place.' => 'Vše, co plán kontroluje, je v pořádku.',
    'Everything we can do for you.' => 'Co všechno pro vás uděláme.',
    'Everything went exactly as agreed, on time and on budget. We will gladly come back.' => 'Vše proběhlo přesně podle domluvy, včas a v rozpočtu. Rádi se vrátíme.',
    'Everything your role (%s) allows, publishing included – Claude publishes when you ask it to. The menu and the look still wait in the draft look until they are published.' => 'Vše, co smí vaše role (%s), včetně zveřejňování – Claude zveřejní, když o to požádáte. Menu a vzhled stále čekají v konceptu vzhledu, dokud je nezveřejníte.',
    'Everything, including users, appearance and site settings.' => 'Všechno včetně uživatelů, vzhledu a nastavení webu.',
    'Exactly this address' => 'Přesně tato adresa',
    'Exceptions to the opening hours' => 'Výjimky z otevírací doby',
    'Excerpt' => 'Výtah',
    'Excerpt limits' => 'Limity úryvků',
    'Expandable items – questions (FAQ for search engines) or any content that need not be visible straight away.' => 'Rozbalovací položky – otázky (FAQ pro vyhledávače) nebo jakýkoli obsah, který nemusí být vidět hned.',
    'Experience' => 'Zkušenosti',
    'Experiment' => 'Experiment',
    'Experiments' => 'Experimenty',
    'Expired' => 'Vypršelo',
    'Expires' => 'Platnost do',
    'Export confirmed (CSV)' => 'Export potvrzených (CSV)',
    'Export file' => 'Soubor exportu',
    'Export of the site “%s” from Talea %s, created %s.' => 'Export webu „%s“ z Talea %s, vytvořený %s.',
    'Export of the whole site' => 'Export celého webu',
    'Export this site as a blueprint' => 'Uložit tento web jako oborový plán',
    'Extension %s' => 'Rozšíření %s',
    'Extensions' => 'Rozšíření',
    'Extensions can be switched on or off at any time in the administration (Extensions). Switching off deletes nothing.' => 'Rozšíření lze kdykoli zapnout nebo vypnout v administraci (Rozšíření). Vypnutím se nic nesmaže.',
    'External links are checked in the background, one news item every five minutes. The audit runs each time you open this page.' => 'Externí odkazy se kontrolují na pozadí, jedna novinka každých pět minut. Audit proběhne pokaždé, když tuto stránku otevřete.',
    'External service' => 'Externí služba',
    'External service code' => 'Kód externí služby',
    'Extra declarations (property: value;)' => 'Deklarace navíc (vlastnost: hodnota;)',
    'Extra spam check' => 'Dodatečná kontrola spamu',
    'Eyebrow' => 'Nadtitulek',
    'FTP: folder for backups (created if missing). S3: bucket name, optionally bucket/folder.' => 'FTP: složka pro zálohy (vytvoří se). S3: název bucketu, případně bucket/složka.',
    'FTP: ftp.example.com. S3: the storage endpoint, e.g. s3.eu-central-1.amazonaws.com or s3.eu-central-003.backblazeb2.com.' => 'FTP: ftp.example.cz. S3: adresa úložiště, např. s3.eu-central-1.amazonaws.com nebo s3.eu-central-003.backblazeb2.com.',
    'Facebook, X, LinkedIn, WhatsApp, e-mail and copy link – no third-party scripts.' => 'Facebook, X, LinkedIn, WhatsApp, e-mail a kopírování odkazu – bez cizích skriptů.',
    'Fact' => 'Fakt',
    'Facts' => 'Fakta',
    'Facts without a value: %s' => 'Fakta bez hodnoty: %s',
    'Failed' => 'Neúspěšné',
    'Failed sign-ins' => 'Neúspěšná přihlášení',
    'Failed: %d.' => 'Nepovedlo se: %d.',
    'Fair pricing' => 'Férová cena',
    'Family house' => 'Rodinný dům',
    'Fast, clean and for the agreed price.' => 'Rychlé, čisté a za domluvenou cenu.',
    'Favourites' => 'Oblíbené',
    'Featured image' => 'Hlavní obrázek',
    'Features' => 'Funkce',
    'Features and add-ons' => 'Funkce a doplňky',
    'Features are optional parts of Talea. All of them are part of the system and maintained by the Talea team – nothing is downloaded or installed. A switched-off feature disappears from the menu and the site; its data stays and returns when you switch it on again.' => 'Funkce jsou volitelné části Talea. Všechny jsou součástí systému a udržuje je tým Talea – nic se nestahuje ani neinstaluje. Vypnutá funkce zmizí z menu i z webu, její data zůstanou a po zapnutí se vrátí.',
    'Features – one per line; a line starting with "-" is not included' => 'Funkce – každá na řádek; řádek začínající „-“ není v balíčku',
    'February' => 'únor',
    'Feedback and contact: add the e-mail address people can write to about barriers (Settings → General → Site e-mail).' => 'Zpětná vazba a kontakt: doplňte e-mailovou adresu, na kterou mohou lidé psát o bariérách (Nastavení → Základní → E-mail webu).',
    'Feedback and contact: if you find a barrier or need content in another form, write to %s. We will answer as soon as we can.' => 'Zpětná vazba a kontakt: narazíte-li na bariéru nebo potřebujete obsah v jiné podobě, napište na %s. Odpovíme co nejdříve.',
    'Fetch and show preview' => 'Stáhnout a ukázat náhled',
    'Fetching from %s: step %s of %s (%s), %s pages and %s items so far. Keep this page open, it continues by itself.' => 'Stahuji z %s: krok %s z %s (%s), zatím %s stránek a %s položek. Nechte stránku otevřenou, pokračuji sám.',
    'Fetching from other sites is switched off in the public demo.' => 'Stahování z jiných webů je ve veřejné ukázce vypnuté.',
    'Fewer than a month before' => 'Méně než před měsícem',
    'Field' => 'Pole',
    'Fields' => 'Pole',
    'Fields and settings' => 'Pole a nastavení',
    'Fields of collection “%s” – insert into text, image or link:' => 'Pole kolekce „%s“ – vložte do textu, obrázku nebo odkazu:',
    'Fields side by side fill a row; on a phone they stack.' => 'Pole vedle sebe vyplní řádek; na telefonu jsou pod sebou.',
    'File' => 'Soubor',
    'File %s – %s export of “%s”. Nothing has been imported yet; this is only an overview of what the file contains.' => 'Soubor %s – export z %s, web „%s“. Nic se zatím neimportovalo; toto je jen přehled, co soubor obsahuje.',
    'File %s – site “%s” (%s). Nothing has been imported yet; this is only an overview of what the file contains.' => 'Soubor %s – web „%s“ (%s). Zatím se nic neimportovalo; tohle je jen přehled toho, co v souboru je.',
    'File of font %d' => 'Soubor písma %d',
    'Files' => 'Soubory',
    'Files Claude uploaded over a connection limited to drafts. They are not public yet: signed-in users and draft previews see them. A file goes public with the content that uses it when that is published, or here with Publish file. Files nobody approves are deleted after %d days.' => 'Soubory, které Claude nahrál přes připojení jen pro koncepty. Zatím nejsou veřejné: vidí je přihlášení uživatelé a náhledy konceptů. Soubor se zveřejní s obsahem, který ho používá, až se ten zveřejní, nebo tady tlačítkem Zveřejnit soubor. Soubory, které nikdo neschválí, se po %d dnech smažou.',
    'Files from Claude waiting for approval' => 'Soubory od Clauda čekající na schválení',
    'Files in media/' => 'Soubory v media/',
    'Files in the media library' => 'Soubory v knihovně médií',
    'Files that could not be saved' => 'Soubory, které se nepodařilo uložit',
    'Files uploaded: %d.' => 'Nahráno souborů: %d.',
    'Fill in company details' => 'Vyplňte údaje o firmě',
    'Fill in for an item in another language version: the language switcher then leads straight to its counterpart and search engines get hreflang tags.' => 'Vyplňte u položky v jiné jazykové verzi: přepínač jazyků pak vede přímo na protějšek a vyhledávače dostanou značky hreflang.',
    'Fill in only for a news item in another language version (the category sets the language).' => 'Vyplňte jen u novinky v jiné jazykové verzi (jazyk určuje kategorie).',
    'Fill in the address in the Content panel or in Business details.' => 'Vyplňte adresu v panelu Obsah nebo v Údaje o firmě.',
    'Fill in the category name.' => 'Vyplňte název kategorie.',
    'Fill in the database name and user.' => 'Vyplňte název databáze a uživatele.',
    'Fill in the required fields: %s' => 'Vyplňte povinná pole: %s',
    'Fill in the role name.' => 'Vyplňte název role.',
    'Fill in the site address in Settings → General first.' => 'Nejdřív vyplňte adresu webu v Nastavení → Základní.',
    'Fill these in once and the site uses them everywhere: in the footer and on the contact page (the Company details element in the builder) and for Google, maps and AI assistants – so they answer correctly when you are open and where to find you.' => 'Údaje vyplníte jednou a web je použije všude: v patičce a na kontaktu (prvek Údaje firmy v builderu) i pro Google, Mapy a AI asistenty – ti tak správně odpoví na otázku, kdy máte otevřeno nebo kde vás najít.',
    'Filled from the site audit: the standard (EN 301 549 / WCAG 2.1 AA), the status by the accessibility findings, the known barriers and the contact. Created as a hidden page – review it, then publish it. Regenerating updates the draft.' => 'Vyplněno z auditu webu: norma (EN 301 549 / WCAG 2.1 AA), stav podle nálezů přístupnosti, známé bariéry a kontakt. Vznikne jako skrytá stránka – zkontrolujte ji a pak zveřejněte. Opakované vytvoření aktualizuje koncept.',
    'Filled in by “Create the sheet”; clear it to have a new sheet created' => 'Vyplní tlačítko „Vytvořit tabulku“; smažte ho a vytvoří se nová tabulka',
    'Filled-in profiles are shown in the site footer and passed to search engines.' => 'Vyplněné profily se zobrazí v patičce webu a předají se vyhledávačům.',
    'Filter' => 'Filtrovat',
    'Filter buttons for visitors (by the field above)' => 'Tlačítka filtru pro návštěvníky (podle pole výše)',
    'Filter by field (key, optional)' => 'Filtrovat podle pole (klíč, nepovinné)',
    'Find' => 'Najít',
    'Find broken links and missing image descriptions and fix them as drafts.' => 'Najděte rozbité odkazy a chybějící popisky obrázků a opravte je jako koncepty.',
    'Find the pages' => 'Najít stránky',
    'Finding pages: %s found so far. Keep this page open, it continues by itself.' => 'Hledají se stránky: zatím nalezeno %s. Nechte stránku otevřenou, pokračuje sama.',
    'Finding the pages of the old site. Keep this page open, it continues by itself.' => 'Hledám stránky starého webu. Nechte stránku otevřenou, pokračuje sama.',
    'Findings' => 'Nálezy',
    'Findings by kind' => 'Nálezy podle druhu',
    'Findings when the report was made' => 'Nálezy v době vytvoření zprávy',
    'Fingerprint, Face ID, Windows Hello or a security key instead of typing the code from the app. The code and the backup codes keep working – in case you do not have the device with you.' => 'Otisk prstu, Face ID, Windows Hello nebo bezpečnostní klíč místo opisování kódu z aplikace. Kód a záložní kódy fungují dál – pro případ, že zařízení nebudete mít u sebe.',
    'Finished pages are served to visitors from memory – the site is faster and copes with traffic peaks. Leave it on.' => 'Hotové stránky se návštěvníkům podávají z paměti – web je rychlejší a vydrží nápor. Nechte zapnuté.',
    'Firewall: old log rows and expired blocks' => 'Firewall: staré záznamy a prošlé blokace',
    'First and last name' => 'Jméno a příjmení',
    'First benefit' => 'První výhoda',
    'First fill in and save at least one webhook address (https://).' => 'Nejdřív vyplňte a uložte aspoň jednu adresu webhooku (https://).',
    'First fill in the Site e-mail on the General tab.' => 'Nejprve vyplňte E-mail webu v záložce Základní.',
    'First page of the visit' => 'První stránka návštěvy',
    'First pages of visits that brought a lead' => 'První stránky návštěv, ze kterých byl zájemce',
    'First seen %s' => 'Poprvé vidět %s',
    'First slide' => 'První snímek',
    'First steps' => 'První kroky',
    'First tab' => 'První karta',
    'Fit' => 'Vejít se',
    'Fix' => 'Vyřešit',
    'Fix selected' => 'Opravit označené',
    'Fix what is missing – redirects in Redirects, descriptions and forms on the pages – and check again. Claude can do it through the connection (migration_report).' => 'Doplňte, co chybí – přesměrování v Přesměrováních, popisy a formuláře na stránkách – a zkontrolujte znovu. Claude to zvládne přes napojení (migration_report).',
    'Fixed deadline' => 'Pevný termín',
    'Flat renovation' => 'Rekonstrukce bytu',
    'Fleet' => 'Konzole webů',
    'Fleet console' => 'Konzole webů',
    'Fleet console: are the sites up' => 'Konzole webů: běží weby?',
    'Flex growth' => 'Roztažení ve flexu',
    'Floor area (m²)' => 'Užitná plocha (m²)',
    'Flyout in the bottom left corner' => 'Plovoucí lišta v levém dolním rohu',
    'Flyout in the bottom right corner' => 'Plovoucí lišta v pravém dolním rohu',
    'Focus keyword' => 'Hlavní klíčové slovo',
    'Focus keywords' => 'Klíčová slova',
    'Folder' => 'Složka',
    'Folder / bucket' => 'Složka / bucket',
    'Folder deleted, its images are now uncategorized.' => 'Složka byla smazána, její obrázky jsou mezi nezařazenými.',
    'Folder name' => 'Název složky',
    'Folder saved.' => 'Složka byla uložena.',
    'Folder: ' => 'Složka: ',
    'Folders' => 'Složky',
    'Follow us' => 'Sociální sítě',
    'Font' => 'Písmo',
    'Font %d' => 'Písmo %d',
    'Font size' => 'Velikost písma',
    'Font weight' => 'Tloušťka písma',
    'Fonts' => 'Písma',
    'Fonts and sizes' => 'Písmo a velikosti',
    'Fonts that have them: %s.' => 'Písma, která je mají: %s.',
    'Food and drink menu' => 'Jídelní a nápojový lístek',
    'Food and stays' => 'Jídlo a ubytování',
    'Footer' => 'Patička',
    'Footer links' => 'Odkazy v patičce',
    'Footer menu' => 'Menu v patičce',
    'Footer text' => 'Text patičky',
    'For Gmail and Seznam use an “app password”, not your account password. The password is stored only on your site and is never displayed back.' => 'U Gmailu a Seznamu použijte „heslo pro aplikace“, ne heslo k účtu. Heslo se ukládá jen na vašem webu a nikdy se nevypisuje zpět.',
    'For a monthly schedule, 1–28 – so that every month has it.' => 'Pro měsíční plán, 1–28 – aby ho měl každý měsíc.',
    'For a service without a page of its own.' => 'Pro službu bez vlastní stránky.',
    'For a weekly schedule.' => 'Pro týdenní plán.',
    'For custom instructions this is the whole task; for a built-in task it is added to it (e.g. “only the pages in the Services section”). Claude reads it as the administrator’s instructions – it still works as drafts only.' => 'U vlastních pokynů je to celý úkol; u připraveného úkolu se k němu přidá (např. „jen stránky v sekci Služby“). Claude to čte jako pokyny správce – přesto pracuje jen s koncepty.',
    'For customers, neighbours and nature.' => 'K zákazníkům, sousedům i přírodě.',
    'For example eu-central-1. For Cloudflare R2 enter auto.' => 'Například eu-central-1. U Cloudflare R2 zadejte auto.',
    'For example https://www.example.com, without a trailing slash. Links in e-mails, RSS, the sitemap and notifications are built from it. Change it after moving to another domain.' => 'Například https://www.firma.cz, bez lomítka na konci. Skládají se z ní odkazy v e-mailech, RSS, mapě webu a oznámeních. Po přestěhování na jinou doménu ji změňte.',
    'For example smtp.gmail.com, smtp.seznam.cz, smtp-relay.brevo.com or smtp.vasedomena.cz.' => 'Například smtp.gmail.com, smtp.seznam.cz, smtp-relay.brevo.com nebo smtp.vasedomena.cz.',
    'For example the registered company name and company ID.' => 'Například obchodní firma a IČO.',
    'For example – click one, change it and send:' => 'Například – klikněte, upravte a pošlete:',
    'For mail clients and places that take no formatting – the Copy button puts it on the clipboard together with the formatted signature.' => 'Pro poštovní programy a místa bez formátování – tlačítko Kopírovat ji dá do schránky spolu s formátovaným podpisem.',
    'For search engines' => 'Pro vyhledávače',
    'For security reasons install.php has deleted itself – there is nothing else you need to do.' => 'Soubor install.php se z bezpečnostních důvodů smazal sám – nic dalšího dělat nemusíte.',
    'For security reasons, now delete this file from the server:' => 'Z bezpečnostních důvodů teď ze serveru smažte soubor',
    'For the whole site' => 'Pro celý web',
    'Forgotten password' => 'Zapomenuté heslo',
    'Forgotten your password?' => 'Zapomenuté heslo?',
    'Form' => 'Formulář',
    'Form fields' => 'Pole formuláře',
    'Form name (in Enquiries and in the email)' => 'Název formuláře (v Poptávkách a v e-mailu)',
    'Form names separated by commas; empty = every form' => 'Názvy formulářů oddělené čárkou; prázdné = každý formulář',
    'Form of address in German' => 'Oslovení v němčině',
    'Form or page' => 'Formulář nebo stránka',
