    'Forms are read from the published pages, site parts, pop-ups and item templates. Fields and recipients are changed in the builder.' => 'Formuláře se načítají z publikovaných stránek, částí webu, pop-upů a šablon položek. Pole a příjemce měníte v editoru.',
