    'Holidays and closed days of the whole business. A closed day in the opening hours exceptions (Business details) counts as a day off for everyone too; a person has their own days off on their form.' => 'Dovolené a zavřené dny celé firmy. Zavřený den ve výjimkách otevírací doby (Údaje o firmě) se také počítá jako volno pro všechny; vlastní volné dny má člověk ve svém formuláři.',
    'Holidays, a closed day, shorter hours. The site shows them under the opening hours, knows whether it is open now, and shows a notice bar a few days ahead until the exception ends.' => 'Svátky, zavřený den, kratší otevírací doba. Web je ukáže pod otevírací dobou, ví, jestli je právě otevřeno, a pár dní předem až do konce výjimky ukáže oznamovací lištu.',
