    'Idea' => 'Nápad',
    'If such an account exists and has an e-mail address, we have sent it a link for setting a new password. It is valid for one hour.' => 'Pokud takový účet existuje a má vyplněný e-mail, poslali jsme na něj odkaz pro nastavení nového hesla. Platí hodinu.',
    'If you did not ask for a new password, delete this e-mail – your password stays unchanged.' => 'Pokud jste o nové heslo nežádali, e-mail smažte – heslo zůstává beze změny.',
    'If you did not ask to subscribe, ignore this e-mail – without confirmation we will not send you anything.' => 'Pokud jste o odběr nežádali, e-mail ignorujte – bez potvrzení vám nic posílat nebudeme.',
    'If you did not change it, tell the administrator of the site at once – someone else may be using your account.' => 'Pokud jste ho neměnili vy, dejte hned vědět správci webu – váš účet možná používá někdo jiný.',
    'If you sign up or are invited as a member, we keep your e-mail address, your name if you give it, the groups you belong to and the time of your last sign-in. A cookie keeps you signed in on your device for up to 30 days; it is strictly necessary for the sign-in. We delete your account when you ask us to.' => 'Pokud se zaregistrujete nebo vás pozvou jako člena, uchováváme vaši e-mailovou adresu, jméno, pokud ho uvedete, skupiny, do nichž patříte, a čas posledního přihlášení. Cookie vás na vašem zařízení drží přihlášené až 30 dní; je pro přihlášení nezbytné. Účet smažeme, když o to požádáte.',
    'Ignore' => 'Ignorovat',
    'Ignore all' => 'Ignorovat vše',
    'Ignore all these addresses? The warning on the start screen goes away until a new address appears.' => 'Ignorovat všechny tyto adresy? Upozornění na úvodní obrazovce zmizí, dokud se neobjeví nová adresa.',
    'Ignore – nothing replaces it, or it is a bot probing for other systems. It will not come back.' => 'Ignorovat – nic ji nenahrazuje, nebo je to robot, který zkouší adresy jiných systémů. Už se nevrátí.',
