    'Importing: %s of %s pages. Keep this page open, it continues by itself.' => 'Import: %s z %s stránek. Nechte stránku otevřenou, pokračuje sama.',
    'Impressions' => 'Zobrazení ve výsledcích',
    'Imprint' => 'Tiráž',
    'Imprint (all details of the operator)' => 'Tiráž (všechny údaje o provozovateli)',
    'Imprint (legal notice)' => 'Tiráž (Impressum)',
    'In Blogger open Settings → Manage blog → Back up content and download the .xml file.' => 'V Bloggeru otevřete Nastavení → Správa blogu → Zálohovat obsah a stáhněte soubor .xml.',
    'In Campaign Manager under Analyze → Insight Tag.' => 'V Campaign Manageru v Analýza → Insight Tag.',
    'In Claude Code, just run:' => 'V Claude Code stačí příkaz:',
    'In Claude Code, run:' => 'V Claude Code spusťte:',
    'In Claude, create a scheduled task (the Claude app) or a routine (Claude Code) that runs a little after the earliest time in your schedules – for example every day at 07:15 – with this prompt:' => 'V Claudovi vytvořte naplánovanou úlohu (aplikace Claude) nebo rutinu (Claude Code), která běží chvíli po nejranějším čase z vašich plánů – třeba každý den v 07:15 – s tímto zadáním:',
    'In Ghost Admin open Settings → Labs → Export your content and download the .json file.' => 'V administraci Ghostu otevřete Settings → Labs → Export your content a stáhněte soubor .json.',
    'In Google Ads under Tools → Conversions; it starts with AW-.' => 'V Google Ads v Nástroje → Konverze; začíná na AW-.',
    'In Joomla open Users → Manage → the user → Joomla API Token, tick Enabled and copy the token. The user must be allowed to read articles, categories and users. The Web Services API plugins must be switched on (System → Plugins → Web Services).' => 'V Joomle otevřete Users → Manage → uživatel → Joomla API Token, zaškrtněte Enabled a token zkopírujte. Uživatel musí smět číst články, rubriky a uživatele. Pluginy Web Services API musí být zapnuté (System → Plugins → Web Services).',
    'In Matomo under Administration → Websites → Manage.' => 'V Matomu v Administrace → Weby → Spravovat.',
    'In Meta Events Manager under Data sources.' => 'V Meta Events Manageru v části Zdroje dat.',
    'In Microsoft Advertising under Tools → UET tag.' => 'V Microsoft Advertising v Nástroje → UET tag.',
    'In Pinterest Ads under Conversions.' => 'V Pinterest Ads v části Konverze.',
    'In TikTok Ads Manager under Assets → Events.' => 'V TikTok Ads Manageru v Assets → Events.',
    'In Umami under Settings → Websites → Edit.' => 'V Umami v Nastavení → Weby → Upravit.',
    'In WordPress, open Tools → Export, choose “All content” and download the .xml file. Then upload it here. Pages, posts (as news), categories and tags are converted and redirects from the old addresses are created; nothing changes on the site until you confirm the import in the next step.' => 'Ve WordPressu otevřete Nástroje → Export, zvolte „Veškerý obsah“ a stáhněte soubor .xml. Ten pak nahrajte sem. Převedou se stránky, příspěvky (jako novinky), kategorie a štítky a vzniknou přesměrování ze starých adres; na webu se nic nezmění, dokud import v dalším kroku nepotvrdíte.',
    'In fifteen years we have completed hundreds of projects across the country.' => 'Za patnáct let jsme dokončili stovky zakázek po celé republice.',
    'In navigation' => 'V navigaci',
    'In one or two sentences, say what you do, who it is for and why you.' => 'Jednou nebo dvěma větami řekněte, co děláte, pro koho a proč právě vy.',
    'In one sentence, what this page is about.' => 'Jednou větou, o čem stránka je.',
    'In one sentence: what you do and for whom. Edit this page in the administration under Pages.' => 'Jednou větou: co děláte a pro koho. Tuto stránku upravíte v administraci v sekci Stránky.',
    'In progress' => 'Řeší se',
    'In search · 28 days' => 'Ve vyhledávání · 28 dní',
    'In the Claude app open Settings → Connectors → Add custom connector.' => 'V aplikaci Claude otevřete Nastavení → Konektory → Přidat vlastní konektor.',
    'In the Claude app you do not need a token: add a custom connector with the address %s and confirm access by signing in.' => 'V aplikaci Claude token nepotřebujete: přidejte vlastní konektor s adresou %s a přístup potvrďte přihlášením.',
    'In the Webflow Designer open CMS → the collection → Export and download the .csv file (one collection per file).' => 'Ve Webflow Designeru otevřete CMS → kolekce → Export a stáhněte soubor .csv (jedna kolekce na soubor).',
    'In the background, one news item every five minutes. The result is in News → Broken links.' => 'Na pozadí, jedna novinka za pět minut. Výsledek je v Novinky → Nefunkční odkazy.',
    'In the background, the system goes through published news – one every five minutes, each once a month – and checks whether its links still work. News items checked: %s of %s.' => 'Systém na pozadí prochází vydané novinky – jednu za pět minut, každou jednou za měsíc – a zkouší, jestli odkazy v nich ještě fungují. Zkontrolováno novinek: %s z %s.',
    'In the background, the system goes through published news, pages and collection items – one every five minutes, each once a month – and checks whether their links still work. Checked: %s of %s.' => 'Systém na pozadí prochází vydané novinky, stránky a položky kolekcí – jednu za pět minut, každou jednou za měsíc – a kontroluje, zda jejich odkazy stále fungují. Zkontrolováno: %s z %s.',
    'In the builder, new sections from a description and text rewrites; in news, headlines, intro, SEO description, tags, proofreading, image descriptions and translation. Needs your own Claude, OpenAI, Google or Mistral key (Settings → Writing assistant); text is sent only when you click an assistant button.' => 'V builderu nové sekce podle popisu a přepisy textů, v novinkách titulky, perex, SEO popis, štítky, korektura, popisy obrázků a překlad. Potřebuje vlastní klíč Claude, OpenAI, Google nebo Mistral (Nastavení → Asistent psaní); text se posílá jen po kliknutí na tlačítko asistenta.',
    'In the draft look the footer menu is empty.' => 'V konceptu vzhledu je menu v patičce prázdné.',
    'In the draft look the menu is again built automatically from pages in the navigation.' => 'V konceptu vzhledu se menu zase skládá automaticky ze stránek v navigaci.',
    'In the first days of each month the site e-mails a short report about the previous month: traffic, enquiries and sign-ups, updates, backups, changes made by people and by Claude, the problems right now and what needs your decision. Counts and page addresses only – never names, e-mail addresses or the contents of enquiries, so the report can be forwarded. With the agency details from the General tab it carries the agency’s branding.' => 'V prvních dnech každého měsíce web pošle e-mailem krátkou zprávu o předchozím měsíci: návštěvnost, poptávky a přihlášení k odběru, aktualizace, zálohy, změny provedené lidmi i Claudem, aktuální problémy a co potřebuje vaše rozhodnutí. Jen počty a adresy stránek – nikdy jména, e-mailové adresy ani obsah poptávek, zprávu tak lze přeposlat. S údaji agentury ze záložky Základní nese značku agentury.',
    'In the past week, visitors repeatedly could not find %d addresses (404 error). Redirect them to the right pages.' => 'Návštěvníci za poslední týden opakovaně nenašli %d adres (chyba 404). Přesměrujte je na správné stránky.',
    'In the search index' => 'Ve vyhledávacím indexu',
    'In the site’s time zone (%s). Set the routine in Claude to run a little later – it picks the run up when it is due.' => 'V časovém pásmu webu (%s). Rutinu v Claudovi nastavte o chvíli později – běh si vyzvedne, až bude na řadě.',
    'In this text' => 'V tomto textu',
    'In trash since' => 'V koši od',
    'In your authenticator app (Google Authenticator, Microsoft Authenticator, 1Password, Aegis…) add a new account by scanning the QR code:' => 'V ověřovací aplikaci (Google Authenticator, Microsoft Authenticator, 1Password, Aegis…) přidejte nový účet naskenováním QR kódu:',
