    'Install Talea on the new hosting with the same table prefix (tl_ unless you changed it) and any starter site.' => 'Nainstalujte Talea na nový hosting se stejnou předponou tabulek (tl_, pokud jste ji neměnili) a s libovolným startovacím webem.',
