    'Issuer' => 'Původce',
    'It appears, with the hreflang links for search engines, once the home page has a published translation.' => 'Objeví se tam, včetně odkazů hreflang pro vyhledávače, jakmile bude mít úvodní stránka zveřejněný překlad.',
    'It creates new news items as drafts and new pages as hidden. All its changes are in the Change log. Protect the token like a password.' => 'Nové novinky zakládá jako koncepty a nové stránky jako skryté. Všechny jeho zásahy najdete v Protokolu změn. Token chraňte jako heslo.',
    'It declares that it:' => 'Prohlašuje, že:',
    'It has database tables but does not declare "tables" in its capabilities.' => 'Má databázové tabulky, ale v capabilities neuvádí „tables“.',
    'It is about' => 'Týká se',
    'It will act with the permissions of your account %s (%s): read and edit pages, news, site parts and appearance – just like you in the administration. Builds and news are saved as drafts.' => 'Bude jednat s právy vašeho účtu %s (%s): číst a upravovat stránky, novinky, části webu a vzhled – stejně jako vy v administraci. Stavby a novinky ukládá jako koncept.',
    'It will act with your account %s (%s) – never with more than your role allows.' => 'Bude pracovat s vaším účtem %s (%s) – nikdy s víc, než dovoluje vaše role.',
