    'Joomla 4 and 5 have no export file: enter the site address and an API token below and the content is fetched from its Web Services API.' => 'Joomla 4 a 5 nemají exportní soubor: zadejte níže adresu webu a API token a obsah se stáhne z jeho Web Services API.',
