    'Leave a field empty for no limit; -1 means no limit too. Numbers are characters (text) and seconds (video).' => 'Prázdné pole znamená bez limitu; -1 také. Čísla jsou znaky (text) a vteřiny (video).',
    'Leave empty if you are not changing the password.' => 'Nechte prázdné, pokud heslo neměníte.',
