    'Left out (repeaters, galleries or relationships – Claude can move them by hand): %s.' => 'Vynechá se (opakovače, galerie a vazby – Claude je může přenést ručně): %s.',
    'Left out – the site has no version in these languages: %s. Add the language in Settings and import the file again, or tick the option to add the language versions.' => 'Vynecháno – web nemá verzi v těchto jazycích: %s. Přidejte jazyk v Nastavení a soubor naimportujte znovu, nebo zaškrtněte volbu přidat jazykové verze.',
    'Legal basis: consent (Art. 6(1)(a)); every e-mail carries an unsubscribe link.' => 'Právní základ: souhlas (čl. 6 odst. 1 písm. a); každý e-mail má odkaz pro odhlášení.',
    'Legal basis: performance of the membership the person asked for (Art. 6(1)(b)). Retention: until the person asks to be removed or the owner removes them – then the account and its sessions are deleted (Enquiries → Personal data request).' => 'Právní základ: plnění členství, o které osoba požádala (čl. 6 odst. 1 písm. b). Uchování: dokud osoba nepožádá o odstranění nebo ji majitel neodebere – pak se účet i relace smažou (Poptávky → Žádost o osobní údaje).',
    'Legal basis: steps before a contract (Art. 6(1)(b)); keeping an application longer needs the applicant’s consent.' => 'Právní základ: kroky před uzavřením smlouvy (čl. 6 odst. 1 písm. b); delší uchování vyžaduje souhlas uchazeče.',
    'Let AI draft it' => 'Nechat návrh na AI',
