    'Makes this installation the console of your other Talea sites: they report to it every hour, it shows all of them on one screen sorted by what needs attention, checks that they are up and decides when they install a new version – test sites first, the rest two days later. It never gets into the sites.' => 'Udělá z této instalace konzoli vašich dalších webů na Talea: každou hodinu jí posílají hlášení, ukáže je všechny na jedné obrazovce seřazené podle toho, co potřebuje pozornost, hlídá, jestli běží, a rozhoduje, kdy nainstalují novou verzi – nejdřív testovací weby, ostatní o dva dny později. Do webů se nikdy nedostane.',
