    'Members only' => 'Jen pro členy',
    'Members sign in with a link sent to their e-mail address – there are no passwords. Restrict a page, a collection item or a news item to one or more groups in its own form (Options). Restricted content is never cached, indexed or searchable. Visitors sign in at %s.' => 'Členové se přihlašují odkazem zaslaným na jejich e-mailovou adresu – žádná hesla nejsou. Stránku, položku kolekce nebo novinku omezíte na jednu či více skupin v jejím formuláři (Volby). Omezený obsah se nikdy neukládá do cache, neindexuje se a nedá se vyhledat. Návštěvníci se přihlašují na %s.',
    'Members, newsletters, comments and the theme are not transferred. A post that was only sent by e-mail is imported as a draft.' => 'Členové, newslettery, komentáře a šablona se nepřenášejí. Příspěvek, který byl jen rozeslán e-mailem, se importuje jako koncept.',
