    'Move within Structure' => 'Pohyb ve Struktuře',
    'Moving a site from another Talea installation: upload its export (the .zip archive from Export of the whole site). Everything is imported – pages, news, collections, components, menus, the look and the media – into a new, empty site; user accounts and secrets are never part of an export.' => 'Přesun webu z jiné instalace Talea: nahrajte jeho export (archiv .zip z Exportu celého webu). Naimportuje se všechno – stránky, novinky, kolekce, komponenty, menu, vzhled i média – do nového, prázdného webu; uživatelské účty a tajné údaje v exportu nikdy nejsou.',
    'Moving a site to another Talea installation without accounts and secrets is simpler with Export of the whole site and Import from Talea (Import and export).' => 'Přesun webu do jiné instalace Talea bez účtů a tajných údajů je jednodušší přes Export celého webu a Import z Talea (Import a export).',
    'Moving from a system with its own export: posts become news items, pages become pages, categories and tags come along, old addresses redirect to the new ones. In the next step you see what the file contains and choose what becomes what; nothing changes on the site until you confirm.' => 'Přechod ze systému s vlastním exportem: z příspěvků budou novinky, ze stránek stránky, rubriky a štítky se přenesou, staré adresy přesměrují na nové. V dalším kroku uvidíte, co soubor obsahuje, a vyberete, co se stane čím; na webu se nic nezmění, dokud nepotvrdíte.',
