    'News URL' => 'Adresa novinek',
    'News and blog: the /news listing with categories and tags, RSS, the News element in the builder and a link in the automatic menu.' => 'Aktuality a blog: výpis /news s kategoriemi a štítky, RSS, prvek Novinky v builderu a odkaz v automatickém menu.',
    'News and pages still show images from the old site. Downloading saves the main news images and images in texts to Media (resized, with thumbnails and WebP) and rewrites the links in the texts. Images are downloaded from the image hosts of %s, which must still be available.' => 'Novinky a stránky zatím zobrazují obrázky ze starého webu. Stažení uloží hlavní obrázky novinek i obrázky v textech do Médií (zmenšené, s náhledy a WebP) a přepíše odkazy v textech. Obrázky se stahují z obrázkových serverů systému %s, které musí být ještě dostupné.',
    'News and pages still show images from the old site. Downloading saves the main news images and images in texts to Media (resized, with thumbnails and WebP) and rewrites the links in the texts. Images are downloaded only from the domain %s, and the old site must still be available.' => 'Novinky a stránky zatím ukazují obrázky ze starého webu. Stažením se hlavní obrázky novinek a obrázky v textech uloží do Médií (zmenší se, vzniknou náhledy a WebP) a odkazy v textech se přepíší. Stahuje se výhradně z domény %s a starý web musí být ještě dostupný.',
