    'Next: check the pages, put the ones you keep into the menu and publish them. Claude can match their look to the design system and tidy the texts through the connection.' => 'Dál: zkontrolujte stránky, ty, které si necháte, dejte do menu a zveřejněte. Claude přes napojení sladí jejich vzhled s design systémem a upraví texty.',
    'No' => 'Ne',
    'No AI key is set, so no text can be written. The wizard still applies the blueprint and a look; add a key under Features (Writing assistant) and run it again to get the pages.' => 'Není nastaven klíč AI, takže nelze napsat žádné texty. Průvodce přesto použije oborový plán a vzhled; klíč doplňte ve Funkcích (Asistent psaní) a spusťte průvodce znovu, abyste získali stránky.',
    'No AI key is set, so no text is written and no pages are made. Add a key under Features (Writing assistant) to get them.' => 'Není nastaven klíč AI, takže se nepíšou texty ani nevznikají stránky. Klíč doplňte ve Funkcích (Asistent psaní).',
    'No Claude session yet.' => 'Zatím žádná relace Clauda.',
    'No accessibility statement – the European Accessibility Act expects a service to say how accessible it is and whom to contact about barriers. Add a page such as /accessibility.' => 'Chybí prohlášení o přístupnosti – evropský akt o přístupnosti (EAA) čeká, že služba řekne, jak je přístupná a na koho se obrátit kvůli bariérám. Přidejte stránku např. /pristupnost.',
    'No accounts are created. Each author’s posts belong to the user you choose; by default to you.' => 'Žádné účty se nezakládají. Příspěvky každého autora patří uživateli, kterého vyberete; výchozí jste vy.',
