    'No run yet. The first one is handed out at %s – when the routine in Claude asks.' => 'Zatím žádný běh. První se předá %s – až se rutina v Claudovi zeptá.',
    'No schedules yet.' => 'Zatím žádné plány.',
    'No search data for the last 28 days.' => 'Za posledních 28 dní nejsou žádná data z vyhledávání.',
