    'No security contact – add who takes reports of security problems (published as security.txt).' => 'Chybí kontakt pro bezpečnostní hlášení – doplňte, kdo přijímá hlášení bezpečnostních problémů (zveřejní se jako security.txt).',
    'No services yet. A service is what the visitor books, such as a haircut, a consultation or a tyre change, and how long it takes.' => 'Zatím žádné služby. Služba je to, co si návštěvník rezervuje, třeba střih, konzultace nebo přezutí pneumatik, a jak dlouho trvá.',
    'No sheet – create it in Administration → Connections.' => 'Tabulka chybí – vytvořte ji v Administrace → Napojení.',
    'No site e-mail: enquiries and password resets have nowhere to go.' => 'Chybí e-mail webu: poptávky a obnovy hesla nemají kam jít.',
    'No site icon (favicon) – browsers and phones show a blank one.' => 'Chybí ikona webu (favicon) – prohlížeče a telefony ukážou prázdnou.',
    'No site reports to this console yet. Make a pairing key and paste it on the site.' => 'Této konzoli zatím žádný web nehlásí. Vytvořte párovací klíč a vložte ho na webu.',
