    'No text was written. Add an AI key under Features (Writing assistant) and run the wizard again to get the pages.' => 'Nebyl napsán žádný text. Doplňte klíč AI ve Funkcích (Asistent psaní) a spusťte průvodce znovu, abyste získali stránky.',
