    'Nobody picked the run up within 6 hours – is the routine in Claude still running?' => 'Běh si do 6 hodin nikdo nevyzvedl – běží rutina v Claudovi ještě?',
    'Nobody takes bookings yet. Add the people (or just one entry for the whole business) and tick the services each offers.' => 'Zatím nikdo nepřijímá rezervace. Přidejte lidi (nebo jeden záznam za celou firmu) a zaškrtněte služby, které každý nabízí.',
    'Non-accessible content:' => 'Nepřístupný obsah:',
    'None' => 'Žádná',
    'None of the elements could be inserted.' => 'Žádný z prvků se nepodařilo vložit.',
    'None of them fits?' => 'Žádný nesedí?',
    'None – every check in System status is fine.' => 'Žádné – všechny kontroly ve Stavu systému jsou v pořádku.',
    'Not checked yet' => 'Zatím nezkontrolováno',
    'Not connected' => 'Nenapojeno',
    'Not imported – this site cannot offer these languages yet: %s.' => 'Nenaimportováno – tento web zatím tyto jazyky nenabízí: %s.',
    'Not in search yet' => 'Zatím není ve vyhledávání',
    'Not in the language switcher yet: %s. A language appears there once the home page has a published translation.' => 'Zatím není v přepínači jazyků: %s. Jazyk se tam objeví, jakmile bude mít úvodní stránka zveřejněný překlad.',
    'Not in the menu' => 'Mimo menu',
    'Not needed for Gone (410) and Unavailable for legal reasons (451).' => 'Nepotřebné pro Zmizelo (410) a Nedostupné z právních důvodů (451).',
    'Not posted yet' => 'Ještě nezveřejněno',
    'Not published yet' => 'Zatím nezveřejněné',
    'Not ready to go live: %s problems would cost visitors or search engines something.' => 'Ještě ne ke spuštění: %s problémů by návštěvníky nebo vyhledávače o něco připravilo.',
    'Not saved – %s: %s' => 'Neuloženo – %s: %s',
    'Not set' => 'Nenastaveno',
    'Not sorted' => 'Neroztříděné',
    'Not sorted yet' => 'Zatím nezařazeno',
    'Not spam' => 'Není spam',
    'Not started yet.' => 'Zatím nespuštěno.',
    'Not used yet. Write {{fact.%s}} into a text, a button or a link.' => 'Zatím se nepoužívá. Napište {{fact.%s}} do textu, tlačítka nebo odkazu.',
    'Not what you wanted? The whole run can be taken back in one step.' => 'Není to, co jste chtěli? Celý běh lze vzít zpět jedním krokem.',
    'Note' => 'Poznámka',
    'Notebook' => 'Zápisník',
    'Notes for whoever works on the site next – Claude in a new conversation, or a colleague: decisions, wording rules, photo credits, the history of the site, what the client is sensitive about. Claude reads them with read_notebook before larger changes and writes decisions down with write_notebook – a drafts-only connection too. Nothing here is shown on the site.' => 'Poznámky pro toho, kdo bude na webu pracovat příště – Clauda v nové konverzaci nebo kolegu: rozhodnutí, pravidla formulací, autoři fotek, historie webu, na co je klient citlivý. Claude si je před většími změnami přečte nástrojem read_notebook a rozhodnutí zapisuje nástrojem write_notebook – i s napojením jen pro koncepty. Nic z toho se na webu nezobrazuje.',
    'Nothing at this address and no redirect – it will end in 404.' => 'Na této adrese nic není a nevede z ní přesměrování – skončí chybou 404.',
    'Nothing booked for these days and filters.' => 'Pro tyto dny a filtry není nic rezervováno.',
    'Nothing found.' => 'Nic nenalezeno.',
    'Nothing ignored.' => 'Nic není ignorováno.',
    'Nothing like that here.' => 'Nic takového tu není.',
    'Nothing links here' => 'Sem nic neodkazuje',
    'Nothing marked yet.' => 'Zatím nic neoznačeno.',
    'Nothing matches your search.' => 'Hledanému textu nic neodpovídá.',
    'Nothing needs attention.' => 'Nic nepotřebuje pozornost.',
    'Nothing on the site points at these files: no page, build, news item, collection item, component, pop-up, newsletter or setting. Media has no trash – deleted files cannot be restored.' => 'Na tyto soubory nic na webu neodkazuje: žádná stránka, stavba, novinka, položka kolekce, komponenta, pop-up, newsletter ani nastavení. Média nemají koš – smazané soubory nejde obnovit.',
    'Nothing refused yet.' => 'Zatím nic odmítnuto.',
    'Nothing to copy.' => 'Není co kopírovat.',
    'Nothing to do – no address ended with “page not found” repeatedly in the last 60 days.' => 'Nic k řešení – za posledních 60 dní žádná adresa opakovaně neskončila „stránka nenalezena“.',
    'Nothing to do – when you change the address of a page or news item, a redirect is created automatically.' => 'Nic nemusíte dělat – když změníte adresu stránky nebo novinky, přesměrování vznikne samo.',
    'Nothing to fix.' => 'Není co opravovat.',
    'Nothing to undo: version B was not applied.' => 'Není co vracet: verze B nebyla použita.',
    'Nothing tracks whether subscribers open the e-mail. Links to the site carry utm parameters, so Statistics show the visits the newsletter brought.' => 'Nic nesleduje, jestli odběratelé e-mail otevřou. Odkazy na web nesou parametry utm, takže Statistika ukáže návštěvy, které newsletter přivedl.',
    'Nothing was waiting.' => 'Nic nečekalo.',
    'Nothing – the site keeps no data about this address.' => 'Nic – web o této adrese žádné údaje neuchovává.',
    'Notice' => 'Oznámení',
    'Notice bar' => 'Oznamovací lišta',
    'Notice log (%s)' => 'Protokol oznámení (%s)',
    'Notice status' => 'Stav oznámení',
    'Notice text' => 'Text oznámení',
    'Notices stay in the archive – change the takedown date instead.' => 'Oznámení zůstávají v archivu – změňte místo toho datum sejmutí.',
    'Notification e-mails (several separated by commas; empty = site e-mail from Settings)' => 'E-maily pro upozornění (více oddělte čárkou; prázdné = e-mail webu z Nastavení)',
    'Notifications' => 'Oznámení',
    'Notify search engines about new news (IndexNow)' => 'Oznamovat nové novinky vyhledávačům (IndexNow)',
    'November' => 'listopad',
    'Number' => 'Číslo',
    'Number of news items' => 'Počet novinek',
    'Number of reviews' => 'Počet recenzí',
    'Number – or a fact or count token ({{fact.projects}}, {{years_since:2004}}, {{count:reference}})' => 'Číslo – nebo značka faktu či počtu ({{fact.projects}}, {{years_since:2004}}, {{count:reference}})',
    'Numbered list' => 'Číslovaný seznam',
    'Numbers' => 'Čísla',
    'Numbers on a light background' => 'Čísla na světlém pozadí',
    'Numbers the site works out when a page is shown, so they never go stale – years since a date and counts of what is on the site. Write the token into a text, or into the number of a counter.' => 'Čísla, která web spočítá při zobrazení stránky, takže nikdy nezestárnou – roky od data a počty toho, co na webu je. Značku napište do textu, nebo do čísla počítadla.',
    'OK' => 'V pořádku',
    'ON' => 'ZAPNUTÝ',
    'October' => 'říjen',
    'Of the saved version. Search engines show about 60 characters of a title and 160 of a description.' => 'Z uložené verze. Vyhledávače ukážou asi 60 znaků titulku a 160 znaků popisu.',
    'Off' => 'Vypnuto',
    'Off from' => 'Volno od',
    'Off – nothing is measured.' => 'Vypnuto – nic se neměří.',
    'Off-site backup copies' => 'Kopie záloh mimo server',
    'Off-site backups' => 'Zálohy mimo server',
    'Off-site copy of the media' => 'Kopie médií mimo server',
    'Off: those tools are refused for every connection; you do them in the admin.' => 'Vypnuto: tyto nástroje budou pro každé napojení odmítnuty; uděláte je v administraci.',
    'Offer' => 'Nabídka',
    'Offer a contact form' => 'Nabízet kontaktní formulář',
    'Offer content for members' => 'Nabízet obsah pro členy',
    'Offered by' => 'Nabízí',
    'Offered to visitors' => 'Nabízet návštěvníkům',
    'Offers their own products or services, or a cooperation.' => 'Nabízí vlastní produkty, služby nebo spolupráci.',
    'Office' => 'Kancelář',
    'Official add-on, shipped with Talea and updated with it.' => 'Oficiální doplněk, součást Taley a aktualizuje se s ní.',
    'Official notice board' => 'Úřední deska',
    'Official notice board: postings and takedowns' => 'Úřední deska: vyvěšení a sejmutí',
    'Offset' => 'Posun',
    'Old address' => 'Stará adresa',
    'Old addresses' => 'Staré adresy',
    'Old addresses are taken as /slug/ (Ghost’s default routes). A custom routes.yaml is not part of the export and is not read.' => 'Staré adresy se berou jako /slug/ (výchozí cesty Ghostu). Vlastní routes.yaml není součástí exportu a nečte se.',
    'Old addresses are the path aliases (or /node/number). Articles become news items, basic pages become pages.' => 'Staré adresy jsou aliasy cest (nebo /node/číslo). Články se stanou novinkami, základní stránky stránkami.',
    'Old site: %s' => 'Starý web: %s',
    'Older enquiry' => 'Starší poptávka',
    'Older records are deleted automatically. 0 = keep.' => 'Starší záznamy se mažou automaticky. 0 = nemazat.',
    'On' => 'Zapnuto',
    'On a phone you can tap here – the link opens your authenticator app.' => 'Na mobilu můžete klepnout sem – odkaz otevře ověřovací aplikaci.',
    'On all work.' => 'Na veškerou práci.',
    'On every page, regardless of consent' => 'Na každé stránce, bez ohledu na souhlas',
    'On leave' => 'Nepřítomnost',
    'On my Talea site %s (use its connector):' => 'Na mém webu na Talea %s (použij jeho konektor):',
    'On the canvas the element is always visible. On the website it appears only when the conditions are met – for example a promotional banner for a week.' => 'Na plátně je prvek vidět vždy. Na webu se ukáže jen při splnění podmínek – třeba akční banner na týden.',
    'On the console: Fleet → Add a site. The key is valid for 24 hours and only once.' => 'V konzoli: Konzole webů → Přidat web. Klíč platí 24 hodin a jen jednou.',
    'On the left you pick an element or a whole ready-made section. Click to insert it after the selected element, drag it anywhere on the page. The Structure tab shows the page as a tree.' => 'Vlevo vyberete prvek nebo celou hotovou sekci. Klepnutím ho vložíte za vybraný prvek, přetažením kamkoli na stránku. Záložka Struktura ukáže stavbu stránky jako strom.',
    'On the right you change the text, links, colours, spacing and behaviour of the selected element. Take colours and sizes from the list – they keep the website consistent.' => 'Vpravo měníte text, odkazy, barvy, rozestupy i chování vybraného prvku. Barvy a velikosti berte z nabídky – drží jednotný vzhled webu.',
    'On the site' => 'Na webu',
    'On this day the site audit and the alert e-mail remind you to check it.' => 'V tento den vám audit webu a upozornění e-mailem připomenou, že je potřeba obsah zkontrolovat.',
    'On this site' => 'Na tomto webu',
    'On – visits, most-read news and traffic sources under Statistics. No cookies and no consent needed.' => 'Zapnuto – návštěvy, nejčtenější novinky a zdroje návštěv v sekci Statistika. Bez cookies a bez souhlasu.',
    'On: %d address(es) blocked now, %d request(s) refused in the last 24 hours.' => 'Zapnutý: nyní blokováno adres: %d, za posledních 24 hodin odmítnuto požadavků: %d.',
    'On: %d gallery(ies), %d shared.' => 'Zapnuto: galerií %d, sdílených %d.',
    'Once a day the site redirects an address visitors could not find to the page it is sure they meant (the same address written differently, moved to another section or language). Such a redirect is marked automatic; deleting it undoes it. Less certain candidates stay below as suggestions.' => 'Jednou denně web přesměruje adresu, kterou návštěvníci nenašli, na stránku, o které je si jistý (stejná adresa napsaná jinak, přesunutá do jiné sekce nebo jazyka). Takové přesměrování je označené jako automatické; smazáním ho vrátíte. Méně jisté kandidáty zůstávají níže jako návrhy.',
    'Once a month ends, the site keeps a report of what happened to it: requests to Claude, changes by people and by Claude, pages and news published, backups, security, the site audit, traffic, enquiries, bookings and the newsletter. It is a summary for you or your client – counts, titles and page addresses only, never personal data, hours or prices. Print it or save it as PDF, download it, or send it by e-mail.' => 'Po skončení každého měsíce si web uloží zprávu o tom, co se na něm dělo: požadavky na Clauda, změny od lidí a od Clauda, zveřejněné stránky a novinky, zálohy, zabezpečení, audit webu, návštěvnost, poptávky, rezervace a newsletter. Je to shrnutí pro vás nebo vašeho klienta – jen počty, názvy a adresy stránek, nikdy osobní údaje, hodiny ani ceny. Vytiskněte ji nebo uložte jako PDF, stáhněte ji nebo ji pošlete e-mailem.',
    'Once every number of days' => 'Jednou za zadaný počet dní',
    'Once per visit' => 'Jednou za návštěvu',
    'One H1 heading.' => 'Jeden nadpis H1.',
    'One address per line or separated by commas, at most 10. Empty = the site e-mail (Settings → General).' => 'Jedna adresa na řádek nebo oddělené čárkou, nejvýš 10. Prázdné = e-mail webu (Nastavení → Základní).',
    'One address per line; each becomes its own redirect.' => 'Jedna adresa na řádek; každá se stane samostatným přesměrováním.',
    'One archive gives you the whole site in an open format (JSON): pages, news, categories, tags, redirects, menus, collections, pop-ups, site parts, components, shared classes and uploaded files – as a content backup or for moving elsewhere. Enquiries, passwords, keys and accounts are not included.' => 'Jedním archivem dostanete celý web v otevřeném formátu (JSON): stránky, novinky, kategorie, štítky, přesměrování, menu, kolekce, pop-up okna, části webu, komponenty, sdílené třídy a nahrané soubory – jako zálohu obsahu nebo pro převod jinam. Poptávky, hesla, klíče ani účty v něm nejsou.',
    'One company, one contact, a clear price. You focus on your work, we handle the rest.' => 'Jedna firma, jeden kontakt, jasná cena. Vy se věnujete svému, my ostatnímu.',
    'One day or range of days per line: “Mo–Fr 8:00–17:00”, “Sa 9–12”, “Su closed”, lunch break “Tu 8–12, 13–17”. Empty = no opening hours.' => 'Každý řádek jeden den nebo rozsah dnů: „Po–Pá 8:00–17:00“, „So 9–12“, „Ne zavřeno“, polední pauza „Út 8–12, 13–17“. Prázdné = bez otevírací doby.',
    'One day: fill in only the first date.' => 'Jeden den: vyplňte jen první datum.',
    'One family' => 'Jedna rodina',
    'One family, geometric' => 'Jedna rodina, geometrická',
    'One line: the company name, the footer menu and the copyright.' => 'Jeden řádek: název firmy, menu patičky a copyright.',
    'One of the times is not free for this person – pick them from the free times.' => 'Některý z termínů není pro tuto osobu volný – vyberte je z volných termínů.',
    'One or two sentences for search results (up to 160 characters). Empty = the beginning of the first longer text field.' => 'Jedna dvě věty do výsledků hledání (do 160 znaků). Prázdné = začátek prvního delšího textového pole.',
    'One or two sentences on what visitors will find on the page (up to 160 characters).' => 'Jedna až dvě věty, co na stránce návštěvník najde (do 160 znaků).',
    'One or two sentences – a motto, a description for search engines and RSS.' => 'Jedna až dvě věty – motto, popis pro vyhledávače a RSS.',
    'One per line, e.g. 203.0.113.7 or 198.51.100.0/24; a comment after #.' => 'Jedna na řádek, např. 203.0.113.7 nebo 198.51.100.0/24; poznámka za #.',
    'One per line, up to five. The page is checked against the first.' => 'Jedno na řádek, nejvýše pět. Stránka se kontroluje podle prvního.',
    'One photo per line: path | description' => 'Jedna fotka na řádek: cesta | popis',
    'One prominent testimonial in the centre.' => 'Jedna výrazná reference na středu.',
    'Online booking of an appointment: a service, a person, a day and a free time – the bookings are in Bookings and arrive by e-mail.' => 'Online rezervace termínu: služba, člověk, den a volný čas – rezervace jsou v Rezervacích a chodí e-mailem.',
    'Online booking of appointments: the Booking element in the builder, services and people with their hours, reminders by e-mail and the Bookings list in the administration.' => 'Online objednávání termínů: prvek Rezervace v builderu, služby a lidé s pracovní dobou, připomínky e-mailem a přehled rezervací v administraci.',
    'Online link' => 'Odkaz na online účast',
    'Only JPG, PNG and WebP images are allowed.' => 'Povoleny jsou jen obrázky JPG, PNG a WebP.',
    'Only JPG, PNG, WebP and GIF images are allowed.' => 'Povolené jsou jen obrázky JPG, PNG, WebP a GIF.',
    'Only a JPG, PNG or WebP image can be replaced.' => 'Nahradit jde jen obrázek JPG, PNG nebo WebP.',
    'Only a booking waiting for confirmation can be accepted.' => 'Přijmout lze jen rezervaci čekající na potvrzení.',
    'Only a booking waiting for confirmation can be declined.' => 'Odmítnout lze jen rezervaci čekající na potvrzení.',
    'Only a booking waiting for confirmation can get other times.' => 'Jiné termíny lze navrhnout jen rezervaci čekající na potvrzení.',
    'Only a confirmed booking can be cancelled.' => 'Zrušit lze jen potvrzenou rezervaci.',
    'Only a confirmed booking can be marked.' => 'Označit lze jen potvrzenou rezervaci.',
    'Only administration users see it – e.g. what you offered the customer.' => 'Vidí ji jen uživatelé administrace – např. co jste zákazníkovi nabídli.',
    'Only an administrator can handle personal data requests.' => 'Žádosti o osobní údaje vyřizuje jen administrátor.',
    'Only an administrator can remove sections.' => 'Sekce smí odebrat jen správce.',
    'Only an administrator changes the booking set-up.' => 'Nastavení rezervací mění jen správce.',
    'Only an administrator edits a shared class – a change applies to the whole website at once. Set the look of a single element in its style.' => 'Sdílenou třídu upravuje jen správce – změna se hned projeví na celém webu. Vzhled jednoho prvku nastavíte v jeho stylu.',
    'Only an editor or administrator can edit a published news item.' => 'Vydanou novinku může upravit jen editor nebo správce.',
    'Only an editor or administrator can publish. Your changes stay saved as a draft.' => 'Publikovat smí jen editor nebo správce. Změny zůstávají uložené jako koncept.',
    'Only an editor or administrator edits, publishes and deletes published pages. You can prepare a new hidden page.' => 'Zveřejněné stránky upravuje, zveřejňuje a maže jen editor nebo správce. Můžete připravit novou skrytou stránku.',
    'Only at certain times' => 'Jen v určitých časech',
    'Only by clicking a link or button' => 'Jen kliknutím na odkaz nebo tlačítko',
    'Only create the link' => 'Jen vytvořit odkaz',
    'Only for a hidden item.' => 'Jen pro skrytou položku.',
    'Only for a hidden page.' => 'Jen pro skrytou stránku.',
    'Only for the goal “a link or button is clicked”: the address as it is in the link, e.g. /contact or tel:+441234567890.' => 'Jen pro cíl „klik na odkaz nebo tlačítko“: adresa tak, jak je v odkazu, např. /kontakt nebo tel:+420123456789.',
    'Only for this page, after the code for the whole site (Settings → Analytics) – e.g. the conversion tag of a landing page. Mind the cookie consent: code that tracks visitors belongs in the marketing code.' => 'Jen pro tuto stránku, za kódem pro celý web (Nastavení → Analytika) – např. konverzní značka vstupní stránky. Pozor na souhlas s cookies: kód, který sleduje návštěvníky, patří do marketingového kódu.',
    'Only for you in the admin and for screen readers. The address #popup-… is made from the name.' => 'Jen pro vás v administraci a pro čtečky obrazovky. Z názvu vznikne adresa #popup-…',
    'Only for your own installation, e.g. https://plausible.example.cz/ – empty means plausible.io.' => 'Jen pro vlastní instalaci, např. https://plausible.example.cz/ – prázdné znamená plausible.io.',
    'Only for your own installation, e.g. https://umami.example.cz/ – empty means Umami Cloud.' => 'Jen pro vlastní instalaci, např. https://umami.example.cz/ – prázdné znamená Umami Cloud.',
    'Only for “Another service via a webhook”: the site sends JSON with the event subscribed or unsubscribed and the e-mail.' => 'Jen u volby „Jiná služba přes webhook“: web pošle JSON s událostí subscribed nebo unsubscribed a e-mailem.',
    'Only for “a section or an element”. Choose a section for a block, a heading or a button for a single piece of text.' => 'Jen pro „sekci nebo prvek“. Pro celý blok vyberte sekci, pro jediný text nadpis nebo tlačítko.',
    'Only for “a whole page”.' => 'Jen pro „celou stránku“.',
    'Only from a campaign' => 'Jen z kampaně',
    'Only from a referrer' => 'Jen odkud přišel',
    'Only from category (address, optional)' => 'Jen z kategorie (adresa, nepovinné)',
    'Only https:// addresses are allowed.' => 'Povolené jsou jen adresy https://.',
    'Only in a draft' => 'Jen v konceptu',
    'Only items with the value (on an item page also {{field}} – related content)' => 'Jen položky s hodnotou (na stránce položky i {{pole}} – související obsah)',
    'Only necessary' => 'Jen nezbytné',
    'Only one item open at a time' => 'Otevřená vždy jen jedna položka',
    'Only own news and without publishing – an editor publishes.' => 'Novinky jen své a bez vydávání – vydává editor.',
    'Only reviews with at least this many stars' => 'Jen recenze s alespoň tolika hvězdičkami',
    'Only someone who may publish can undo a published change.' => 'Zveřejněnou změnu může vrátit jen ten, kdo smí publikovat.',
    'Only the %title% part changes; the site name and the tagline keep the way you wrote them.' => 'Mění se jen část %title%; název webu a slogan zůstanou tak, jak jste je napsali.',
    'Only the ID is needed. The pixels run only after the visitor allows marketing in the cookie bar (the Privacy and cookies tab) and appear in the cookie table.' => 'Stačí ID. Pixely se spustí až poté, co návštěvník v cookie liště povolí marketing (záložka Soukromí a cookies), a objeví se v tabulce cookies.',
    'Only the first %d notes are shown – narrow the list by a topic or a search.' => 'Zobrazuje se jen prvních %d poznámek – zužte výpis tématem nebo hledáním.',
    'Only the header and footer can have variants.' => 'Varianty mají jen záhlaví a patička.',
    'Only the list of news.' => 'Jen výpis novinek.',
    'Only the logo and one button – for a campaign page without the menu.' => 'Jen logo a jedno tlačítko – pro kampaňovou stránku bez menu.',
    'Only the message and the links from the system.' => 'Jen hláška a odkazy od systému.',
    'Only the news item.' => 'Jen novinka.',
    'Only the owner of an image or an administrator can describe it.' => 'Obrázek může popsat jen jeho vlastník nebo správce.',
    'Only the rows you change are saved; nothing is published that was not before.' => 'Uloží se jen řádky, které změníte; nic se nezveřejní, co předtím zveřejněné nebylo.',
