    'Optional, for example “See all news” or “Book an appointment”.' => 'Nepovinné, například „Všechny novinky“ nebo „Objednat se“.',
    'Optional. Published content needs no sign-in. For unpublished content type user:password (HTTP Basic authentication must be switched on in Drupal) or an access token.' => 'Nepovinné. Publikovaný obsah přihlášení nepotřebuje. Pro nepublikovaný obsah zadejte uživatel:heslo (v Drupalu musí být zapnuté HTTP Basic authentication) nebo přístupový token.',
    'Optional. Shown above the news list and as the description for search engines.' => 'Nepovinné. Zobrazí se nad výpisem novinek a jako popis pro vyhledávače.',
    'Optional. What you enter is saved as your company details and used on the site; what you leave empty stays open.' => 'Nepovinné. Co zadáte, uloží se jako údaje o firmě a použije se na webu; co necháte prázdné, zůstane otevřené.',
