    'Rows with a price, a unit and a note, grouped by category with filter buttons for visitors; the rows have no pages of their own.' => 'Řádky s cenou, jednotkou a poznámkou, seskupené podle kategorie s filtrovacími tlačítky pro návštěvníky; řádky nemají vlastní stránky.',
    'Run site_audit. Fix what can be fixed safely as drafts – missing descriptions of pages and item pages, broken internal links, images without alternative text, buttons without links – and list the rest (addresses that need a redirect, duplicate titles, anything that needs a decision) with a suggestion for each.' => 'Spusť site_audit. Co jde bezpečně opravit, oprav jako koncepty – chybějící popisky stránek a stránek položek, rozbité interní odkazy, obrázky bez alternativního textu, tlačítka bez odkazu – a zbytek (adresy, které potřebují přesměrování, duplicitní titulky, cokoli, co vyžaduje rozhodnutí) vypiš s návrhem ke každému.',
    'Run triage_enquiries on the new enquiries. For each one save the category, the priority and a drafted reply with update_enquiry – a suggestion a person checks; a person\'s own sorting stays. A reply is a draft a person sends – never send anything yourself.' => 'Spusť triage_enquiries na nové poptávky. Ke každé ulož kategorii, prioritu a koncept odpovědi přes update_enquiry – je to návrh, který zkontroluje člověk; třídění, které udělal člověk, zůstává. Odpověď je koncept, který odešle člověk – sám nikdy nic neodesílej.',
