    'Tag' => 'Štítek',
    'Tag deleted. The news items remain, they just no longer carry it.' => 'Štítek byl smazán. Novinky zůstaly, jen ho už nemají.',
    'Tag manager: limits the number of requests' => 'Správce značek: omezuje počet požadavků',
    'Tag saved.' => 'Štítek byl uložen.',
    'Tag suggestions' => 'Návrh štítků',
    'Tag without an introduction' => 'Štítek bez úvodu',
    'Tag “%s” has been merged into “%s”.' => 'Štítek „%s“ byl sloučen do „%s“.',
    'Tags' => 'Štítky',
    'Tags and topics' => 'Štítky a témata',
    'Tags are created automatically as you write news. When you add a description to a tag, its page becomes a topic – an introduction to a field or project with all its news in one place.' => 'Štítky vznikají samy při psaní novinek. Když štítku doplníte popis, stane se z jeho stránky téma – úvod k oboru nebo projektu se všemi novinkami na jednom místě.',
    'Tailored design' => 'Návrh na míru',
    'Take a photo' => 'Vyfotit',
    'Taken down' => 'Sejmuto',
    'Taken down on' => 'Sejmuto dne',
    'Takes bookings' => 'Přijímá rezervace',
    'Takes the newest news items at the time of sending – write the introduction once, send whenever.' => 'Vezme nejnovější příspěvky v okamžiku odeslání – úvod napíšete jednou, posíláte kdykoli.',
    'Talea export' => 'Export Talea',
    'Talea installation' => 'Instalace Talea',
    'Talea is already installed' => 'Talea je už nainstalovaná',
    'Talea is free and has no ads.' => 'Talea je zdarma a bez reklam.',
    'Talea never sends the draft by itself. Read it, then reply by e-mail.' => 'Talea koncept sama neodešle. Přečtěte si ho a pak odpovězte e-mailem.',
    'Talea noticed something that needs your attention:' => 'Talea si všimla něčeho, co potřebuje vaši pozornost:',
    'Talea reads the sitemap, or follows the site’s links when there is none – at most %s pages.' => 'Talea přečte mapu webu (sitemap), a když chybí, projde odkazy webu – nejvýš %s stránek.',
    'Talea sends these events to the data layer for your tags: generate_lead (a form was sent), sign_up (newsletter), popup_conversion, click_phone, click_email and file_download.' => 'Talea posílá do datové vrstvy pro vaše značky tyto události: generate_lead (odeslaný formulář), sign_up (newsletter), popup_conversion, click_phone, click_email a file_download.',
    'Tap the place on the page to move the element to (top or bottom part of an element = before or after, middle of a container = inside). Esc cancels.' => 'Klepněte na místo na stránce, kam prvek přesunout (horní nebo dolní část prvku = před nebo za, střed kontejneru = dovnitř). Esc zruší.',
    'Target' => 'Cíl',
    'Target folder' => 'Cílová složka',
    'Task' => 'Úkol',
    'Team' => 'Tým',
    'Technical' => 'Technické',
    'Technology' => 'Technologie',
    'Tell search engines what the items are. Item pages then carry the schema.org data; the name, address, description and image come from the item itself. Save new fields first – then you can pick them here.' => 'Řekněte vyhledávačům, co položky jsou. Stránky položek pak ponesou data schema.org; název, adresa, popis a obrázek se berou z položky. Nová pole nejdřív uložte – pak je tu půjde vybrat.',
    'Tell us what you need – we will get back to you within one business day.' => 'Popište, co potřebujete – ozveme se vám do jednoho pracovního dne.',
    'Tells search engines about a new or changed page the moment it is published, instead of waiting for the next visit.' => 'Oznámí vyhledávačům novou nebo změněnou stránku hned po zveřejnění, místo čekání na další návštěvu.',
    'Tells search engines what a page is: an article, a product, an event, a recipe, a business.' => 'Říká vyhledávačům, co stránka je: článek, produkt, událost, recept, firma.',
    'Template' => 'Šablona',
    'Templates assembled from what the site is set up to do – review and complete them, they are not legal advice.' => 'Šablony sestavené z toho, co má web nastaveno – zkontrolujte a doplňte je, nejsou právní radou.',
    'Templates: %s' => 'Šablony: %s',
    'Temporary' => 'Dočasné',
    'Temporary (302)' => 'Dočasné (302)',
    'Temporary, keeps the request method (307)' => 'Dočasné, zachová metodu požadavku (307)',
    'Test' => 'Zkouška',
    'Test message from %s' => 'Zkušební zpráva z %s',
    'Test redirect' => 'Vyzkoušet přesměrování',
    'Test: %s – version B' => 'Test: %s – verze B',
    'Testimonial' => 'Reference',
    'Testimonial requests: %d' => 'Žádosti o referenci: %d',
    'Testimonials' => 'Reference',
    'Testimonials and projects' => 'Reference a realizace',
    'Text alignment' => 'Zarovnání textu',
    'Text and buttons on the left, image on the right; stacked on phones.' => 'Text a tlačítka vlevo, obrázek vpravo; na telefonu pod sebou.',
    'Text below the field' => 'Text pod polem',
    'Text colour' => 'Barva textu',
    'Text colour while the header is transparent' => 'Barva textu, dokud je záhlaví průhledné',
    'Text font' => 'Písmo textu',
    'Text history (%s)' => 'Historie textu (%s)',
    'Text in the utm_* parameters of the address the visitor arrived with (e.g. spring or newsletter). Empty = everyone.' => 'Text v parametrech utm_* adresy, se kterou návštěvník přišel (např. jaro nebo newsletter). Prázdné = všichni.',
    'Text in two columns' => 'Text ve dvou sloupcích',
    'Text next to the stars' => 'Text vedle hvězdiček',
    'Text on background' => 'Text na pozadí',
    'Text on primary' => 'Text na hlavní',
    'Text on surface' => 'Text na ploše',
    'Text on the left, a ticked list on the right.' => 'Text vlevo, seznam s fajfkami vpravo.',
    'Text rewritten – Ctrl+Z undoes it.' => 'Text přepsán – Ctrl+Z ho vrátí.',
    'Text should have a contrast of at least 4.5 : 1 (WCAG AA). Pairs marked in red will be hard to read for some visitors.' => 'Text by měl mít kontrast aspoň 4,5 : 1 (WCAG AA). Červeně označené dvojice budou pro část návštěvníků špatně čitelné.',
    'Text when finished' => 'Text po skončení',
    'Text when the collection has no items' => 'Text, když kolekce nemá položky',
    'Text width' => 'Šířka textu',
    'Text width (news and text pages)' => 'Šířka textu (novinky a textové stránky)',
    'Text “%s” has low contrast against its background (%d : 1) – it is hard to read.' => 'Text „%s“ má na svém pozadí slabý kontrast (%d : 1) – špatně se čte.',
    'Texts for visitors (Search, Read more, form messages, the cookie bar…) are not translated into %s yet: the site shows them in English.' => 'Texty pro návštěvníky (Hledat, Číst dál, hlášky formulářů, cookie lišta…) zatím nejsou přeložené do jazyka %s: web je ukazuje anglicky.',
    'Texts for visitors (Search, Read more…) are translated into: %s. Other languages show them in English, with dates in their own format. You write the content of pages and news in the language of the version.' => 'Texty pro návštěvníky (Hledat, Číst dál…) jsou přeložené do jazyků: %s. Ostatní jazyky je mají anglicky, datum ve svém tvaru. Obsah stránek a novinek píšete v jazyce verze.',
    'Texts for visitors are not translated into %s yet: these versions show Search, Read more, form messages and the cookie bar in English.' => 'Texty pro návštěvníky zatím nejsou přeložené do: %s. Tyto verze ukazují Hledat, Číst dál, hlášky formulářů a cookie lištu anglicky.',
    'Thank you for your application. We will get back to you.' => 'Děkujeme za vaši žádost. Ozveme se vám.',
    'Thank you – you are registered. We will send you the details before the event.' => 'Děkujeme, jste zaregistrováni. Podrobnosti vám pošleme před akcí.',
    'Thank you! We have sent you an e-mail with a link – click it to confirm your subscription.' => 'Děkujeme! Poslali jsme vám e-mail s odkazem – odběr potvrďte kliknutím na něj.',
    'Thank you! We will send you the guide by e-mail.' => 'Děkujeme! Průvodce vám pošleme e-mailem.',
    'Thank you, we have received your enquiry. We will get back to you with prices and availability.' => 'Děkujeme, poptávku jsme přijali. Ozveme se s cenami a dostupností.',
    'Thank you, we have received your message. We will get back to you as soon as possible.' => 'Děkujeme, zprávu jsme dostali. Ozveme se vám co nejdřív.',
    'Thank you, we will send news to %s. You can unsubscribe using the link in every e-mail.' => 'Děkujeme, novinky vám budeme posílat na %s. Odhlásit se můžete odkazem v každém e-mailu.',
    'Thank you. Home no longer points to the instructions until they change again.' => 'Děkujeme. Úvod na pokyny znovu upozorní, až se změní.',
    'Thank-you after a request' => 'Poděkování po žádosti',
    'Thank-you message' => 'Poděkování po odeslání',
    'That was too fast. Please try again in a few seconds.' => 'To bylo příliš rychlé. Zkuste to prosím znovu za pár vteřin.',
    'The %s API key is not valid. Check it under Settings → Writing assistant.' => 'Klíč API služby %s není platný. Zkontrolujte ho v Nastavení → Asistent psaní.',
    'The %s account has run out of credit.' => 'Na účtu služby %s došel kredit.',
    'The <x> of <x>.pipedrive.com' => 'To <x> z <x>.pipedrive.com',
    'The AI is not connected to this site yet – requests wait until an administrator connects it.' => 'AI zatím není k webu připojená – požadavky počkají, než ji připojí správce.',
    'The AI is not connected to this site yet, so requests wait until it is.' => 'AI zatím není k webu připojená, požadavky proto počkají, než bude.',
    'The API does not say an article’s address. Old addresses are the best guess /category-path/id-alias; SEF URL rewriting differs per site, so check the redirects with the migration report after the import.' => 'API neříká adresu článku. Staré adresy jsou nejlepší odhad /cesta-rubriky/id-alias; přepisování SEF adres se liší web od webu, proto přesměrování po importu zkontrolujte podle zprávy o migraci.',
    'The API is not available at this address (the site answered 404). Check the address and that the API is switched on.' => 'API na této adrese není (web odpověděl 404). Zkontrolujte adresu a že je API zapnuté.',
    'The API key is missing – an administrator enters it under Settings → Writing assistant.' => 'Chybí klíč API – administrátor ho zadá v Nastavení → Asistent psaní.',
    'The Claude connection is switched off (Features) – requests are saved, but nobody reads them until it is on.' => 'Napojení Clauda je vypnuté (Funkce) – požadavky se ukládají, ale dokud ho nezapnete, nikdo je nečte.',
    'The Claude connection is switched off (Features) – the schedules are kept, but no routine can pick the runs up until it is on.' => 'Připojení Clauda je vypnuté (Funkce) – plány zůstávají, ale dokud ho nezapnete, žádná rutina si běhy nevyzvedne.',
    'The Claude connection is switched off.' => 'Napojení na Claude je vypnuté.',
    'The Claude connection “%s” of %s has not been used for %d days – revoke it, or let the automatic suspension do it.' => 'Napojení Clauda „%s“ uživatele %s nikdo %d dní nepoužil – zrušte ho, nebo to nechte na automatickém pozastavení.',
    'The Form element in the builder and the Enquiries inbox: submitted enquiries are stored, arrive by e-mail and can be passed to a colleague or a CRM.' => 'Prvek Formulář v builderu a schránka Poptávky: odeslané dotazy se uloží, přijdou e-mailem a jdou předat kolegovi nebo do CRM.',
    'The GD extension for image processing is missing on the server.' => 'Na serveru chybí rozšíření GD pro práci s obrázky.',
    'The Google account manages no Business Profile location.' => 'Účet Google nespravuje žádnou pobočku firemního profilu.',
    'The ID of the list (Brevo, Ecomail, SmartEmailing), group (MailerLite) or audience (Mailchimp) – you find it in the list settings in the service.' => 'ID seznamu (Brevo, Ecomail, SmartEmailing), skupiny (MailerLite) nebo audience (Mailchimp) – najdete ho v nastavení seznamu ve službě.',
    'The Newsletter sign-up element in the builder: visitors enter an e-mail and confirm it by a link (double opt-in). Send them your latest news in an e-mail styled by the design system (through an SMTP server, while cron runs), pass confirmed subscribers to your mailing service (Brevo, MailerLite, Mailchimp, Ecomail, SmartEmailing, webhook), or export them to CSV.' => 'Prvek Odběr novinek v builderu: návštěvník zadá e-mail a potvrdí ho odkazem (double opt-in). Novinky jim pošlete e-mailem ve vzhledu design systému (přes SMTP server, když běží cron), potvrzené odběratele předáte do mailingové služby (Brevo, MailerLite, Mailchimp, Ecomail, SmartEmailing, webhook), nebo je vyexportujete do CSV.',
    'The Newsletter sign-up element in the builder: visitors enter an e-mail and confirm it by a link (double opt-in). The site sends confirmed subscribers to your mailing service (Brevo, MailerLite, Mailchimp, Ecomail, SmartEmailing, webhook), or you export them to CSV.' => 'Prvek Odběr novinek v builderu: návštěvník zadá e-mail a potvrdí ho odkazem (double opt-in). Potvrzené odběratele web pošle do vaší mailingové služby (Brevo, MailerLite, Mailchimp, Ecomail, SmartEmailing, webhook), nebo je vyexportujete do CSV.',
    'The PHP extension curl is missing on the server – the site’s API cannot be read without it.' => 'Na serveru chybí rozšíření PHP curl – bez něj nelze API webu číst.',
    'The PHP extension for FTP is missing on the server.' => 'Na serveru chybí rozšíření PHP pro FTP.',
    'The PHP extension xmlreader or dom is missing on the server – a WordPress export cannot be read without them.' => 'Na serveru chybí rozšíření PHP xmlreader nebo dom – bez nich nejde export z WordPressu přečíst.',
    'The PHP zip extension is missing on the server – upload obsah.json from the archive instead.' => 'Na serveru chybí rozšíření PHP zip – nahrajte místo archivu soubor obsah.json z něj.',
    'The PHP zip extension is missing on the server, so the export contains data only (JSON). Download the media/ folder over FTP.' => 'Na serveru chybí rozšíření PHP zip, export proto obsahuje jen data (JSON). Složku media/ si stáhněte přes FTP.',
    'The Redirects feature is off: no redirect from an old address works.' => 'Funkce Přesměrování je vypnutá: žádné přesměrování ze staré adresy nefunguje.',
    'The SMTP server address is not valid.' => 'Adresa SMTP serveru nemá platný tvar.',
    'The SMTP server did not respond in time.' => 'SMTP server neodpověděl včas.',
    'The SMTP server refused the sign-in – check the user name and password (Gmail and Seznam need an app password).' => 'SMTP server odmítl přihlášení – zkontrolujte jméno a heslo (u Gmailu a Seznamu je potřeba „heslo pro aplikace“).',
    'The SVG file could not be read (max. 2 MB, valid SVG).' => 'Soubor SVG se nepodařilo přečíst (nejvýš 2 MB, platné SVG).',
    'The accessibility statement is ready as a hidden page – review it, then publish it: %s' => 'Prohlášení o přístupnosti je připraveno jako skrytá stránka – zkontrolujte ho a pak zveřejněte: %s',
    'The account %s has not been used for %d days (last activity %s) – block it, or let the automatic suspension do it.' => 'Účet %s nikdo %d dní nepoužil (poslední aktivita %s) – zablokujte ho, nebo to nechte na automatickém pozastavení.',
    'The account has been reactivated – the user can sign in again.' => 'Účet je znovu aktivní – uživatel se může zase přihlásit.',
    'The account has no Search Console property. Add the site at search.google.com/search-console first.' => 'Účet nemá v Search Console žádnou vlastnost. Nejdřív web přidejte na search.google.com/search-console.',
    'The account is blocked – it cannot sign in to the administration.' => 'Účet je zablokovaný – do administrace se nepřihlásí.',
    'The account is blocked. Contact an administrator.' => 'Účet je zablokován. Obraťte se na administrátora.',
    'The account is not blocked.' => 'Účet není zablokovaný.',
    'The account is temporarily locked after a series of failed attempts. Try again in 15 minutes.' => 'Účet je po řadě chybných pokusů dočasně zamčený. Zkuste to znovu za 15 minut.',
    'The account you will first sign in to the administration with.' => 'Účet, kterým se poprvé přihlásíte do administrace.',
    'The add-on %s failed and was switched off: %s' => 'Doplněk %s selhal a byl vypnut: %s',
    'The add-on %s was switched on.' => 'Doplněk %s byl zapnut.',
    'The add-on %s was uninstalled.' => 'Doplněk %s byl odinstalován.',
    'The add-on could not be switched on: %s' => 'Doplněk se nepodařilo zapnout: %s',
    'The add-on could not be uninstalled: %s' => 'Doplněk se nepodařilo odinstalovat: %s',
    'The add-on failed: %s' => 'Doplněk selhal: %s',
    'The add-on is switched off – its data stays.' => 'Doplněk je vypnutý – jeho data zůstávají.',
    'The add-on is switched on.' => 'Doplněk je zapnutý.',
    'The add-on is uninstalled and its data deleted. Delete its folder in extensions/ to remove the code.' => 'Doplněk je odinstalován a jeho data smazána. Kód odstraníte smazáním jeho složky v extensions/.',
    'The add-on is uninstalled, its data is kept. Delete its folder in extensions/ to remove the code.' => 'Doplněk je odinstalován, jeho data zůstala. Kód odstraníte smazáním jeho složky v extensions/.',
    'The add-on page does not exist or its add-on is switched off.' => 'Stránka doplňku neexistuje nebo je její doplněk vypnutý.',
    'The address and the target are the same.' => 'Adresa a cíl jsou stejné.',
    'The address as it is registered there, e.g. https://example.com/ – empty = this site’s address.' => 'Adresa, jak je tam zaregistrovaná, např. https://example.com/ – prázdné = adresa tohoto webu.',
    'The address does not belong to the old site, or it is not a public http(s) address on the standard port.' => 'Adresa nepatří starému webu, nebo to není veřejná adresa http(s) na standardním portu.',
    'The address does not belong to the old site.' => 'Adresa nepatří starému webu.',
    'The address has %d characters.' => 'Adresa má %d znaků.',
    'The address is no longer blocked.' => 'Adresa už není blokovaná.',
    'The address of your installation, e.g. https://statistiky.example.cz/' => 'Adresa vaší instalace, např. https://statistiky.example.cz/',
    'The address or pattern must be 1 to 255 characters.' => 'Adresa nebo vzor musí mít 1 až 255 znaků.',
    'The address “%s” is already used by the system or another collection.' => 'Adresu „%s“ už používá systém nebo jiná kolekce.',
    'The administrator %s signs in without two-step sign-in or a passkey.' => 'Správce %s se přihlašuje bez dvoufázového ověření i bez přístupového klíče.',
    'The agency or freelancer who looks after the site. The sign-in screen and the foot of the admin show whom to ask for help.' => 'Agentura nebo freelancer, který se o web stará. Přihlašovací obrazovka a spodní okraj administrace ukážou, na koho se obrátit s pomocí.',
    'The answer is larger than the fetch allows (8 MB per page, 48 MB in total).' => 'Odpověď je větší, než stažení dovoluje (8 MB na stránku, 48 MB celkem).',
    'The answers are kept' => 'Odpovědi zůstávají',
    'The answers are saved – the site states them as facts.' => 'Odpovědi jsou uložené – web je uvádí jako fakty.',
    'The application did not register correctly with this website (unknown client or return address). Please connect it again.' => 'Aplikace se na tomto webu neohlásila správně (neznámý klient nebo adresa pro návrat). Připojte ji prosím znovu.',
    'The application is disconnected – it will not get into the website until you allow it again.' => 'Aplikace je odpojená – do webu se už nedostane, dokud ji znovu nepovolíte.',
    'The application sent an incomplete sign-in request, so it was stopped here. Please connect it again.' => 'Aplikace poslala neúplný požadavek na přihlášení, proto se zastavil tady. Připojte ji prosím znovu.',
    'The archive could not be created – check write permissions for storage/backups.' => 'Archiv se nepodařilo vytvořit - zkontrolujte práva k zápisu do storage/backups.',
    'The archive could not be finished – the disk is probably full.' => 'Archiv se nepodařilo dokončit - nejspíš došlo místo na disku.',
    'The assistant checks spelling, typos and typography' => 'Asistent zkontroluje pravopis, překlepy a typografii',
    'The assistant did not respond.' => 'Asistent neodpověděl.',
    'The assistant did not return a usable section. Try refining the description.' => 'Asistent nevrátil použitelnou sekci. Zkuste popis upřesnit.',
    'The assistant drafts texts and layout in your site\'s style. Check the result – fill in facts (numbers, prices, names) yourself.' => 'Asistent navrhne texty i rozložení ve stylu vašeho webu. Výsledek zkontrolujte – fakta (čísla, ceny, jména) doplňte sami.',
    'The assistant found nothing to change. Try asking in other words.' => 'Asistent nenašel nic ke změně. Zkuste to říct jinými slovy.',
    'The assistant is drafting a section…' => 'Asistent navrhuje sekci…',
    'The assistant is rewriting the text…' => 'Asistent přepisuje text…',
    'The assistant only suggests – a person decides on every change. When used, the text is sent to the chosen provider; nothing is sent anywhere without clicking an assistant button.' => 'Asistent jen navrhuje – o každé změně rozhoduje člověk. Při použití se text odešle zvolenému poskytovateli; bez kliknutí na tlačítko asistenta se nikam nic neposílá.',
    'The assistant plans the pages and writes first texts with your own AI key – you review the plan first.' => 'Asistent s vaším vlastním klíčem AI naplánuje stránky a napíše první texty – plán nejdřív zkontrolujete.',
    'The assistant reports an error (%s): %s' => 'Asistent hlásí chybu (%s): %s',
    'The assistant returned an incomplete translation. Please try again.' => 'Asistent vrátil neúplný překlad. Zkuste to prosím znovu.',
    'The assistant rewrote the drafts – read them before posting.' => 'Asistent návrhy přepsal – před zveřejněním si je přečtěte.',
    'The assistant suggested nothing.' => 'Asistent nic nenavrhl.',
    'The assistant suggested nothing. Try again.' => 'Asistent nic nenavrhl. Zkuste to znovu.',
    'The assistant suggests the kind, the priority and a reply; the text of each enquiry is then sent to the AI provider chosen in Features – mention it in your privacy policy. Claude can sort enquiries over its connection without this.' => 'Asistent navrhne druh, prioritu a odpověď; text každé poptávky se pak posílá poskytovateli AI zvolenému ve Funkcích – uveďte to v zásadách ochrany osobních údajů. Claude umí poptávky třídit přes své napojení i bez toho.',
    'The assistant suggests wording based on the text' => 'Asistent navrhne znění podle textu',
    'The assistant writes each page when you create the drafts, from the brief. This sends the brief and your answers to %s.' => 'Asistent napíše každou stránku podle zadání, až vytvoříte koncepty. Tím se zadání a vaše odpovědi odešlou poskytovateli %s.',
    'The assistant\'s reply could not be read. Please try again.' => 'Asistent odpověděl nečitelně. Zkuste to prosím znovu.',
    'The attachment %s could not be saved: %s' => 'Přílohu %s nejde uložit: %s',
    'The attachment no longer exists.' => 'Příloha už neexistuje.',
    'The audit found nothing to fix.' => 'Audit nenašel nic k opravě.',
    'The automatic backup failed: %s' => 'Automatická záloha selhala: %s',
    'The background job “%s” failed %d times in a row: %s' => 'Úloha na pozadí „%s“ selhala %d× za sebou: %s',
    'The background job “%s” works again.' => 'Úloha na pozadí „%s“ zase funguje.',
    'The background jobs store the report for %s within an hour. Earlier months cannot be made any more: what they would be built from is kept only 30 to 180 days.' => 'Úlohy na pozadí uloží zprávu za období %s do hodiny. Dřívější měsíce už vytvořit nejde: data, ze kterých by vznikly, se uchovávají jen 30 až 180 dní.',
    'The backup could not be created: %s' => 'Zálohu se nepodařilo vytvořit: %s',
    'The backup is incomplete or damaged (the end of the file is missing) – the restore was stopped.' => 'Záloha je neúplná nebo poškozená (chybí konec souboru) – obnova byla zastavena.',
    'The best company we have ever worked with. They kept every deadline and the result exceeded our expectations.' => 'Nejlepší firma, se kterou jsme kdy spolupracovali. Termíny drželi na den a výsledek předčil naše očekávání.',
    'The blueprint is applied: %d new collections (with hidden list pages) and %d facts. Answer its questions below.' => 'Plán je použitý: %d nových kolekcí (se skrytými stránkami výpisu) a %d faktů. Odpovězte níže na jeho otázky.',
    'The blueprint is removed – its collections and facts stay.' => 'Plán je odebraný – jeho kolekce a fakty zůstávají.',
    'The booking does not exist.' => 'Rezervace neexistuje.',
    'The booking form on the page is submitted.' => 'Odešle se rezervační formulář na stránce.',
    'The booking is accepted and the customer got the confirmation.' => 'Rezervace je přijata a zákazník dostal potvrzení.',
    'The booking is accepted.' => 'Rezervace je přijata.',
    'The booking is cancelled and the customer was told by e-mail.' => 'Rezervace je zrušena a zákazník to dostal e-mailem.',
    'The booking is cancelled.' => 'Rezervace je zrušena.',
    'The booking is saved and the confirmation was sent to the customer.' => 'Rezervace je uložena a zákazníkovi odešlo potvrzení.',
    'The booking is saved.' => 'Rezervace je uložena.',
    'The booking was anonymised – the row stays for statistics without the person.' => 'Rezervace byla anonymizována – řádek zůstává pro statistiky bez osoby.',
    'The build is not valid JSON.' => 'Stavba nemá platný tvar JSON.',
    'The builder has changes that are not on the site yet.' => 'V builderu jsou změny, které ještě nejsou na webu.',
    'The builder has work-in-progress changes that are not on the site yet.' => 'V builderu jsou rozpracované změny, které ještě nejsou na webu.',
    'The builder needs JavaScript. The page content can also be edited without it in the page form.' => 'Builder potřebuje JavaScript. Obsah stránky jde upravit i bez něj ve formuláři stránky.',
    'The builder needs a larger screen.' => 'Builder potřebuje větší obrazovku.',
    'The built-in protection still applies. Off = such forms are refused until the provider answers again.' => 'Vestavěná ochrana platí dál. Vypnuto = takové formuláře se odmítnou, dokud poskytovatel znovu neodpoví.',
    'The built-in roles News author, Editor and Administrator are enough for most websites. A custom role is useful when someone should see only part of the administration – for example a salesperson only Enquiries.' => 'Vestavěné role Autor novinek, Editor a Správce stačí většině webů. Vlastní role se hodí, když má někdo vidět jen část administrace – třeba obchodník jen Poptávky.',
    'The built-in statistics are off (Settings → Analytics), so there are no traffic figures.' => 'Vestavěná statistika je vypnutá (Nastavení → Měření), čísla o návštěvnosti proto nejsou.',
    'The built-in tasks are instructions for Claude; every run ends with the rules: drafts only, never publish, never delete, stop and report anything that needs a person.' => 'Připravené úkoly jsou pokyny pro Clauda; každý běh končí pravidly: jen koncepty, nikdy nepublikovat, nikdy nemazat, zastavit se a ohlásit vše, co potřebuje člověka.',
    'The button link must be an https:// address or a path on the site starting with /.' => 'Odkaz tlačítka musí být adresa https:// nebo cesta na webu začínající lomítkem.',
    'The button “%s” does not say what it does – screen readers read buttons and links on their own.' => 'Tlačítko „%s“ neříká, co dělá – čtečky obrazovky čtou tlačítka a odkazy samostatně.',
    'The button “%s” leads nowhere – add a link.' => 'Tlačítko „%s“ nikam nevede – doplňte odkaz.',
    'The category cannot be deleted while it contains news items (including those in the trash). Move them elsewhere first.' => 'Kategorii nelze smazat, dokud v ní jsou novinky (i v koši). Nejprve je přesuňte jinam.',
    'The category does not exist.' => 'Kategorie neexistuje.',
    'The check runs while you write (needs JavaScript).' => 'Kontrola běží při psaní (potřebuje JavaScript).',
    'The choice about the shared kit is saved.' => 'Volba o sdílené sadě je uložena.',
    'The chosen language version (local storage)' => 'Zvolená jazyková verze (úložiště prohlížeče)',
    'The chosen light or dark appearance (local storage)' => 'Zvolený světlý nebo tmavý vzhled (úložiště prohlížeče)',
    'The class is not used in any published or draft build yet.' => 'Třída zatím není použitá v žádné publikované ani rozpracované stavbě.',
    'The client has no account of their own yet – create one with the Client role (Users → Roles).' => 'Klient zatím nemá vlastní účet – založte mu ho s rolí Klient (Uživatelé → Role).',
    'The clipboard does not contain Talea elements.' => 'Schránka neobsahuje prvky Talea.',
    'The code does not match. Check the time on your phone and try again.' => 'Kód nesouhlasí. Zkontrolujte čas v telefonu a zkuste to znovu.',
    'The code is not correct.' => 'Kód není správný.',
    'The collection and its items were deleted.' => 'Kolekce i s položkami byla smazána.',
    'The collection does not exist.' => 'Kolekce neexistuje.',
    'The collection gets its own link in the main menu, under the heading Collections, so its items are one click away from every screen. At most %d collections are listed there, by name.' => 'Kolekce dostane vlastní odkaz v hlavním menu pod nadpisem Kolekce, takže její položky jsou z každé obrazovky na jedno kliknutí. Zobrazí se tam nejvýše %d kolekcí, seřazených podle názvu.',
    'The collection has no visible items yet.' => 'Kolekce zatím nemá žádné viditelné položky.',
    'The collection is empty.' => 'Kolekce je zatím prázdná.',
    'The collection is not an official notice board.' => 'Kolekce není úřední deska.',
    'The collection needs a name.' => 'Kolekce musí mít název.',
    'The collection was created with a hidden page that lists it – add the first items, then publish the page.' => 'Kolekce je založená i se skrytou stránkou, která ji vypisuje – přidejte první položky a pak stránku zveřejněte.',
    'The collection was created – add the first items.' => 'Kolekce je vytvořená – přidejte první položky.',
    'The collection was saved.' => 'Kolekce byla uložena.',
    'The comment does not exist.' => 'Komentář neexistuje.',
    'The company details are changed in Business details. Claude reads and changes facts with list_facts and save_fact.' => 'Údaje o firmě se mění v Údaje o firmě. Claude fakty čte a mění nástroji list_facts a save_fact.',
    'The company details for the imprint next to the footer menu and social networks.' => 'Údaje o firmě pro tiráž vedle menu patičky a sociálních sítí.',
    'The company is founded in a family garage.' => 'Založení firmy v garáži rodinného domu.',
    'The company, the footer menu, contacts and a newsletter sign-up, the copyright below.' => 'Firma, menu patičky, kontakty a přihlášení k odběru, pod tím copyright.',
    'The component does not exist.' => 'Komponenta neexistuje.',
    'The component has no properties – it looks the same everywhere.' => 'Komponenta nemá vlastnosti – u všech použití vypadá stejně.',
    'The component needs a name.' => 'Komponenta musí mít název.',
    'The component was deleted. Places where it was used will be empty.' => 'Komponenta byla smazána. Místa, kde byla použitá, zůstanou prázdná.',
    'The component was saved.' => 'Komponenta byla uložena.',
    'The component “%s” is used on: %s. Deleting it leaves an empty space there. Delete it anyway?' => 'Komponentu „%s“ používá: %s. Po smazání tam zůstane prázdné místo. Opravdu ji smazat?',
    'The config.php file exists, so the installer changes nothing.' => 'Soubor config.php existuje, instalátor proto nic nemění.',
    'The connection has been revoked – Claude can no longer sign in with it.' => 'Napojení je zrušené – Claude se s ním už nepřihlásí.',
    'The connection no longer exists.' => 'Napojení už neexistuje.',
    'The connection to the SMTP server was interrupted.' => 'Spojení se SMTP serverem se přerušilo.',
    'The connection to the assistant failed. Try again.' => 'Spojení s asistentem selhalo. Zkuste to znovu.',
    'The connector needs the site on HTTPS in the domain root.' => 'Konektor potřebuje web na HTTPS v kořeni domény.',
    'The connector needs the site on HTTPS. In a subfolder, the Claude app finds the sign-in on its own; for a tool that does not, use a personal token.' => 'Konektor potřebuje web na HTTPS. V podsložce si aplikace Claude přihlášení najde sama; nástroji, který to neumí, dejte osobní token.',
    'The console can share a design kit – its design system, shared classes, components and saved sections. Here it arrives as drafts only: into the look draft, into component drafts and into the section library. Nothing is published until you publish it. Custom code never travels in a kit.' => 'Konzole může sdílet designovou sadu – svůj design systém, sdílené třídy, komponenty a uložené sekce. Sem přijde jen jako koncepty: do konceptu vzhledu, do konceptů komponent a do knihovny sekcí. Nic se nezveřejní, dokud to nevydáte vy. Vlastní kód v sadě nikdy necestuje.',
    'The console did not confirm the report.' => 'Konzole hlášení nepotvrdila.',
    'The console did not hand over the kit (%s).' => 'Konzole sadu nepředala (%s).',
    'The console does not know this site any more – pair it again.' => 'Konzole tento web už nezná – spárujte ho znovu.',
    'The console handed over a different kit version than it announced – refused.' => 'Konzole předala jinou verzi sady, než ohlásila – odmítnuta.',
    'The console has no components.' => 'Konzole nemá žádné komponenty.',
    'The console has no saved sections.' => 'Konzole nemá žádné uložené sekce.',
    'The console has no shared classes.' => 'Konzole nemá žádné sdílené třídy.',
    'The console refused the pairing: %s' => 'Konzole spárování odmítla: %s',
    'The container ID in the form GTM-XXXXXXX. Consent mode is built in: with the built-in cookie bar the container starts after the visitor allows analytics or marketing.' => 'ID kontejneru ve tvaru GTM-XXXXXXX. Režim souhlasu je vestavěný: s vestavěnou cookie lištou se kontejner spustí, až návštěvník povolí analytické nebo marketingové cookies.',
    'The content import is finished.' => 'Import obsahu je hotový.',
    'The content value from the google-site-verification meta tag.' => 'Hodnota content z meta tagu google-site-verification.',
    'The content value from the msvalidate.01 meta tag.' => 'Hodnota content z meta tagu msvalidate.01.',
    'The copy of the item is hidden – edit it and publish it.' => 'Kopie položky je skrytá – upravte ji a zveřejněte.',
    'The copy of the news item is saved as a draft.' => 'Kopie novinky je uložená jako koncept.',
    'The copy of the page is hidden – edit it and publish it.' => 'Kopie stránky je skrytá – upravte ji a zveřejněte.',
    'The counting is cookie-free: nothing identifies a visitor, bots and signed-in users are left out.' => 'Počítání je bez cookies: nic neidentifikuje návštěvníka, roboti a přihlášení uživatelé se nepočítají.',
    'The country of visitors is not known here – blocking countries works only behind Cloudflare or when the hosting sends the country.' => 'Zemi návštěvníků tu neznáme – blokování zemí funguje jen za Cloudflare, nebo když zemi posílá hosting.',
    'The current password is not correct.' => 'Současné heslo není správné.',
    'The customer gets a personal link for 30 days; what they write arrives as a hidden draft in References, with the consent they gave.' => 'Zákazník dostane osobní odkaz na 30 dní; co napíše, přijde jako skrytý koncept do Referencí i se souhlasem, který dal.',
    'The customer gets the confirmation with the calendar and cancel links.' => 'Zákazník dostane potvrzení s odkazy do kalendáře a ke zrušení.',
    'The customer left no e-mail address – call them, or decline the request.' => 'Zákazník nezanechal e-mail – zavolejte mu, nebo žádost odmítněte.',
    'The data from the device is incomplete.' => 'Data zařízení jsou neúplná.',
    'The database backup contains pages, news, settings and users; uploaded images are in the media backup. Backups are stored in storage/backups/, which is not accessible from the web – download copies off the server too.' => 'Záloha databáze obsahuje stránky, novinky, nastavení a uživatele; nahrané obrázky jsou v záloze médií. Zálohy leží ve složce storage/backups/, která není z webu přístupná – stahujte si je i mimo server.',
    'The database has been restored from the backup (statements: %d). The state before the restore is saved in backup %s.' => 'Databáze byla obnovena ze zálohy (příkazů: %d). Stav před obnovou je uložený v záloze %s.',
    'The database has been updated: %s' => 'Databáze byla aktualizována: %s',
    'The database is back in its state before the restore.' => 'Databáze je zpět ve stavu před obnovou.',
    'The database is behind the code: run "php bin/migrate" on the server.' => 'Databáze je pozadu za kódem: spusťte na serveru "php bin/migrate".',
    'The database is not updated yet - run the migrations and try again.' => 'Databáze ještě není aktualizovaná – spusťte migrace a zkuste to znovu.',
    'The database is ready and the configuration has been written.' => 'Databáze je připravena a konfigurace zapsána.',
    'The database update failed: %s. The site keeps running; install the fix in Settings → Backups, or write to info@taleacms.com.' => 'Aktualizace databáze se nepovedla: %s. Web běží dál; nainstalujte opravu v Nastavení → Zálohy, nebo napište na info@taleacms.com.',
    'The database user name or password is wrong. Check them in your hosting control panel.' => 'Uživatelské jméno nebo heslo k databázi nesedí. Zkontrolujte je v administraci hostingu.',
    'The day of the month must be 1–28, so that every month has it.' => 'Den v měsíci musí být 1–28, aby ho měl každý měsíc.',
    'The day off is removed.' => 'Volno je odebráno.',
    'The day off is saved.' => 'Volno je uloženo.',
    'The defaults every page, news item and collection item starts from. A page’s own title and description always win.' => 'Výchozí hodnoty, od kterých začíná každá stránka, novinka a položka kolekce. Vlastní titulek a popis stránky mají vždy přednost.',
    'The description has %d characters – %d to %d is best.' => 'Popis má %d znaků – nejlepších je %d až %d.',
    'The description has %d characters – search engines cut it after about %d.' => 'Popis má %d znaků – vyhledávače ho zkrátí asi po %d.',
    'The description has %d characters – search results cut it after about 160.' => 'Popis má %d znaků – výsledky hledání ho zkrátí asi po 160.',
    'The description has %d characters.' => 'Popis má %d znaků.',
    'The device did not check who you are. Use a passkey protected by a PIN, fingerprint or face.' => 'Zařízení neověřilo, kdo jste. Použijte přihlašovací klíč chráněný PINem, otiskem prstu nebo obličejem.',
    'The device did not confirm that a user was present.' => 'Zařízení nepotvrdilo přítomnost uživatele.',
    'The device offered an algorithm the system does not support.' => 'Zařízení nabídlo algoritmus, který systém nepodporuje.',
    'The device\'s public key could not be read.' => 'Veřejný klíč zařízení se nepodařilo načíst.',
    'The document is valid until %s – upload the new edition or move the date; the day after, it hides itself and its download address stops working.' => 'Dokument platí do %s – nahrajte nové vydání nebo posuňte datum; den poté se sám skryje a jeho adresa ke stažení přestane fungovat.',
    'The domain %s expires in %d days – renew it with the registrar.' => 'Doména %s vyprší za %d dní – prodlužte ji u registrátora.',
    'The domain %s has expired – renew it with the registrar before someone else takes it.' => 'Doména %s vypršela – prodlužte ji u registrátora, než ji získá někdo jiný.',
    'The domain and mail check has run – the results are below.' => 'Kontrola domény a pošty proběhla – výsledky jsou níže.',
    'The domain and mail check has run – the results are in the table above.' => 'Kontrola domény a pošty proběhla – výsledky jsou v tabulce výše.',
    'The domain as the site is entered in Plausible.' => 'Doména, pod kterou je web zadaný v Plausible.',
    'The domain of the old site does not exist or points to an internal network.' => 'Doména starého webu neexistuje nebo vede do vnitřní sítě.',
    'The draft could not be saved.' => 'Koncept se nepodařilo uložit.',
    'The draft does not exist.' => 'Návrh neexistuje.',
    'The drafts wait for your review in the administration – nothing was published by itself.' => 'Koncepty čekají na vaši kontrolu v administraci – nic se nezveřejnilo samo.',
    'The dropdown opens' => 'Nabídka se otevře',
    'The duration is in minutes, 5 to 480.' => 'Délka je v minutách, 5 až 480.',
    'The e-mail address is not valid.' => 'E-mail nemá platný tvar.',
    'The e-mail address of your account was changed' => 'E-mail vašeho účtu byl změněn',
    'The e-mail goes to the alert address (Settings → System status → Alerts).' => 'E-mail jde na adresu pro upozornění (Nastavení → Stav systému → Upozornění).',
    'The earlier look is in the draft – preview the whole site, then publish it.' => 'Dřívější vzhled je v konceptu – prohlédněte si celý web a pak ho publikujte.',
    'The earlier version of the item is back; the one before it is in the history.' => 'Dřívější verze položky je zpět; ta předchozí zůstala v historii.',
    'The easiest way is to add a custom connector in the Claude app with the address %s – Claude sends you here to sign in and confirm access, no token to copy. The token below is for Claude Code and other tools without sign-in.' => 'Nejjednodušší je přidat v aplikaci Claude vlastní konektor s adresou %s – Claude vás pošle sem přihlásit a potvrdit přístup, žádný token nekopírujete. Token níže je pro Claude Code a jiné nástroje bez přihlášení.',
    'The editor now contains the version from %s. It takes effect once you save the news item.' => 'V editoru je verze z %s. Platit začne, až novinku uložíte.',
    'The element could not be saved.' => 'Prvek se nepodařilo uložit.',
    'The element has no text to rewrite.' => 'Prvek nemá text, který by šel přepsat.',
    'The element is no longer in the published page.' => 'Prvek už není ve zveřejněné stránce.',
    'The element is not in the published page.' => 'Prvek není ve zveřejněné stránce.',
    'The encrypted connection (STARTTLS) could not be established – the server probably has an invalid certificate.' => 'Šifrované spojení (STARTTLS) se nepodařilo navázat – server má nejspíš neplatný certifikát.',
    'The enquiry does not exist.' => 'Poptávka neexistuje.',
    'The enquiry form collects personal data – visitors must know how you handle it. The page is prepared as a hidden draft: fill in the details in square brackets and publish it.' => 'Formulář s poptávkou sbírá osobní údaje – návštěvník musí vědět, jak s nimi naložíte. Kostru stránky máte připravenou jako skrytou: doplňte údaje v hranatých závorkách a stránku zveřejněte.',
    'The enquiry has no e-mail address to send the request to.' => 'Poptávka nemá e-mailovou adresu, kam žádost poslat.',
    'The enquiry is empty – add products with Add to enquiry.' => 'Poptávka je prázdná – přidejte produkty tlačítkem Přidat do poptávky.',
    'The enquiry is open again.' => 'Poptávka je znovu otevřená.',
    'The enquiry is resolved.' => 'Poptávka je vyřízená.',
    'The enquiry was anonymised – the row stays for statistics without the person.' => 'Poptávka byla anonymizována – řádek zůstává pro statistiku bez údajů o osobě.',
    'The enquiry was deleted.' => 'Poptávka byla smazána.',
    'The enquiry was moved to the trash. You can restore it for 30 days.' => 'Poptávka je v koši. Po 30 dní ji můžete obnovit.',
    'The entry file is missing or not a .php file inside the add-on.' => 'Vstupní soubor chybí nebo to není soubor .php uvnitř doplňku.',
    'The error log is empty.' => 'Záznam chyb je prázdný.',
    'The event is on now.' => 'Akce právě probíhá.',
    'The exact registered name, e.g. “Novak Joinery Ltd”. Elsewhere the site uses the site name.' => 'Přesný název podle rejstříku, např. „Truhlářství Novák s.r.o.“. Na webu se jinak používá název webu.',
    'The exception is applied.' => 'Výjimka platí.',
    'The exception is deleted.' => 'Výjimka je smazaná.',
    'The exception is saved.' => 'Výjimka je uložená.',
    'The exception no longer exists.' => 'Výjimka už neexistuje.',
    'The experiment could not be created.' => 'Experiment se nepodařilo vytvořit.',
    'The experiment does not exist.' => 'Experiment neexistuje.',
    'The experiment is already running or finished.' => 'Experiment už běží nebo je dokončen.',
    'The experiment is not running or stopped: nothing to promote.' => 'Experiment neběží ani není zastavený: není co povýšit.',
    'The experiment is running. Visitors now get a random version.' => 'Experiment běží. Návštěvníci teď dostávají náhodnou verzi.',
    'The experiment needs a name.' => 'Experiment potřebuje název.',
    'The experiment was created. Edit version B, then start it.' => 'Experiment byl vytvořen. Upravte verzi B a pak ho spusťte.',
    'The experiment was deleted.' => 'Experiment byl smazán.',
    'The experiment was stopped. Visitors see the original again.' => 'Experiment byl zastaven. Návštěvníci znovu vidí původní verzi.',
    'The export comes from a newer version of Talea – update this site first (pull the newer image).' => 'Export pochází z novější verze Talea – nejdřív aktualizujte tento web (stáhněte novější image).',
    'The export does not carry it. Images are downloaded from this address and the redirects from the old addresses count on it.' => 'Export ji neobsahuje. Z této adresy se stahují obrázky a počítají s ní přesměrování ze starých adres.',
    'The export does not exist.' => 'Export neexistuje.',
    'The export does not say the address of the old site. Enter it below – images are downloaded from it and the old addresses redirect from it.' => 'Export neříká adresu starého webu. Zadejte ji níže – stahují se z ní obrázky a přesměrovávají se z ní staré adresy.',
    'The export has been deleted.' => 'Export byl smazán.',
    'The export has no files – copy the media/ folder from the old site over FTP before or after the import.' => 'Export neobsahuje soubory – složku media/ ze starého webu zkopírujte přes FTP před importem nebo po něm.',
    'The export is ready – download it from the list below.' => 'Export je hotový – stáhněte si ho ze seznamu níže.',
    'The fact %s changed.' => 'Fakt %s se změnil.',
    'The fact does not exist.' => 'Fakt neexistuje.',
    'The fact is deleted – some content still uses it and shows nothing there now; the site audit lists it.' => 'Fakt je smazaný – nějaký obsah ho ještě používá a teď tam nic neukazuje; audit webu ho vypíše.',
    'The fact is deleted.' => 'Fakt je smazaný.',
    'The fact is saved.' => 'Fakt je uložený.',
    'The fact {{fact.%s}} does not exist – visitors see nothing in its place. Create it in Facts, or fix the key.' => 'Fakt {{fact.%s}} neexistuje – návštěvníci na jeho místě nic neuvidí. Vytvořte ho ve Faktech, nebo opravte klíč.',
    'The failed transfers were tried again – see the result in the Service column.' => 'Nepovedené přenosy se zkusily znovu – výsledek vidíte ve sloupci Služba.',
    'The fetch from the site did not finish. Start it again.' => 'Stažení z webu nedoběhlo. Spusťte ho znovu.',
    'The fields and recipients come from the published page. Change them in the builder.' => 'Pole a příjemci pocházejí z publikované stránky. Změníte je v editoru.',
    'The file contains a DOCTYPE or custom entities. A WordPress export never has them – the file was rejected for security reasons.' => 'Soubor obsahuje DOCTYPE nebo vlastní entity. Export z WordPressu nic takového nemá – soubor byl z bezpečnostních důvodů odmítnut.',
    'The file contains a DOCTYPE or custom entities. An export never has them – the file was rejected for security reasons.' => 'Soubor obsahuje DOCTYPE nebo vlastní entity. Export je nikdy nemá – soubor byl z bezpečnostních důvodů odmítnut.',
    'The file contains no blog content (the feed element is missing).' => 'Soubor neobsahuje žádný obsah blogu (chybí prvek feed).',
    'The file contains no site content (the channel element is missing).' => 'V souboru chybí obsah webu (značka channel).',
    'The file contains no usable design tokens (a JSON file in the DTCG format is expected).' => 'Soubor neobsahuje design tokeny, které by šly použít (čekáme JSON ve formátu DTCG).',
    'The file content does not match its extension.' => 'Obsah souboru neodpovídá jeho příponě.',
    'The file could not be moved to the media folder – check the write permissions of media/.' => 'Soubor se nepodařilo přesunout do složky médií – zkontrolujte práva zápisu do media/.',
    'The file could not be opened.' => 'Soubor se nepodařilo otevřít.',
    'The file could not be saved – check write permissions for storage/import.' => 'Soubor se nepodařilo uložit – zkontrolujte práva k zápisu do storage/import.',
    'The file could not be saved.' => 'Soubor se nepodařilo uložit.',
    'The file could not be uploaded.' => 'Soubor se nepodařilo nahrát.',
    'The file could not be uploaded. If it is larger than the server allows, upload it over FTP into the storage/import/ folder.' => 'Soubor se nepodařilo nahrát. Je-li větší, než server dovoluje, nahrajte ho přes FTP do složky storage/import/.',
    'The file could not be uploaded. If it is larger than the server allows, upload it over FTP into the storage/import/sources/ folder.' => 'Soubor se nepodařilo nahrát. Je-li větší, než server dovolí, nahrajte ho přes FTP do složky storage/import/sources/.',
    'The file does not contain the address of the old site, so the images cannot be downloaded.' => 'V souboru chybí adresa starého webu, obrázky proto nejde stáhnout.',
    'The file does not exist.' => 'Soubor neexistuje.',
    'The file has been deleted. The imported content stays on the site.' => 'Soubor byl smazán. Převedený obsah na webu zůstává.',
    'The file has been replaced – the new version is shown everywhere it is used.' => 'Soubor byl nahrazen – všude, kde je použitý, se ukazuje nová verze.',
    'The file is empty or larger than 1 GB. Export a large site from WordPress in parts (by date).' => 'Soubor je prázdný nebo větší než 1 GB. Velký web exportujte z WordPressu po částech (podle data).',
    'The file is empty or larger than 256 MB.' => 'Soubor je prázdný nebo větší než 256 MB.',
    'The file is larger than the server allows (%s at most). Make it smaller or ask your hosting provider to raise the limit.' => 'Soubor je větší, než server dovoluje nahrát (nejvýš %s). Zmenšete ho, nebo požádejte správce hostingu o vyšší limit.',
    'The file is not a JPG, PNG, GIF or WebP image.' => 'Soubor není obrázek JPG, PNG, GIF ani WebP.',
    'The file is not a Talea export (content.json is missing in the archive).' => 'Soubor není export Talea (v archivu chybí content.json).',
    'The file is not a Talea export.' => 'Soubor není export Talea.',
    'The file is not a backup created by Talea.' => 'Soubor není záloha vytvořená systémem Talea.',
    'The file is not a page export.' => 'Soubor není export stránky.',
    'The file is not a valid blueprint: %s' => 'Soubor není platný oborový plán: %s',
    'The file is not valid XML – it is damaged or incomplete. Download the export again. The error is on line:' => 'Soubor není platné XML – je poškozený nebo neúplný. Stáhněte export znovu. Chyba je na řádku:',
    'The file is not valid XML – it is damaged or incomplete. Download the export from WordPress again. The error is on line:' => 'Soubor není platné XML – je poškozený nebo neúplný. Stáhněte export z WordPressu znovu. Chyba je na řádku:',
    'The file is public: %s' => 'Soubor je veřejný: %s',
    'The file is too large (200 MB at most).' => 'Soubor je příliš velký (nejvýše 200 MB).',
    'The file must have the .%s extension.' => 'Soubor musí mít příponu .%s.',
    'The file must have the .xml extension – it is an export from WordPress (Tools → Export).' => 'Soubor musí mít příponu .xml – je to export z WordPressu (Nástroje → Export).',
    'The firewall guards the public site and the Claude connection – never the administration, so you cannot lock yourself out. Addresses of your local network are never blocked.' => 'Firewall chrání veřejný web a napojení Clauda – nikdy administraci, takže se nemůžete zamknout. Adresy vaší místní sítě se neblokují nikdy.',
    'The first data arrives after tonight’s update.' => 'První data dorazí po dnešní noční aktualizaci.',
    'The first page of a visit, its campaign and the site that sent the visitor go with enquiries and newsletter sign-ups (Statistics → Campaigns and pages). Only for visitors who allow marketing in the cookie bar – turning it on adds that choice to the bar.' => 'První stránka návštěvy, její kampaň a web, ze kterého návštěvník přišel, se uloží k poptávkám a přihláškám k odběru (Statistiky → Kampaně a stránky). Jen u návštěvníků, kteří v cookie liště povolí marketing – zapnutím se tato volba do lišty přidá.',
    'The first pages' => 'První stránky',
    'The first part of the news addresses in every language: blog gives /blog/…. Empty = the default address. Lowercase letters, digits and hyphens; not the address of a page, a collection or the system. The old addresses redirect to the new one.' => 'První část adres novinek ve všech jazycích: blog dá /blog/…. Prázdné = výchozí adresa. Malá písmena, číslice a pomlčky; ne adresa stránky, kolekce ani systému. Stará adresa přesměruje na novou.',
    'The first posts' => 'První příspěvky',
    'The five-hundredth finished project.' => 'Pětistá dokončená zakázka.',
    'The focus keyword is at the start of the text.' => 'Klíčové slovo je na začátku textu.',
    'The focus keyword is in a subheading.' => 'Klíčové slovo je v mezititulku.',
    'The focus keyword is in an image description (alt).' => 'Klíčové slovo je v popisu obrázku (alt).',
    'The focus keyword is in no image description (alt).' => 'Klíčové slovo není v žádném popisu obrázku (alt).',
    'The focus keyword is in no subheading.' => 'Klíčové slovo není v žádném mezititulku.',
    'The focus keyword is in the address.' => 'Klíčové slovo je v adrese.',
    'The focus keyword is in the description.' => 'Klíčové slovo je v popisu.',
    'The focus keyword is in the search title.' => 'Klíčové slovo je v titulku pro vyhledávače.',
    'The focus keyword is in the text.' => 'Klíčové slovo je v textu.',
    'The focus keyword is not at the start of the text.' => 'Klíčové slovo není na začátku textu.',
    'The focus keyword is not in the address.' => 'Klíčové slovo není v adrese.',
    'The focus keyword is not in the description.' => 'Klíčové slovo není v popisu.',
    'The focus keyword is not in the search title.' => 'Klíčové slovo není v titulku pro vyhledávače.',
    'The focus keyword is not in the text.' => 'Klíčové slovo není v textu.',
    'The focus keyword “%s” is in the title, the description and the first paragraph.' => 'Klíčové slovo „%s“ je v titulku, popisu i prvním odstavci.',
    'The focus keyword “%s” is missing from %s.' => 'Klíčové slovo „%s“ chybí v: %s.',
    'The focus keywords of this page are too long together. Remove one to add another.' => 'Klíčová slova této stránky jsou dohromady příliš dlouhá. Pro přidání dalšího jedno odeberte.',
    'The folder name must be lowercase letters, digits and _ (it is the add-on\'s slug).' => 'Název složky smí obsahovat jen malá písmena, číslice a _ (je to identifikátor doplňku).',
    'The folder storage is not writable – images cannot be saved.' => 'Do složky storage nelze zapisovat – obrázky nelze uložit.',
    'The folder storage/backups cannot be created - check the write permissions.' => 'Nelze vytvořit složku storage/backups - zkontrolujte práva k zápisu.',
    'The footer menu is empty.' => 'Menu v patičce je prázdné.',
    'The form could not be verified. Reload the page and try again.' => 'Formulář se nepodařilo ověřit. Obnovte stránku a zkuste to znovu.',
    'The form does not exist.' => 'Formulář neexistuje.',
    'The form has expired. Go back, reload the page and submit it again.' => 'Platnost formuláře vypršela. Vraťte se zpět, obnovte stránku a odešlete jej znovu.',
    'The form has expired. Reload the page and try again.' => 'Platnost formuláře vypršela. Obnovte stránku a zkuste to znovu.',
    'The form sent more fields than the server accepts, so nothing was saved. Edit fewer pages at once.' => 'Formulář poslal víc polí, než server přijme, proto se nic neuložilo. Upravujte méně stránek najednou.',
    'The form was sent before we could check that a person is sending it. Please wait a moment and send it again.' => 'Formulář odešel dřív, než jsme stihli ověřit, že ho posílá člověk. Počkejte prosím chvilku a odešlete ho znovu.',
    'The gallery and its images were deleted.' => 'Galerie a její obrázky byly smazány.',
    'The gallery could not be saved.' => 'Galerii se nepodařilo uložit.',
    'The gallery has no name for screen readers.' => 'Galerie nemá název pro čtečky obrazovky.',
    'The gallery has photos without a description for blind visitors (alt).' => 'Galerie má fotky bez popisu pro nevidomé (alt).',
    'The gallery was created. It is closed: nobody can open it until you share it.' => 'Galerie byla vytvořena. Je zavřená: nikdo ji neotevře, dokud ji nesdílíte.',
    'The header and footer appear on every page. Wrappers add sections around content assembled by the system – news items, lists and the 404 message. Until you publish a part from the builder, it has its default design.' => 'Záhlaví a patička jsou na každé stránce webu. Obálky přidají sekce kolem obsahu, který skládá systém – novinky, výpisu a hlášení 404. Dokud část nepublikujete z builderu, má výchozí podobu.',
    'The heading font %s has no %s letters: the %s version shows them in a fallback font of the visitor’s device.' => 'Písmo nadpisů %s nemá %s znaky: verze %s je ukazuje náhradním písmem zařízení návštěvníka.',
    'The heading “%s” skips a level (h%d → h%d).' => 'Nadpis „%s“ přeskakuje úroveň (h%d → h%d).',
    'The headline is over 110 characters – it will be cut off in search results and on social networks.' => 'Titulek má přes 110 znaků – ve výsledcích hledání i na sítích se ořízne.',
    'The hold ran out on %s – the time is free for others, but you can still answer.' => 'Držení termínu vypršelo %s – termín je volný pro ostatní, ale stále můžete odpovědět.',
    'The home page cannot be deleted.' => 'Úvodní stránku nelze smazat.',
    'The home page cannot be deleted. First choose another home page in Settings → General.' => 'Úvodní stránku nejde smazat. Nejdřív v Nastavení → Základní vyberte jinou úvodní stránku.',
    'The home page cannot be hidden. First choose another home page in Settings → General.' => 'Úvodní stránku nejde skrýt. Nejdřív v Nastavení → Základní vyberte jinou úvodní stránku.',
    'The hours were sent and the reviews fetched.' => 'Otevírací doba byla odeslána a recenze načteny.',
    'The image could not be loaded – a description can only be suggested for images uploaded to Media.' => 'Obrázek se nepodařilo načíst – popis jde navrhnout jen k obrázkům nahraným do Médií.',
    'The image could not be saved - check the permissions of the media/ folder.' => 'Obrázek se nepodařilo uložit - zkontrolujte práva ke složce media/.',
    'The image could not be saved.' => 'Obrázek se nepodařilo uložit.',
    'The image has no description for blind visitors (alt).' => 'Obrázek nemá popis pro nevidomé (alt).',
    'The image is damaged and cannot be processed.' => 'Obrázek je poškozený a nelze ho zpracovat.',
    'The image is larger than 15 MB.' => 'Obrázek je větší než 15 MB.',
    'The image is now %s px wide and takes %s.' => 'Obrázek má teď šířku %s px a zabírá %s.',
    'The image is too large (20 MB and 50 megapixels at most).' => 'Obrázek je příliš velký (nejvýše 20 MB a 50 megapixelů).',
    'The image is too large (25 MB and 50 megapixels at most).' => 'Obrázek je příliš velký (nejvýše 25 MB a 50 megapixelů).',
    'The image was removed.' => 'Obrázek byl odebrán.',
    'The import does not exist any more.' => 'Tento import už neexistuje.',
    'The import has stopped:' => 'Import se zastavil:',
    'The import is finished. The pages are hidden until you check and publish them.' => 'Import je hotový. Stránky jsou skryté, dokud je nezkontrolujete a nezveřejníte.',
    'The import replaces all content of this site: pages, news, collections, components, menus, site parts, pop-ups, redirects and the media library, and takes over the site name, company details, languages and the look. User accounts, passwords, keys and the settings of mail and backups stay as they are on this site – the export never contains them. Imported news will be yours.' => 'Import nahradí veškerý obsah tohoto webu: stránky, novinky, kolekce, komponenty, menu, části webu, pop-upy, přesměrování a knihovnu médií, a převezme název webu, údaje o firmě, jazyky a vzhled. Uživatelské účty, hesla, klíče a nastavení pošty a záloh zůstanou tak, jak jsou na tomto webu – export je nikdy neobsahuje. Naimportované novinky budou vaše.',
    'The installation could not be completed – check the highlighted fields.' => 'Instalaci se nepodařilo dokončit – zkontrolujte zvýrazněná pole.',
    'The instance of your Raynet account (X-Instance-Name)' => 'Instance vašeho účtu Raynet (X-Instance-Name)',
    'The instructions changed again in the meantime – check them once more.' => 'Pokyny se mezitím znovu změnily – zkontrolujte je ještě jednou.',
    'The instructions for the AI were changed by %s on %s.' => 'Pokyny pro AI se změnily – %s, %s.',
    'The instructions for the AI were changed by %s through the connection %s on %s.' => 'Pokyny pro AI se změnily – %s přes napojení %s, %s.',
    'The instructions handed out with each run of this schedule (in English for Claude):' => 'Pokyny předávané s každým během tohoto plánu (anglicky, pro Clauda):',
    'The intro is missing – the news list and social sharing need it.' => 'Chybí perex – výpis novinek a sdílení na sítích ho potřebují.',
    'The item does not exist.' => 'Položka neexistuje.',
    'The item is in the trash – it is no longer on the site; you can restore it for 30 days.' => 'Položka je v koši – na webu už není; 30 dní ji můžete obnovit.',
    'The item is in the trash. Bring it back with restore_from_trash first.' => 'Položka je v koši. Nejdřív ji vraťte přes restore_from_trash.',
    'The item is saved, but these fields had an invalid value and were left empty: %s' => 'Položka je uložená, ale tato pole měla neplatnou hodnotu a zůstala prázdná: %s',
    'The item needs a name.' => 'Položka musí mít název.',
    'The item page stays reachable, but it is left out of search engines, the sitemap, llms.txt and site search.' => 'Stránka položky zůstane dostupná, ale vynechá se z vyhledávačů, mapy webu, llms.txt i hledání na webu.',
    'The item still has placeholders in square brackets (%s) – fill them in or delete them.' => 'Položka stále obsahuje zástupné texty v hranatých závorkách (%s) – doplňte je nebo smažte.',
    'The item was deleted permanently.' => 'Položka je smazaná natrvalo.',
    'The item was deleted.' => 'Položka byla smazána.',
    'The item was restored as hidden.' => 'Položka je obnovená jako skrytá.',
    'The item was saved.' => 'Položka byla uložena.',
    'The item “%s” points at a hidden page – visitors do not see it in the menu.' => 'Položka „%s“ vede na skrytou stránku – návštěvníci ji v menu nevidí.',
    'The item “%s” points at a page in the trash.' => 'Položka „%s“ vede na stránku v koši.',
    'The key belongs to a different domain.' => 'Klíč patří k jiné doméně.',
    'The key counter went backwards – the key may have been copied. Remove it and register it again.' => 'Počitadlo klíče se vrátilo zpět - klíč mohl být zkopírován. Odeberte ho a zaregistrujte znovu.',
    'The key identifier has an invalid length.' => 'Identifikátor klíče má neplatnou délku.',
    'The key may contain lowercase letters, digits and _ (2–40 characters).' => 'Klíč může obsahovat malá písmena, číslice a _ (2–40 znaků).',
    'The key may contain lowercase letters, digits and _ and must start with a letter (2–40 characters).' => 'Klíč smí obsahovat malá písmena, číslice a _ a musí začínat písmenem (2–40 znaků).',
    'The kinds other than an exact address are checked only when nothing exists at the address, so they cannot hide a live page.' => 'Ostatní druhy než přesná adresa se zkoušejí jen tehdy, když na adrese nic neexistuje, takže nemohou zakrýt existující stránku.',
    'The kit carries the design of this console – its design system, shared classes, components and saved sections – to the sites that chose to receive it (Settings → Fleet console on the site). A site gets each version as drafts only: the look draft, component drafts and its section library. Its people review and publish; nothing goes live by itself. Custom code never travels in a kit.' => 'Sada přenáší design této konzole – její design systém, sdílené třídy, komponenty a uložené sekce – na weby, které se rozhodly ji přijímat (na webu Nastavení → Konzole webů). Web dostane každou verzi jen jako koncepty: koncept vzhledu, koncepty komponent a svou knihovnu sekcí. Jeho lidé je zkontrolují a vydají; nic se nezveřejní samo. Vlastní kód v sadě nikdy necestuje.',
    'The kit does not match the hash the console announced – refused.' => 'Sada neodpovídá otisku, který konzole ohlásila – odmítnuta.',
    'The kit is not readable – refused.' => 'Sada není čitelná – odmítnuta.',
    'The kit is not signed by the console – refused.' => 'Sada není podepsaná konzolí – odmítnuta.',
    'The kit is too large (%s) – choose fewer components or sections.' => 'Sada je příliš velká (%s) – vyberte méně komponent nebo sekcí.',
    'The kit is too large – refused.' => 'Sada je příliš velká – odmítnuta.',
    'The language of the footer texts and of the latest news items.' => 'Jazyk textů v patičce a nejnovějších novinek.',
    'The last 50; the log keeps 30 days.' => 'Posledních 50; záznam se drží 30 dní.',
    'The last attempt %s failed: %s' => 'Poslední pokus %s selhal: %s',
    'The last copy was uploaded %s.' => 'Poslední kopie byla nahrána %s.',
    'The last database backup is from %s.' => 'Poslední záloha databáze je z %s.',
    'The last kit was refused: %s' => 'Poslední sada byla odmítnuta: %s',
    'The last three exports are kept. To restore this site, use the database backup in Settings → Backups.' => 'Uchovávají se poslední tři exporty. Pro obnovu tohoto webu slouží záloha databáze v Nastavení → Zálohy.',
    'The link %s does not work (%s).' => 'Odkaz %s nefunguje (%s).',
    'The link %s leads to a page that does not exist.' => 'Odkaz %s vede na stránku, která neexistuje.',
    'The link could not be created.' => 'Odkaz se nepodařilo vytvořit.',
    'The link has expired or has already been used. Request a new one.' => 'Odkaz už neplatí nebo byl použit. Požádejte o nový.',
    'The link is invalid or has already been used. If you want to receive news, please subscribe again.' => 'Odkaz je neplatný nebo už byl použitý. Pokud chcete novinky odebírat, přihlaste se prosím znovu.',
    'The link is no longer valid' => 'Odkaz už neplatí',
    'The link to send yourself: %s' => 'Odkaz k odeslání: %s',
    'The link “%s” does not say where it leads – screen readers read links on their own.' => 'Odkaz „%s“ neříká, kam vede – čtečky obrazovky čtou odkazy samostatně.',
    'The list comes straight from %s with your key, newest first – new models appear here without an update of Talea. Loaded %s.' => 'Seznam přichází přímo od %s s vaším klíčem, nejnovější první – nové modely se tu objeví bez aktualizace Talea. Načteno %s.',
    'The list of news and a newsletter sign-up below it.' => 'Výpis novinek a pod ním přihlášení k odběru.',
    'The locations could not be loaded: %s' => 'Pobočky se nepodařilo načíst: %s',
    'The log is kept for six months.' => 'Protokol se uchovává půl roku.',
    'The logo in the middle with the menu below it – for a site led by the brand.' => 'Logo uprostřed a pod ním menu – pro web, který stojí na značce.',
    'The logo on the left, the menu and a button on the right. Stays at the top while scrolling.' => 'Logo vlevo, menu a tlačítko vpravo. Při posouvání zůstává nahoře.',
    'The look does not exist.' => 'Vzhled neexistuje.',
    'The look draft and the component drafts are waiting for your review:' => 'Koncept vzhledu a koncepty komponent čekají na vaši kontrolu:',
    'The look goes to the draft look; nothing is published until you do it.' => 'Vzhled se uloží do konceptu vzhledu; nic se nezveřejní, dokud to neuděláte.',
    'The look is in the draft – preview the whole site, then publish it.' => 'Vzhled je v konceptu – prohlédněte si celý web a pak ho zveřejněte.',
    'The look is published: %s' => 'Vzhled je publikovaný: %s',
    'The look version does not exist.' => 'Tato verze vzhledu neexistuje.',
    'The look was published: %s' => 'Vzhled byl zveřejněn: %s',
    'The mail DNS records (SPF, DMARC, DKIM), the site certificate and the domain registration have not been checked yet. The check runs once a day on its own.' => 'DNS záznamy pošty (SPF, DMARC, DKIM), certifikát webu a registrace domény zatím nebyly zkontrolovány. Kontrola běží jednou denně sama.',
    'The mail DNS records (SPF, DMARC, DKIM), the site certificate and the domain registration have not been checked yet. The check runs once a day on its own; the results appear in the table above.' => 'DNS záznamy pošty (SPF, DMARC, DKIM), certifikát webu a registrace domény zatím nebyly zkontrolovány. Kontrola běží jednou denně sama; výsledky se objeví v tabulce výše.',
    'The mail() function is disabled on the server – set up sending via SMTP.' => 'Funkce mail() je na serveru vypnutá – nastavte odesílání přes SMTP.',
    'The mail() function. Nothing to set up, but with some hosts messages end up in spam.' => 'Funkce mail(). Nic se nenastavuje; u některých hostingů ale zprávy padají do spamu.',
    'The measurement ID in the form G-XXXXXXXXXX is enough. It runs only after the visitor\'s consent (the Privacy and cookies tab).' => 'Stačí ID měření ve tvaru G-XXXXXXXXXX. Spouští se až po souhlasu návštěvníka (záložka Soukromí a cookies).',
    'The measurement ID in the form G-XXXXXXXXXX is enough. With a cookie bar on, it runs only after the visitor\'s consent (the Privacy and cookies tab).' => 'Stačí ID měření ve tvaru G-XXXXXXXXXX. Se zapnutou cookie lištou se spouští až po souhlasu návštěvníka (záložka Soukromí a cookies).',
    'The media are too large to pack in one go. Turn on the off-site copy (it copies the media bit by bit) or download the media/ folder over FTP.' => 'Média jsou příliš velká na zabalení najednou. Zapněte kopie mimo server (média kopírují postupně), nebo složku media/ stáhněte přes FTP.',
    'The media exceed 1 GB, so the export contains data only (JSON). Download the media/ folder over FTP.' => 'Média mají přes 1 GB, export proto obsahuje jen data (JSON). Složku media/ si stáhněte přes FTP.',
    'The member could not be saved.' => 'Člena se nepodařilo uložit.',
    'The member does not exist.' => 'Člen neexistuje.',
    'The member has been removed and signed out everywhere.' => 'Člen byl odebrán a všude odhlášen.',
    'The menu could not be saved – please try again.' => 'Menu se nepodařilo uložit – zkuste to prosím znovu.',
    'The menu has been saved.' => 'Menu bylo uloženo.',
    'The menu is again built automatically from pages in the navigation.' => 'Menu se zase skládá samo ze stránek zařazených do navigace.',
    'The menu is currently built automatically from pages ticked “in navigation”. Once you edit and save it here, this version applies.' => 'Menu se zatím skládá samo ze stránek zaškrtnutých „v navigaci“. Když ho tady upravíte a uložíte, bude platit tahle podoba.',
    'The menu is empty – add the first item.' => 'Menu je prázdné – přidejte první položku.',
    'The menu is saved to the draft look – preview the whole site, then publish it.' => 'Menu je uložené v konceptu vzhledu – prohlédněte si celý web a pak ho publikujte.',
    'The message could not be sent. Please try again.' => 'Zprávu se nepodařilo odeslat. Zkuste to prosím znovu.',
    'The message has been handed over for delivery to %s. If it does not arrive, check your spam folder – or set up sending via SMTP (Settings → Mail).' => 'Zpráva byla předána k odeslání na %s. Pokud nedorazí, zkontrolujte spam – nebo nastavte odesílání přes SMTP (Nastavení → Pošta).',
    'The message has been handed over for delivery to %s. If it does not arrive, check your spam folder.' => 'Zpráva byla předána k odeslání na %s. Pokud nedorazí, zkontrolujte spam.',
    'The message with a search box below it.' => 'Hláška a pod ní vyhledávací pole.',
    'The monthly report by e-mail went out (the month and how many recipients).' => 'Odešla měsíční zpráva e-mailem (měsíc a počet příjemců).',
    'The monthly report for %s went to %d recipient(s).' => 'Měsíční zpráva za %s odešla %d příjemci (příjemcům).',
    'The monthly report – its e-mail, the recipients and the archive to print or download – is under Settings → Reports.' => 'Měsíční zpráva – její e-mail, příjemci a archiv k tisku nebo stažení – je v Nastavení → Zprávy.',
    'The new name must be unused and written in lowercase without accents (e.g. card-large).' => 'Nový název musí být volný a psaný malými písmeny bez diakritiky (např. karta-velka).',
    'The new page has less than half of the old page’s images.' => 'Nová stránka má méně než polovinu obrázků staré stránky.',
    'The new password link has been sent to %s.' => 'Odkaz na nové heslo odešel na %s.',
    'The new password must be at least 10 characters long.' => 'Nové heslo musí mít alespoň 10 znaků.',
    'The new passwords do not match.' => 'Nová hesla se neshodují.',
    'The new photo appears everywhere the old one is used – the file address does not change.' => 'Nová fotka se ukáže všude, kde je stará použitá – adresa souboru se nezmění.',
    'The newest reviews from your Google Business Profile with the rating – they update themselves daily.' => 'Nejnovější recenze z vašeho firemního profilu Google s hodnocením – aktualizují se samy každý den.',
    'The news item and a call to action below it.' => 'Novinka a pod ní výzva k akci.',
    'The news item does not exist or you do not have access to it.' => 'Novinka neexistuje nebo k ní nemáte přístup.',
    'The news item will be checked again within a few minutes.' => 'Novinka se zkontroluje znovu během několika minut.',
    'The news items move to the selected tag. Talea then deletes this tag and redirects its address. Use it for typos and duplicate spellings.' => 'Novinky přejdou pod vybraný štítek. Talea pak tento štítek smaže a jeho adresu přesměruje. Hodí se na překlepy a dvojí psaní.',
    'The newsletter does not exist.' => 'Newsletter neexistuje.',
    'The newsletter has already been sent.' => 'Newsletter už byl odeslán.',
    'The newsletter has no news items to send – publish a news item or choose No news.' => 'Newsletter nemá žádné novinky k odeslání – vydejte novinku, nebo zvolte Bez novinek.',
    'The newsletter is being sent right now – it cannot be deleted until it finishes.' => 'Newsletter se právě odesílá – smazat ho půjde, až odesílání skončí.',
    'The newsletter is scheduled for %s.' => 'Newsletter je naplánovaný na %s.',
    'The newsletter needs a subject.' => 'Newsletter potřebuje předmět.',
    'The newsletter was deleted.' => 'Newsletter je smazaný.',
    'The newsletter was saved.' => 'Newsletter je uložený.',
    'The note does not exist.' => 'Poznámka neexistuje.',
    'The note has been saved.' => 'Poznámka byla uložena.',
    'The note is deleted.' => 'Poznámka je smazaná.',
    'The note is saved.' => 'Poznámka je uložená.',
    'The notice board has %s notices – they stay in the archive, so the collection cannot be deleted.' => 'Úřední deska má %s oznámení – zůstávají v archivu, kolekci proto nelze smazat.',
    'The number %s is typed in – make it a fact ({{fact.key}}) or a count, so it stays true.' => 'Číslo %s je napsané ručně – udělejte z něj fakt ({{fact.klic}}) nebo počet, aby zůstalo pravdivé.',
    'The number of published news items.' => 'Počet vydaných novinek.',
    'The number of visible items of a collection (by its address).' => 'Počet zobrazených položek kolekce (podle její adresy).',
    'The off-site copy of the backup failed: %s' => 'Kopie zálohy mimo server selhala: %s',
    'The official notice board preset for municipalities and other offices: notices with posting and takedown dates, a permanent archive and an append-only audit trail (the list_notice_log tool). Applying the Municipality blueprint turns it on. Switching it off hides it but never deletes notices or their log.' => 'Předvolba úřední desky pro obce a další úřady: oznámení s daty vyvěšení a sejmutí, trvalý archiv a protokol změn, do kterého se jen přidává (nástroj list_notice_log). Zapne se použitím vzoru Obec. Po vypnutí se skryje, ale oznámení ani jejich protokol se nikdy nesmažou.',
    'The old page could not be read, so only the address was checked.' => 'Starou stránku nešlo načíst, zkontrolovala se jen adresa.',
    'The old page had a form, the new one has none.' => 'Stará stránka měla formulář, nová žádný nemá.',
    'The old page had a search engine description, the new one has none.' => 'Stará stránka měla popis pro vyhledávače, nová ho nemá.',
    'The old site did not return the image, it responded with error' => 'Starý web obrázek nevydal, odpověděl chybou',
    'The old site is not responding.' => 'Starý web neodpovídá.',
    'The old site responds too slowly.' => 'Starý web odpovídá příliš pomalu.',
    'The old value “%s” is still written as plain text in %d places – replace it with the token so it changes by itself next time:' => 'Stará hodnota „%s“ je ještě napsaná jako prostý text na %d místech – nahraďte ji značkou, ať se příště změní sama:',
    'The older version is in the draft – publish it when ready' => 'Starší verze je v konceptu – publikujte ji, až bude hotová',
    'The opening hours from Business details and their exceptions go to the chosen location whenever they change and once a day; the newest reviews and the rating come back for the Google reviews element and the facts {{fact.google_rating}} and {{fact.google_reviews}}.' => 'Otevírací doba z Údaje o firmě a její výjimky se posílají do vybrané pobočky při každé změně a jednou denně; zpět přicházejí nejnovější recenze a hodnocení pro prvek Recenze Google a fakta {{fact.google_rating}} a {{fact.google_reviews}}.',
    'The opening text of the e-mail; the details follow. Write it in your own tone and form of address; {name} is the customer\'s name.' => 'Úvodní text e-mailu, následují podrobnosti. Napište ho vlastním tónem a oslovením; {name} je jméno zákazníka.',
    'The opening text; your personal message from the request follows it.' => 'Úvodní text; po něm následuje vaše osobní zpráva.',
    'The original (A) is better with a probability of %s. Keep it.' => 'Původní verze (A) je lepší s pravděpodobností %s. Nechte ji.',
    'The original changed after this translation was saved.' => 'Originál se změnil po uložení tohoto překladu.',
    'The original holds' => 'Původní verze vede',
    'The original stays. The experiment is over.' => 'Původní verze zůstává. Experiment skončil.',
    'The original was kept.' => 'Původní verze zůstala.',
    'The other form redirects with 301 and the canonical URL always uses the chosen one. Does not apply to the home page, files such as sitemap.xml, or the API.' => 'Druhý tvar přesměruje kódem 301 a kanonická adresa vždy používá zvolený. Netýká se úvodní stránky, souborů jako sitemap.xml ani API.',
    'The other times were sent to the customer.' => 'Jiné termíny byly odeslány zákazníkovi.',
    'The page as visitors will see it' => 'Stránka, jak ji uvidí návštěvník',
    'The page content goes here (news item, news list, 404 message).' => 'Sem se vloží obsah stránky (novinka, výpis novinek, hlášení 404).',
    'The page could not be downloaded.' => 'Stránku se nepodařilo stáhnout.',
    'The page does not exist.' => 'Stránka neexistuje.',
    'The page has %d H1 headings – only the main one should be an H1, the others H2.' => 'Stránka má %d nadpisů H1 – H1 má být jen hlavní nadpis, ostatní H2.',
    'The page has an image or a video.' => 'Stránka obsahuje obrázek nebo video.',
    'The page has an outline.' => 'Stránka má obsah.',
    'The page has been created with a privacy policy outline – fill in the details in square brackets.' => 'Stránka je založená s kostrou zásad – doplňte údaje v hranatých závorkách.',
    'The page has been imported as hidden – check it and publish it.' => 'Stránka je importovaná jako skrytá – zkontrolujte ji a zveřejněte.',
    'The page has been permanently deleted.' => 'Stránka byla smazána natrvalo.',
    'The page has been restored as hidden – publish it in its settings.' => 'Stránka je obnovená jako skrytá – zveřejníte ji v jejím nastavení.',
    'The page has more than one main heading (h1) – keep just one.' => 'Stránka má víc hlavních nadpisů (h1) – nechte jen jeden.',
    'The page has no H1 heading – the main heading tells readers and search engines what the page is about.' => 'Stránka nemá nadpis H1 – hlavní nadpis říká čtenářům i vyhledávačům, o čem stránka je.',
    'The page has no content to import.' => 'Stránka nemá obsah k importu.',
    'The page has no image or video.' => 'Stránka neobsahuje obrázek ani video.',
    'The page has no main heading (h1) – search engines and screen readers use it to tell what the page is about.' => 'Stránka nemá hlavní nadpis (h1) – vyhledávače i čtečky podle něj poznají, o čem je.',
    'The page has no outline.' => 'Stránka nemá obsah.',
    'The page has no title.' => 'Stránka nemá titulek.',
    'The page is checked against this keyword.' => 'Stránka se kontroluje podle tohoto klíčového slova.',
    'The page is empty. Add a section from the Add panel.' => 'Stránka je prázdná. Přidejte sekci z panelu Přidat.',
    'The page is here but not published yet.' => 'Stránka tu je, ale ještě není zveřejněná.',
    'The page is in the trash. You can restore it for %d days.' => 'Stránka je v koši. Obnovit ji můžete %d dní.',
    'The page no longer exists.' => 'Stránka už neexistuje.',
    'The page password must have at least %d characters.' => 'Heslo stránky musí mít aspoň %d znaků.',
    'The page shown at the site address. News is always at %s.' => 'Stránka, která se ukáže na adrese webu. Novinky jsou vždy na %s.',
    'The page shows the text from the editor (the build\'s content without the layout). You will find the build in versions when you open the builder.' => 'Stránka zobrazuje text z editoru (obsah stavby bez rozložení). Stavbu najdete ve verzích, když otevřete builder.',
    'The page text still has placeholders in square brackets (%s) – fill them in or delete them.' => 'Text stránky stále obsahuje zástupné texty v hranatých závorkách (%s) – doplňte je nebo smažte.',
    'The page visitors see now (version A). It has to be published and made in the builder.' => 'Stránka, kterou návštěvníci vidí teď (verze A). Musí být zveřejněná a vytvořená v editoru.',
    'The page you are looking for is not here. It may have a different address.' => 'Požadovaná stránka na webu není. Možná má jinou adresu.',
    'The pages are hidden. Replace the texts in square brackets, then publish each page in the builder.' => 'Stránky jsou skryté. Nahraďte texty v hranatých závorkách a pak každou stránku zveřejněte v editoru.',
    'The paragraphs are short.' => 'Odstavce jsou krátké.',
    'The part of the address after %s.' => 'Část adresy za %s.',
    'The part of the address after %s. If you change it after publishing, the old address redirects automatically.' => 'Část adresy za %s. Když ji po vydání změníte, stará adresa se sama přesměruje.',
    'The passkey has been added. Next time you can sign in with it alone, or use it instead of the code from the app.' => 'Přihlašovací klíč byl přidán. Příště se můžete přihlásit jen jím, nebo ho použít místo kódu z aplikace.',
    'The passkey has been removed.' => 'Přihlašovací klíč je odebrán.',
    'The password has been changed and other sign-ins of this account have been ended.' => 'Heslo bylo změněno a ostatní přihlášení tohoto účtu ukončena.',
    'The password has been changed, other sign-ins ended and connection tokens revoked.' => 'Heslo bylo změněno, ostatní přihlášení ukončena a tokeny napojení zrušeny.',
    'The password has been changed. Sign in with the new password.' => 'Heslo je změněno. Přihlaste se novým heslem.',
    'The password must be at least 10 characters long.' => 'Heslo musí mít alespoň 10 znaků.',
    'The passwords do not match.' => 'Hesla se neshodují.',
    'The path to the page (Home › News › …) – built automatically for the page shown.' => 'Cesta ke stránce (Úvod › Novinky › …) – sestaví se sama podle zobrazené stránky.',
    'The pattern matches every address.' => 'Vzor odpovídá každé adrese.',
    'The person does not exist.' => 'Člověk neexistuje.',
    'The person gets an e-mail with a link that signs them in; it works once for a few days.' => 'Člověk dostane e-mail s odkazem, který ho přihlásí; funguje jednou a několik dní.',
    'The person has upcoming bookings – cancel or move them first, or switch the person off instead.' => 'Člověk má nadcházející rezervace – nejdřív je zrušte nebo přesuňte, nebo ho místo toho vypněte.',
    'The person is removed.' => 'Člověk je odebrán.',
    'The person is saved.' => 'Člověk je uložen.',
    'The photo and the logo load from your website, so they show as long as they stay there.' => 'Fotka a logo se načítají z vašeho webu, takže se zobrazují, dokud tam zůstanou.',
    'The photos of each item’s gallery appear here.' => 'Tady se zobrazí fotky z galerie každé položky.',
    'The pop-up counters were reset.' => 'Počitadla okna jsou vynulovaná.',
    'The pop-up does not exist.' => 'Pop-up okno neexistuje.',
    'The pop-up is created turned off and opens in the builder. It shows on the site once you publish it and turn it on.' => 'Okno se založí vypnuté a otevře se v builderu. Na webu se ukáže, až ho publikujete a zapnete.',
    'The pop-up is off – it no longer shows on the site.' => 'Okno je vypnuté – na webu se už neukáže.',
    'The pop-up is on and shows on the site according to its rules.' => 'Okno je zapnuté a ukáže se na webu podle pravidel.',
    'The pop-up needs a name.' => 'Okno musí mít název.',
    'The pop-up settings were saved.' => 'Nastavení okna bylo uloženo.',
    'The pop-up was deleted.' => 'Pop-up okno bylo smazáno.',
    'The post draft is saved.' => 'Návrh příspěvku je uložený.',
    'The post is too long (at most 3000 characters).' => 'Příspěvek je příliš dlouhý (nejvýš 3000 znaků).',
    'The post needs a text.' => 'Příspěvek potřebuje text.',
    'The presets your collections come from, your facts without their values, and the questions, checks and instructions of the applied blueprints.' => 'Hotové kolekce, ze kterých vaše kolekce vznikly, vaše fakty bez hodnot a otázky, kontroly a pokyny použitých plánů.',
    'The preview shows unsaved changes.' => 'Náhled ukazuje neuložené změny.',
    'The previous version is not kept.' => 'Předchozí verze není uložena.',
    'The primary tag of a post is offered as its category, the other tags as tags; internal tags (#name) are skipped.' => 'Hlavní štítek příspěvku se nabízí jako rubrika, ostatní štítky jako štítky; interní štítky (#název) se vynechávají.',
    'The privacy policy template and the record of processing name %s.' => 'Šablona zásad ochrany soukromí a záznam o zpracování uvádějí %s.',
    'The promotion was undone. The page is as it was before.' => 'Povýšení bylo vráceno. Stránka je jako dřív.',
    'The properties could not be loaded: %s' => 'Vlastnosti se nepodařilo načíst: %s',
    'The proposal is discarded.' => 'Návrh je zahozený.',
    'The proposal no longer exists.' => 'Návrh už neexistuje.',
    'The public key does not match the data from the device.' => 'Veřejný klíč neodpovídá datům zařízení.',
    'The receiver did not respond.' => 'Příjemce neodpověděl.',
    'The recipient address is not valid.' => 'Adresa příjemce nemá platný tvar.',
    'The redirect does not exist.' => 'Přesměrování neexistuje.',
    'The redirect of hidden items must be an address on the site (/team) or https://…' => 'Přesměrování skrytých položek musí být adresa na webu (/tym) nebo https://…',
    'The redirects will be saved but only take effect once you turn on the Redirects feature.' => 'Přesměrování se zapíší, ale začnou platit, až zapnete funkci Přesměrování.',
    'The region where the sending domain is verified in Amazon SES – the SMTP credentials work only there.' => 'Oblast, kde je odesílací doména ověřena v Amazon SES – přihlašovací údaje SMTP fungují jen tam.',
    'The regular expression is not valid.' => 'Regulární výraz není platný.',
    'The reply is added – Claude reads it with the request.' => 'Odpověď je přidaná – Claude si ji přečte s požadavkem.',
    'The report does not exist any more.' => 'Kontrola už neexistuje.',
    'The report for %s has been handed over for delivery to %d recipient(s).' => 'Zpráva za období %s byla předána k doručení %d příjemcům.',
    'The report has been handed over for delivery to %d recipient(s).' => 'Zpráva byla předána k doručení %d příjemci (příjemcům).',
    'The report has been sent to the console.' => 'Hlášení je odeslané konzoli.',
    'The request does not exist.' => 'Požadavek neexistuje.',
    'The request is declined and the customer was told by e-mail.' => 'Žádost je odmítnuta a zákazník se to dozvěděl e-mailem.',
    'The request is saved – it waits until Claude is connected to the site; you will read its notes here.' => 'Požadavek je uložený – počká, dokud nebude Claude k webu připojený; jeho poznámky si přečtete tady.',
    'The request is saved – it waits: the scheduled run that picks up requests has stopped. You will read Claude’s notes here.' => 'Požadavek je uložený – čeká: plánovaný běh, který požadavky vyřizuje, se zastavil. Poznámky Clauda si přečtete tady.',
    'The request is saved. Claude picks it up the next time someone asks it; you will read its notes here.' => 'Požadavek je uložený. Claude ho vyřídí, až ho o to někdo příště požádá; jeho poznámky si přečtete tady.',
    'The request is saved. Claude will see it the next time it works on the site; you will read its notes here.' => 'Požadavek je uložený. Claude ho uvidí, až bude příště pracovat na webu; jeho poznámky si přečtete tady.',
    'The request to connect the application has expired or does not exist. Start connecting again in the application.' => 'Žádost o připojení aplikace vypršela nebo neexistuje. Spusťte připojení v aplikaci znovu.',
    'The request was sent. The link: %s' => 'Žádost je odeslaná. Odkaz: %s',
    'The response does not belong to this attempt. Please try again.' => 'Odpověď nepatří k tomuto pokusu. Zkuste to znovu.',
    'The response does not contain a new key.' => 'Odpověď neobsahuje nový klíč.',
    'The response from the device has an unexpected type.' => 'Odpověď zařízení má nečekaný typ.',
    'The response was created at a different address than the site address in Settings.' => 'Odpověď vznikla na jiné adrese, než je adresa webu v Nastavení.',
    'The response was created in an embedded frame of another site.' => 'Odpověď vznikla ve vloženém okně cizí stránky.',
    'The results are also in System status.' => 'Výsledky jsou také ve Stavu systému.',
    'The reviews could not be fetched: %s' => 'Recenze se nepodařilo načíst: %s',
    'The role does not exist.' => 'Role neexistuje.',
    'The role has been deleted. Its members kept their current access.' => 'Role byla smazána. Její členové si ponechali dosavadní přístup.',
    'The role has been saved.' => 'Role byla uložena.',
    'The routine asks the site what is due, does each run as drafts and reports it; the summary and the links to the drafts appear in the history here. You review and publish. A run nobody picks up within 6 hours is marked missed and reported in the events and the alert e-mails.' => 'Rutina se webu zeptá, co je na řadě, každý běh udělá jako koncepty a ohlásí ho; shrnutí a odkazy na koncepty se objeví zde v historii. Vy zkontrolujete a publikujete. Běh, který si do 6 hodin nikdo nevyzvedne, je označen jako zmeškaný a objeví se v událostech a v upozorněních e-mailem.',
    'The rule does not match this address.' => 'Pravidlo této adrese neodpovídá.',
    'The rule is in use' => 'Pravidlo se používá',
    'The rule matches: %d to' => 'Pravidlo odpovídá: %d na',
    'The rule matches: the answer is %d with no target.' => 'Pravidlo odpovídá: odpověď je %d bez cíle.',
    'The same address in every language cannot be switched off while two language versions share an address: %s. Change one of each pair first.' => 'Stejnou adresu ve všech jazycích nelze vypnout, dokud si dvě jazykové verze dělí adresu: %s. Nejdřív změňte jednu z každé dvojice.',
    'The same address in every language version' => 'Stejná adresa ve všech jazykových verzích',
    'The same file uploaded more than once. Keep the one the site uses; an unused copy can be ticked and deleted below.' => 'Stejný soubor nahraný víckrát. Nechte ten, který web používá; nepoužitou kopii zaškrtněte a dole smažte.',
    'The same for the whole site; a page shows it on its Sharing tab.' => 'Stejná pro celý web; stránka ji ukazuje na kartě Sdílení.',
    'The same from a fact whose value is a year or a date.' => 'Totéž z faktu, jehož hodnotou je rok nebo datum.',
    'The sample pages and the texts for visitors are created in this language. The administration stays in the language of the installation.' => 'V tomto jazyce vzniknou ukázkové stránky a texty pro návštěvníky. Administrace zůstane v jazyce instalace.',
    'The scan could not reach the site from the server (%s). The table shows what Talea and the known embeds set.' => 'Sken se ze serveru k webu nedostal (%s). Tabulka ukazuje, co nastavuje Talea a známá vložení.',
    'The schedule and its history are deleted.' => 'Plán i historie jeho běhů jsou smazány.',
    'The schedule does not exist.' => 'Plán neexistuje.',
    'The schedule is active again.' => 'Plán je opět aktivní.',
    'The schedule is paused – no runs are handed out until you resume it.' => 'Plán je pozastaven – dokud ho neobnovíte, žádné běhy se nepředávají.',
    'The schedule is saved. The site hands the run to the routine in Claude when its time comes – set the routine up below if you have not yet.' => 'Plán je uložen. Až přijde jeho čas, web předá běh rutině v Claudovi – pokud ji ještě nemáte, nastavte ji níže.',
    'The scheduled Claude run “%s” was not picked up – check the routine in Claude (Scheduled runs).' => 'Naplánovaný běh Clauda „%s“ si nikdo nevyzvedl – zkontrolujte rutinu v Claudovi (Naplánované běhy).',
    'The scheduled run that picks up requests has stopped (last missed or failed %s) – requests wait until it runs again or someone asks Claude.' => 'Plánovaný běh, který vyřizuje požadavky, se zastavil (naposledy zmeškán nebo selhal %s) – požadavky čekají, dokud znovu neproběhne nebo někdo nepožádá Clauda.',
    'The scheduled run that picks up requests has stopped – check the routine in the Claude app.' => 'Plánovaný běh, který vyřizuje požadavky, se zastavil – zkontrolujte rutinu v aplikaci Claude.',
    'The script from your provider (for Cookiebot, the line with data-cbid). It loads first.' => 'Skript od poskytovatele (u Cookiebotu řádek s data-cbid). Načte se jako první.',
    'The search title does not start with the focus keyword.' => 'Titulek pro vyhledávače nezačíná klíčovým slovem.',
    'The search title starts with the focus keyword.' => 'Titulek pro vyhledávače začíná klíčovým slovem.',
    'The section appears in the Add panel → My sections. Each insert is a separate copy; if it should be the same everywhere, save it as a component.' => 'Sekce se objeví v panelu Přidat → Moje sekce. Každé vložení je samostatná kopie; když má být všude stejná, uložte ji jako komponentu.',
    'The section is back to the defaults.' => 'Sekce je zpět na výchozích hodnotách.',
    'The section is in the Add panel → My sections.' => 'Sekce je v panelu Přidat → Moje sekce.',
    'The section is not in the library.' => 'Sekce v knihovně není.',
    'The section needs a name.' => 'Sekce potřebuje název.',
    'The sending domain %s has no DMARC record – Gmail and Microsoft require it. Add a TXT record on %s: %s' => 'Odesílací doména %s nemá záznam DMARC – Gmail a Microsoft ho vyžadují. Přidejte TXT záznam na %s: %s',
    'The sending domain %s has no SPF record – mail from the forms will land in spam. Add a TXT record: %s' => 'Odesílací doména %s nemá záznam SPF – pošta z formulářů skončí ve spamu. Přidejte TXT záznam: %s',
    'The server allows uploads of at most %s. Copy a larger file over FTP into the storage/import/ folder – it will appear in the list below.' => 'Server dovolí nahrát nejvýš %s. Větší soubor zkopírujte přes FTP do složky storage/import/ – objeví se v seznamu níže.',
    'The server allows uploads of at most %s. Copy a larger file over FTP into the storage/import/sources/ folder, named system-name.extension (for example ghost-blog.json) – it will appear in the list below.' => 'Server dovolí nahrát nejvýš %s. Větší soubor zkopírujte přes FTP do složky storage/import/sources/ pojmenovaný systém-název.přípona (například ghost-blog.json) – objeví se v seznamu níže.',
    'The server cannot read compressed backups (zlib is missing).' => 'Server neumí číst komprimované zálohy (chybí zlib).',
    'The server cannot use encrypted FTP (FTPS). Send backups to S3 storage, or download them manually.' => 'Server neumí šifrované FTP (FTPS). Zálohu posílejte do úložiště S3, nebo si ji stahujte ručně.',
    'The server could not reach the site: %s.' => 'Server se k webu nedostal: %s.',
    'The server does not meet the requirements. Fix the items marked with a cross and reload the page.' => 'Server nesplňuje požadavky. Opravte položky označené křížkem a obnovte stránku.',
    'The server holds an unsaved draft from ' => 'Na serveru je neuložená rozepsaná verze z ',
    'The server refused to send the message (the mail() function failed).' => 'Server zprávu odmítl odeslat (funkce mail() selhala).',
    'The server returned an unexpected response.' => 'Server vrátil neočekávanou odpověď.',
    'The service did not respond.' => 'Služba neodpověděla.',
    'The service does not exist.' => 'Služba neexistuje.',
    'The service has upcoming bookings – cancel them first, or switch the service off instead.' => 'Služba má nadcházející rezervace – nejdřív je zrušte, nebo službu místo toho vypněte.',
    'The service is deleted.' => 'Služba je smazána.',
    'The service is saved.' => 'Služba je uložena.',
    'The session does not exist.' => 'Relace neexistuje.',
    'The session is undone: %d rows restored, %d removed.' => 'Relace je vrácena: obnoveno řádků %d, odstraněno %d.',
    'The setting was saved.' => 'Nastavení bylo uloženo.',
    'The settings are saved, but the assistant key does not work: %s' => 'Nastavení je uložené, ale klíč asistenta nefunguje: %s',
    'The sheet was created – tick “Enquiries to a sheet” and new enquiries will appear in it.' => 'Tabulka je vytvořená – zaškrtněte „Poptávky do tabulky“ a nové poptávky se v ní objeví.',
    'The sign-in could not be verified. Try connecting again.' => 'Přihlášení se nepodařilo ověřit. Zkuste napojení znovu.',
    'The sign-in expired – connect %s again.' => 'Přihlášení vypršelo – napojte %s znovu.',
    'The sign-in has expired, please start again.' => 'Přihlášení vypršelo, začněte prosím znovu.',
    'The sign-in was cancelled: %s' => 'Přihlášení bylo zrušeno: %s',
    'The sign-in, password reset and Claude connection limits count visitors by it; behind Cloudflare choose Cloudflare, otherwise all visitors look alike.' => 'Limity přihlašování, obnovy hesla a spojení s Claudem počítají návštěvníky podle ní; za Cloudflarem zvolte Cloudflare, jinak vypadají všichni návštěvníci stejně.',
    'The signature from the device is not valid.' => 'Podpis zařízení neplatí.',
    'The site already has its own content. A Talea export can be imported only into a new, empty site.' => 'Web už má vlastní obsah. Export Talea jde naimportovat jen do nového, prázdného webu.',
    'The site answers more than 5000 pages – the fetch was stopped.' => 'Web odpovídá více než 5000 stránkami – stažení bylo zastaveno.',
    'The site appearance has been saved.' => 'Vzhled webu byl uložen.',
    'The site cannot run Claude by itself. It keeps the schedules below, tells a routine in Claude what is due, records each run and notices runs nobody picked up. The run itself happens in Claude – a scheduled task in the Claude app or a Claude Code routine – connected to this site with drafts-only access, so a run never publishes, deletes or sends anything.' => 'Web sám Clauda spustit nemůže. Uchovává níže uvedené plány, říká rutině v Claudovi, co je na řadě, zaznamenává každý běh a všimne si běhů, které si nikdo nevyzvedl. Samotný běh probíhá v Claudovi – jako naplánovaná úloha v aplikaci Claude nebo rutina v Claude Code – připojené k tomuto webu s přístupem jen ke konceptům, takže běh nikdy nic nepublikuje, nemaže ani neodesílá.',
    'The site certificate expires in %d days – check that it renews.' => 'Certifikát webu vyprší za %d dní – zkontrolujte, že se obnoví.',
    'The site certificate has expired – browsers warn visitors away from the site.' => 'Certifikát webu vypršel – prohlížeče návštěvníky od webu odrazují.',
    'The site did not answer the API request, it responded with error' => 'Web na požadavek API neodpověděl, vrátil chybu',
    'The site did not answer with JSON – this is not the address of the API.' => 'Web neodpověděl JSONem – toto není adresa API.',
    'The site has a custom menu – the page is added to its end. Change the order and submenus in Appearance → Menu.' => 'Web má sestavené menu – stránka se přidá na jeho konec. Pořadí a podmenu upravíte ve Vzhled → Menu.',
    'The site has a single language.' => 'Web má jediný jazyk.',
    'The site has been imported.' => 'Web je naimportovaný.',
    'The site has no collections yet.' => 'Web zatím nemá žádné kolekce.',
    'The site has no database backup yet.' => 'Web zatím nemá žádnou zálohu databáze.',
    'The site has no pop-ups.' => 'Web nemá žádná pop-up okna.',
    'The site is being imported. The administration is locked until the import is done – try again in a few minutes.' => 'Na web se právě importuje obsah. Administrace je do konce importu zamčená – zkuste to znovu za pár minut.',
    'The site is not in the console.' => 'Web v konzoli není.',
    'The site is paired with the console and has sent its first report.' => 'Web je spárovaný s konzolí a poslal první hlášení.',
    'The site is temporarily unavailable' => 'Web je dočasně mimo provoz',
    'The site logo from Appearance, otherwise the site name – a link to the home page.' => 'Logo webu z nastavení Vzhledu, jinak název webu – odkaz na úvodní stránku.',
    'The site no longer reports to the console.' => 'Web už konzoli nic nehlásí.',
    'The site part is back to its default design. The previous design is in the history when you open it in the builder again.' => 'Část webu se vrátila na výchozí podobu. Předchozí podobu najdete ve verzích, když ji znovu otevřete v builderu.',
    'The site redirected the API request from https to plain http – the token would travel unencrypted, so the fetch was stopped. Use the https address of the site.' => 'Web přesměroval požadavek na API z https na nešifrované http – token by šel po síti nezašifrovaný, proto se stahování zastavilo. Použijte https adresu webu.',
    'The site refused the request – the API token is wrong or missing, or it has no permission. Response:' => 'Web požadavek odmítl – API token je špatný nebo chybí, nebo nemá oprávnění. Odpověď:',
    'The site reports its problems in English; fix them in its administration.' => 'Web hlásí své problémy anglicky; opravíte je v jeho administraci.',
    'The site runs behind' => 'Web běží za',
    'The site runs on a local address – the certificate, the domain and the mail records are checked once it has its public address.' => 'Web běží na místní adrese – certifikát, doména a záznamy pošty se zkontrolují, až bude mít veřejnou adresu.',
    'The site sends password reset links and system notifications, and enquiries from forms. With your own SMTP server, messages go out from a verified mailbox and do not end up in spam.' => 'Web posílá odkazy pro obnovu hesla a upozornění systému; s formuláři přibudou i poptávky. Přes vlastní SMTP server zprávy odcházejí z ověřené schránky a nekončí ve spamu.',
    'The site sent a "next page" link that leads outside the site – the fetch was stopped.' => 'Web poslal odkaz na „další stránku“ mimo web – stažení bylo zastaveno.',
    'The site talks only to the services listed here, only after you connect them. Sign-ins and keys are stored encrypted and never shown again – not here, not to Claude, not in the site export.' => 'Web komunikuje jen se službami uvedenými zde a jen po jejich napojení. Přihlášení a klíče se ukládají šifrovaně a už se nikdy neukážou – ani tady, ani Claudovi, ani v exportu webu.',
    'The site texts (Search, News, Read more…) are in this language, and the site declares it to search engines.' => 'V tomto jazyce jsou texty webu (Hledat, Novinky, Číst dál…) a web se tak hlásí vyhledávačům.',
    'The site was paired with the fleet console %s.' => 'Web se spároval s konzolí webů %s.',
    'The site was removed from the console. It stops reporting with its next report; pair it again to bring it back.' => 'Web je z konzole odebraný. Jeho další hlášení konzole odmítne; vrátíte ho novým spárováním.',
    'The site will stop reporting to the console. Continue?' => 'Web přestane posílat hlášení konzoli. Pokračovat?',
    'The site’s own pages have not been scanned yet – the background tasks do it daily.' => 'Vlastní stránky webu ještě nebyly skenovány – úlohy na pozadí to dělají denně.',
    'The stable address of the current file – it stays the same when a new version replaces the file.' => 'Stálá adresa aktuálního souboru – zůstává stejná, i když soubor nahradí nová verze.',
    'The state before the import is in backup %s (Settings → Backups).' => 'Stav před importem je v záloze %s (Nastavení → Zálohy).',
    'The state before the import is in backup %s (Settings → Backups). Check the site, then delete the export file – it is no longer needed.' => 'Stav před importem je v záloze %s (Nastavení → Zálohy). Web zkontrolujte a pak soubor exportu smažte – už není potřeba.',
    'The state before the restore is in backup %s – please restore it.' => 'Stav před obnovou je v záloze %s – obnovte ji prosím.',
    'The status is saved.' => 'Stav je uložen.',
    'The structured data has no valid type – choose one or remove the element.' => 'Strukturovaná data nemají platný typ – vyberte jeden, nebo prvek odstraňte.',
    'The structured data “%s” is missing required properties: %s.' => 'Strukturovaným datům „%s“ chybí povinné vlastnosti: %s.',
    'The subscriber has been deleted.' => 'Odběratel byl smazán.',
    'The suggestion is only inserted into the field – you can keep editing it. Nothing is saved until you save the form.' => 'Návrh se jen vloží do pole – můžete ho dál upravit. Nic se neuloží, dokud formulář neuložíte.',
    'The system does most things itself: URLs, descriptions, the sitemap, structured data and resources for AI search engines. Here you decide only on the essentials.' => 'Většinu věcí dělá systém sám: adresy, popisy, sitemapu, strukturovaná data i podklady pro AI vyhledávače. Tady rozhodujete jen o tom hlavním.',
    'The system has been updated to version %s. The database will update itself the next time the administration loads.' => 'Systém byl aktualizován na verzi %s. Databáze se upraví sama při příštím načtení administrace.',
    'The system inserts the news item, news list or 404 message here. Use it exactly once in a wrapper.' => 'Sem systém vloží novinku, výpis novinek nebo hlášení 404. V obálce patří právě jednou.',
    'The system is running, but some items deserve attention.' => 'Systém běží, některé položky si zaslouží pozornost.',
    'The table has no header (TH cells) – a screen reader cannot tell what each column means.' => 'Tabulka nemá záhlaví (buňky TH) – čtečka neumí říct, co který sloupec znamená.',
    'The tables were created, but config.php could not be written. Check the write permissions.' => 'Tabulky jsou vytvořeny, ale nepodařilo se zapsat config.php. Zkontrolujte práva k zápisu.',
    'The tag does not exist.' => 'Štítek neexistuje.',
    'The target must be a path on this site or a full https://… address.' => 'Cíl musí být cesta na tomto webu nebo celá adresa https://….',
    'The target would match the rule itself: a loop.' => 'Cíl by odpovídal samotnému pravidlu: smyčka.',
    'The template could not be used.' => 'Šablonu se nepodařilo použít.',
    'The template is in the draft – adjust it and publish; until then visitors see the published version.' => 'Šablona je v konceptu – upravte ji a publikujte; do té doby návštěvníci vidí publikovanou podobu.',
    'The test address is not a valid e-mail.' => 'Adresa pro zkoušku není platný e-mail.',
    'The test call has been delivered.' => 'Zkušební volání bylo doručeno.',
    'The test call was not delivered – the reason is in the delivery log. It will be retried automatically.' => 'Zkušební volání se nepodařilo doručit – důvod je v protokolu doručení. Zkusí se znovu samo.',
    'The test e-mail could not be sent: %s' => 'Zkušební e-mail se nepodařilo odeslat: %s',
    'The test e-mail went to %s.' => 'Zkušební e-mail odešel na %s.',
    'The text font %s has no %s letters: the %s version shows them in a fallback font of the visitor’s device.' => 'Písmo textu %s nemá %s znaky: verze %s je ukazuje náhradním písmem zařízení návštěvníka.',
    'The text has %d words.' => 'Text má %d slov.',
    'The text has not changed since this version (formatting and image changes are not compared).' => 'Text se od této verze nezměnil (změny formátování a obrázků se neporovnávají).',
    'The text links to no other page of this site.' => 'Text neodkazuje na žádnou další stránku tohoto webu.',
    'The text links to no other website.' => 'Text neodkazuje na žádný jiný web.',
    'The text links to other pages of this site.' => 'Text odkazuje na další stránky tohoto webu.',
    'The text links to other websites.' => 'Text odkazuje na jiné weby.',
    'The text still has placeholders in square brackets (%s) – fill them in or delete them.' => 'Text stále obsahuje zástupné texty v hranatých závorkách (%s) – doplňte je nebo smažte.',
    'The three latest news items and a link to all of them.' => 'Tři nejnovější novinky a odkaz na všechny.',
    'The time is held until %s.' => 'Termín je držen do %s.',
    'The time must be HH:MM.' => 'Čas musí být ve tvaru HH:MM.',
    'The time must be free for the person within their hours; the lead time for visitors does not apply here.' => 'Čas musí být u člověka volný v rámci jeho hodin; předstih pro návštěvníky tu neplatí.',
    'The time must be in the future, as YYYY-MM-DD HH:MM.' => 'Čas musí být v budoucnosti, ve tvaru RRRR-MM-DD HH:MM.',
    'The time zone setting is %s, but PHP runs in %s – this server does not know the zone, so dates are written and shown on the %s clock. Choose the zone again in Settings → General.' => 'Nastavené časové pásmo je %s, ale PHP běží v %s – tento server pásmo nezná, proto se data zapisují a zobrazují podle hodin %s. Vyberte pásmo znovu v Nastavení → Obecné.',
    'The times need an existing person.' => 'Časy potřebují existující osobu.',
    'The title contains a number.' => 'Titulek obsahuje číslo.',
    'The title contains no number.' => 'Titulek neobsahuje číslo.',
    'The title has %d characters – %d to %d is best for search results.' => 'Titulek má %d znaků – pro výsledky hledání je nejlepších %d až %d.',
    'The title has %d characters – search engines cut it after about %d.' => 'Titulek má %d znaků – vyhledávače ho zkrátí asi po %d.',
    'The title has %d characters – search results cut it after about 60.' => 'Titulek má %d znaků – výsledky hledání ho zkrátí asi po 60.',
    'The title has %d characters.' => 'Titulek má %d znaků.',
    'The title must not be empty.' => 'Titulek nesmí zůstat prázdný.',
    'The title “%s” is used %d times – search engines cannot tell the pages apart.' => 'Titulek „%s“ je použitý %d× – vyhledávače stránky od sebe nerozliší.',
    'The token has an unexpected form.' => 'Token má nečekanou podobu.',
    'The token has been created.' => 'Token je vytvořený.',
    'The token is used only for this fetch and is not stored anywhere.' => 'Token se použije jen pro toto stažení a nikam se neukládá.',
    'The token {{%s}} cannot be computed – visitors see nothing in its place. years_since takes a year, a date (YYYY-MM-DD) or a fact with one; count takes the address of a collection, or news.' => 'Značku {{%s}} nejde spočítat – návštěvníci na jejím místě nic neuvidí. years_since bere rok, datum (RRRR-MM-DD) nebo fakt s nimi; count bere adresu kolekce, nebo news.',
    'The topic must be one of: %s.' => 'Téma musí být jedno z: %s.',
    'The translation has been created as a draft. Read it before publishing – the assistant can make mistakes in names, numbers and technical terms.' => 'Překlad je založený jako koncept. Než ho vydáte, přečtěte ho – asistent může chybovat ve jménech, číslech a odborných výrazech.',
    'The translation starts as a copy of the original – replace the texts, then publish.' => 'Překlad začíná jako kopie originálu – přepište texty a pak ho zveřejněte.',
    'The trash is empty.' => 'Koš je prázdný.',
    'The unpublished look changes were discarded.' => 'Nepublikované změny vzhledu jsou zahozené.',
    'The upload is larger than the server allows (at most %s), so nothing arrived. Upload a smaller file or raise post_max_size on the server.' => 'Nahrávaný soubor je větší, než server dovolí (nejvýše %s), proto nic nedorazilo. Nahrajte menší soubor nebo zvyšte post_max_size na serveru.',
    'The uploaded file was a %s export and has been converted into a Talea export automatically.' => 'Nahraný soubor byl export z %s a byl automaticky převeden na export Talea.',
    'The user can change it later under My account.' => 'Uživatel si ho pak změní v nabídce Můj účet.',
    'The user has been created and the invitation sent to %s.' => 'Uživatel je založený a pozvánka odešla na %s.',
    'The user has been deleted. Their news items remain, without an author.' => 'Uživatel byl smazán. Jeho novinky zůstaly zachované bez autora.',
    'The user has no e-mail or is blocked.' => 'Uživatel nemá e-mail nebo je zablokovaný.',
    'The value does not fit the type of the fact (%s).' => 'Hodnota neodpovídá typu faktu (%s).',
    'The value of a field is not valid, nothing was saved. A separator has up to three characters.' => 'Hodnota některého pole není platná, nic se neuložilo. Oddělovač má nejvýše tři znaky.',
    'The variant needs a name.' => 'Varianta musí mít název.',
    'The variant was deleted – the selected pages have the default version again.' => 'Varianta byla smazána – vybrané stránky mají zase výchozí podobu.',
    'The version does not exist.' => 'Verze neexistuje.',
    'The visitor sends a request instead of a booking. Talea holds the time until you accept, decline or propose other times, and tells the customer by e-mail.' => 'Návštěvník pošle žádost místo rezervace. Talea termín podrží, dokud ji nepřijmete, neodmítnete nebo nenavrhnete jiné termíny, a dá zákazníkovi vědět e-mailem.',
    'The visitor’s browser remembers it (sessionStorage and localStorage), not cookies.' => 'Pamatuje si to prohlížeč návštěvníka (sessionStorage a localStorage), ne cookies.',
    'The website aims to meet EN 301 549 and WCAG 2.1 level AA.' => 'Web usiluje o splnění normy EN 301 549 a WCAG 2.1 úrovně AA.',
    'The website measures traffic without cookies. It uses third-party cookies only with your consent.' => 'Web měří návštěvnost bez cookies. Cookies třetích stran použije jen s vaším souhlasem.',
    'The website requires two-step sign-in – you can create a token once you turn it on.' => 'Web vyžaduje dvoufázové přihlášení – token vytvoříte, až si ho zapnete.',
    'The weekly hours and days off of each person apply.' => 'Platí týdenní hodiny a volné dny každé osoby.',
    'The whole site' => 'Celý web',
    'The writing assistant' => 'Asistent psaní',
    'The writing assistant is not enabled (Features).' => 'Asistent psaní není zapnutý (Funkce).',
    'The writing assistant is not enabled or the key is missing (Features).' => 'Asistent psaní není zapnutý nebo chybí klíč (Funkce).',
    'The zip extension is missing on the server – download the media via FTP.' => 'Na serveru chybí rozšíření zip – média si stáhněte přes FTP.',
    'Then submit the sitemap address in Search Console:' => 'Do Search Console pak vložte adresu sitemapy:',
    'There are no confirmed subscribers yet.' => 'Zatím nejsou žádní potvrzení odběratelé.',
    'There are no drafts to rewrite.' => 'Nejsou žádné návrhy k přepsání.',
    'There are no news items yet.' => 'Zatím tu není žádná novinka.',
    'There are no news yet.' => 'Zatím zde nejsou žádné novinky.',
    'There is a new private address. The old one does not work any more.' => 'Je tu nová soukromá adresa. Stará už nefunguje.',
    'There is no database with this name on the server. Create it in your hosting control panel or correct the name.' => 'Databáze s tímto názvem na serveru není. Založte ji v administraci hostingu, nebo opravte název.',
    'There is no news yet.' => 'Zatím tu nejsou žádné novinky.',
    'There is no published version yet – nothing to revert to.' => 'Zatím není publikovaná verze – není k čemu se vrátit.',
    'There is nobody to send the report to – fill in the recipients, or the site e-mail on the General tab.' => 'Zprávu není komu poslat – vyplňte příjemce, nebo e-mail webu na záložce Základní.',
    'There is not enough disk space for an archive with media, so the export contains data only (JSON). Download the media/ folder over FTP.' => 'Na disku není dost místa pro archiv s médii, export proto obsahuje jen data (JSON). Složku media/ si stáhněte přes FTP.',
    'There is nothing in the media/ folder yet.' => 'Ve složce media/ zatím nic není.',
    'There is nothing to publish.' => 'Není co publikovat.',
    'There was nothing to publish.' => 'Nebylo co publikovat.',
    'These are questions and answers (FAQ for search engines)' => 'Jsou to otázky a odpovědi (FAQ pro vyhledávače)',
    'These changes could not be followed row by row and stay as they are – check them by hand:' => 'Tyto změny nešlo sledovat po řádcích a zůstávají, jak jsou – zkontrolujte je ručně:',
    'These fields have an invalid format and were not saved: %s.' => 'Tato pole mají neplatný formát a nebyla uložena: %s.',
    'These fields have an invalid format and were not saved: %s. Please correct them (they are highlighted); the other settings are saved.' => 'Tato pole nemají platný tvar a neuložila se: %s. Opravte je prosím (jsou zvýrazněná), ostatní nastavení je uložené.',
    'These got a number at the end; the old address redirects to the new one. Once each language version can have its own addresses, they can get their original address back.' => 'Tyto adresy dostaly na konci číslo; stará adresa přesměruje na novou. Až bude mít každá jazyková verze vlastní adresy, mohou dostat zpět původní adresu.',
    'These lines are not addresses and are ignored: %s' => 'Tyto řádky nejsou adresy a nepoužijí se: %s',
    'These numbers are fixed. A person can promote a version at any time; automatic promotion waits until all of them are met.' => 'Tato čísla jsou pevná. Člověk může verzi povýšit kdykoli; automatické povýšení počká, až budou splněna všechna.',
    'These services have times of their own:' => 'Tyto služby mají vlastní časy:',
    'These times replace the weekly hours for this service.' => 'Tyto časy pro tuto službu nahradí týdenní hodiny.',
    'They carry CVs – only the file name goes out, never the file' => 'Nesou životopisy – odejde jen název souboru, nikdy soubor',
    'They hold for every Claude connection on top of its access. Claude is told why when it hits one, so it can tell you.' => 'Platí pro každé napojení Clauda navíc k jeho oprávnění. Když na některý narazí, Claude se dozví proč a může vám to říct.',
    'Third' => 'Třetina',
    'Third benefit' => 'Třetí výhoda',
    'Third slide' => 'Třetí snímek',
    'This Kaleta export has a format version Talea does not know – export the site again with Kaleta 3.7 or newer.' => 'Tento export z Kalety má verzi formátu, kterou Talea nezná – exportujte web znovu z Kalety 3.7 nebo novější.',
    'This URL is used by the system, choose another one.' => 'Tuto adresu používá systém, zvolte jinou.',
    'This browser does not support passkeys, or the site is not running on HTTPS.' => 'Tento prohlížeč přihlašovací klíče nepodporuje, nebo web neběží na HTTPS.',
    'This element cannot be tested.' => 'Tento prvek nelze testovat.',
    'This element could not be displayed.' => 'Prvek se nepodařilo vykreslit.',
    'This element has no editable content.' => 'Prvek nemá nastavitelný obsah.',
    'This fact comes from the settings (Business details) – change it there.' => 'Tento fakt pochází z nastavení (Údaje o firmě) – změňte ho tam.',
    'This group still restricts pages, items or news. Remove the restriction first – otherwise they would become public.' => 'Tato skupina stále omezuje stránky, položky nebo novinky. Nejprve omezení odstraňte – jinak by se staly veřejnými.',
    'This help' => 'Tato nápověda',
    'This is already a focus keyword of the page.' => 'Toto už je klíčové slovo stránky.',
    'This is not a Blogger export. In Blogger open Settings → Manage blog → Back up content and download the .xml file.' => 'Toto není export z Bloggeru. V Bloggeru otevřete Nastavení → Správa blogu → Zálohovat obsah a stáhněte soubor .xml.',
    'This is not a Drupal fetch. Enter the site address in Import and export → From another system and fetch the content again.' => 'Toto není stažení z Drupalu. Zadejte adresu webu v Import a export → Z jiného systému a obsah stáhněte znovu.',
    'This is not a Ghost export. In Ghost Admin open Settings → Labs → Export your content and download the .json file.' => 'Toto není export z Ghostu. V administraci Ghostu otevřete Settings → Labs → Export your content a stáhněte soubor .json.',
    'This is not a Joomla fetch. Enter the site address and the API token in Import and export → From another system and fetch the content again.' => 'Toto není stažení z Joomly. Zadejte adresu webu a API token v Import a export → Z jiného systému a obsah stáhněte znovu.',
    'This is not a Webflow collection export – the first row has no Name and Slug columns. In the Webflow Designer open CMS → the collection → Export and download the .csv file.' => 'Toto není export kolekce Webflow – první řádek nemá sloupce Name a Slug. Ve Webflow Designeru otevřete CMS → kolekce → Export a stáhněte soubor .csv.',
    'This is not a WordPress export. In WordPress open Tools → Export, choose “All content” and download the .xml file.' => 'Tohle není export z WordPressu. Ve WordPressu otevřete Nástroje → Export, zvolte „Veškerý obsah“ a stáhněte soubor .xml.',
    'This is not a pairing key of a Talea console (it starts with talea-console:).' => 'Tohle není párovací klíč konzole Talea (začíná talea-console:).',
    'This is not the JSON:API of Drupal – the answer has no "jsonapi" and "data".' => 'Toto není JSON:API Drupalu – odpověď nemá „jsonapi“ a „data“.',
    'This is not the Web Services API of Joomla – the answer has no "data" and "links".' => 'Toto není Web Services API Joomly – odpověď nemá „data“ a „links“.',
    'This is switched off in the public demo. Install Talea to try it.' => 'Ve veřejném demu je tohle vypnuté. Vyzkoušíte to po instalaci Talea.',
    'This is the home page: its address is the root. Choose another home page in Settings → General.' => 'Toto je úvodní stránka: její adresa je kořen webu. Jinou úvodní stránku zvolíte v Nastavení → Obecné.',
    'This is the plan. Change anything you like, then create the drafts: the look waits in the draft look, the pages are hidden, nothing is published.' => 'Tohle je plán. Cokoli upravte a pak vytvořte koncepty: vzhled čeká v konceptu vzhledu, stránky jsou skryté, nic se nezveřejní.',
    'This is the public demo of Talea. Sign in as %s with the password %s. Everything you change disappears at the next hourly reset.' => 'Tohle je veřejné demo Talea. Přihlaste se jako %s s heslem %s. Všechno, co změníte, zmizí při příštím obnovení, které probíhá každou hodinu.',
    'This is what it says about itself – Talea cannot check it, an add-on runs with the same rights as Talea.' => 'Toto doplněk uvádí sám o sobě – Talea to nemůže ověřit, doplněk běží se stejnými právy jako Talea.',
    'This key does not belong to the account.' => 'Tenhle klíč k účtu nepatří.',
    'This key is already registered.' => 'Tenhle klíč už je zaregistrovaný.',
    'This month is not in the archive.' => 'Tento měsíc v archivu není.',
    'This news item is published – only an editor or administrator can save changes to it. Ask them to edit it.' => 'Novinka je vydaná – změny v ní uloží jen editor nebo správce. Požádejte je o úpravu.',
    'This page' => 'Tato stránka',
    'This page belongs to the add-on %s.' => 'Tato stránka patří doplňku %s.',
    'This page does not exist.' => 'Tato stránka neexistuje.',
    'This page is protected from changes by the assistant (Claude settings → Guardrails for Claude).' => 'Tato stránka je před změnami asistenta chráněna (Nastavení Clauda → Mantinely pro Clauda).',
    'This page\'s content is built in the builder.' => 'Obsah této stránky se skládá v builderu.',
    'This passkey is not registered on this site.' => 'Tento přihlašovací klíč není na tomto webu zaregistrovaný.',
    'This policy explains how [COMPANY NAME], company ID [ID], registered at [ADDRESS], processes the personal data you entrust to us.' => 'Tyto zásady vysvětlují, jak [NÁZEV FIRMY], IČO [IČO], se sídlem [ADRESA] zpracovává osobní údaje, které nám svěříte.',
    'This search cannot be a focus keyword: a keyword has no comma and up to 100 characters.' => 'Toto hledání nemůže být klíčovým slovem: klíčové slovo nemá čárku a má nejvýše 100 znaků.',
    'This server cannot download files from other sites (both curl and allow_url_fopen are missing, or the GD extension). Move the images manually: upload them to Media and replace them in the articles.' => 'Tento server neumí stahovat soubory z jiných webů (chybí curl i allow_url_fopen, případně rozšíření GD). Obrázky přeneste ručně: nahrajte je do Médií a v článcích je vyměňte.',
    'This server cannot download from other sites (both curl and allow_url_fopen are missing, or the GD extension).' => 'Tento server neumí stahovat z jiných webů (chybí curl i allow_url_fopen, nebo rozšíření GD).',
    'This server cannot draw pictures (the PHP GD extension is missing), so nothing is generated.' => 'Tento server neumí kreslit obrázky (chybí rozšíření PHP GD), nic se tedy nevytváří.',
    'This session was already undone.' => 'Tato relace už byla vrácena.',
    'This site already has its own content (pages: %d, news: %d, collection items: %d, media: %d). A Talea export can be imported only into a new, empty site – install Talea again and choose “Start from an export”.' => 'Tento web už má vlastní obsah (stránky: %d, novinky: %d, položky kolekcí: %d, média: %d). Export Talea jde naimportovat jen do nového, prázdného webu – nainstalujte Talea znovu a zvolte „Začít z exportu“.',
    'This site already has its own content, so an export cannot be imported here. Install Talea again and choose “Start from an export”.' => 'Tento web už má vlastní obsah, export sem proto naimportovat nejde. Nainstalujte Talea znovu a zvolte „Začít z exportu“.',
    'This site requires two-factor sign-in. Please turn it on below – until then the administration is locked.' => 'Web vyžaduje dvoufázové přihlášení. Zapněte si ho prosím níže – do té doby je administrace zamčená.',
    'This statement was prepared on %s from an automatic check of the site. The automatic check does not cover everything a person would notice; the owner reviews the statement before publishing it.' => 'Toto prohlášení bylo vypracováno %s na základě automatické kontroly webu. Automatická kontrola nepokrývá vše, čeho by si všiml člověk; provozovatel prohlášení před zveřejněním zkontroluje.',
    'This status change is not possible.' => 'Tahle změna stavu není možná.',
    'This system has no fetch step.' => 'Tento systém nemá krok stažení.',
    'This time has been taken meanwhile – propose other times or decline the request.' => 'Termín mezitím obsadil někdo jiný – navrhněte jiné termíny, nebo žádost odmítněte.',
    'This time is not free for the chosen person – pick another time.' => 'Tento čas u zvoleného člověka není volný – vyberte jiný.',
    'This user has no access to the database. Grant it in your hosting control panel.' => 'Uživatel k této databázi nemá přístup. Přidělte mu ji v administraci hostingu.',
    'This version of the news item does not exist.' => 'Verze novinky neexistuje.',
    'This version of the page does not exist.' => 'Tato verze stránky neexistuje.',
    'This website has no connection with this application yet. An application chooses its name itself, so the name is not verified – allow access only if you started this connection yourself.' => 'Tento web s touto aplikací zatím není propojený. Aplikace si název volí sama, takže není ověřený – přístup povolte, jen pokud jste propojení zahájili sami.',
    'Three big numbers with labels, without a coloured band.' => 'Tři velká čísla s popiskem, bez barevného pásu.',
    'Three cards linking to subpages.' => 'Tři karty jako odkazy na podstránky.',
    'Three cards with price and features, the middle one highlighted.' => 'Tři karty s cenou a výčtem, prostřední zvýrazněná.',
    'Three or four principles you work by.' => 'Tři až čtyři zásady, podle kterých pracujete.',
    'Three questions, then a look tried on your own site, the features and first pages you need – all as drafts. With your own AI key the assistant can write the texts.' => 'Tři otázky, pak vzhled vyzkoušený na vlastním webu, potřebné funkce a první stránky – vše jako koncepty. S vlastním klíčem AI napíše asistent i texty.',
    'Three short reviews with stars.' => 'Tři krátké recenze s hvězdičkami.',
    'Thumbnail shape' => 'Tvar náhledů',
    'Thumbs up' => 'Palec nahoru',
    'Thursday' => 'Čtvrtek',
    'Tick one or more groups: only their members can read it. Nothing ticked = public. Restricted content is never cached, indexed or searchable.' => 'Zaškrtněte jednu či více skupin: číst to mohou jen jejich členové. Nic nezaškrtnuto = veřejné. Omezený obsah se nikdy neukládá do cache, neindexuje se a nedá se vyhledat.',
    'Tick that you trust the code of this add-on.' => 'Zaškrtněte, že kódu tohoto doplňku věříte.',
    'Tick that you want to erase the data.' => 'Zaškrtněte, že chcete údaje vymazat.',
    'Time' => 'Čas',
    'Time remaining until a date – an event, an opening, a registration deadline.' => 'Zbývající čas do data – akce, otevření provozovny, uzávěrka přihlášek.',
    'Time zone' => 'Časové pásmo',
    'Time, a random identifier and the chosen categories – no IP address. Evidence in case of an audit.' => 'Čas, náhodný identifikátor a zvolené kategorie – bez IP adresy. Doklad pro případnou kontrolu.',
    'Timeline' => 'Časová osa',
    'Tips and news from our field. No spam – unsubscribe with one click.' => 'Tipy a novinky z našeho oboru. Žádný spam, odhlásit se můžete jedním kliknutím.',
    'Title' => 'Titulek',
    'Title in search results' => 'Titulek ve výsledcích hledání',
    'Title or text' => 'Nadpis nebo text',
    'Title, description and sharing image are set.' => 'Titulek, popis i obrázek pro sdílení jsou nastavené.',
    'Titles' => 'Titulky',
    'Titles and descriptions' => 'Titulky a popisy',
    'Titles with a number often get more clicks.' => 'Titulky s číslem dostávají často více kliknutí.',
    'To add a kind, fill in the empty row and save. Deleting a kind leaves its enquiries not sorted.' => 'Nový druh přidáte vyplněním prázdného řádku a uložením. Po smazání druhu zůstanou jeho poptávky nezařazené.',
    'To confirm' => 'K potvrzení',
    'To decide' => 'K rozhodnutí',
    'To do' => 'K vyřízení',
    'To embed a video, put its address (YouTube, Vimeo) on a line of its own. It loads for the visitor only after a click.' => 'Video vložíte tak, že jeho adresu (YouTube, Vimeo) dáte na samostatný řádek. Návštěvníkovi se načte až po kliknutí.',
    'To fix' => 'K opravě',
    'Today' => 'Dnes',
    'Toggle light and dark mode' => 'Přepnout světlý a tmavý režim',
    'Token' => 'Značka',
    'Token revoked.' => 'Token byl zrušen.',
    'Tokens' => 'Tokeny',
    'Tokens file' => 'Soubor s tokeny',
    'Tom K.' => 'Tomáš K.',
    'Tone of the texts' => 'Tón textů',
    'Too many attempts in a row. Please try again in a moment.' => 'Příliš mnoho pokusů za sebou. Zkuste to prosím za chvíli.',
    'Too many attempts. Try again in 15 minutes.' => 'Příliš mnoho pokusů. Zkuste to znovu za 15 minut.',
    'Too many calls to %s this minute – it will be tried again.' => 'Příliš mnoho volání %s za tuto minutu – zkusí se to znovu.',
    'Too many messages have come from your address in a short time. Please try again later.' => 'Z vaší adresy přišlo v krátké době příliš mnoho zpráv. Zkuste to prosím později.',
    'Too many redirects.' => 'Příliš mnoho přesměrování.',
    'Too many requests. Try again in 15 minutes.' => 'Příliš mnoho žádostí. Zkuste to znovu za 15 minut.',
    'Too many searches in a row. Please try again in a moment.' => 'Příliš mnoho hledání za sebou. Zkuste to prosím za chvíli.',
    'Too many sign-in attempts. Try again in 15 minutes.' => 'Příliš mnoho pokusů o přihlášení. Zkuste to znovu za 15 minut.',
    'Tools' => 'Nářadí',
    'Top line' => 'Linka nahoře',
    'Top pages' => 'Nejlepší stránky',
    'Top pages (Bing)' => 'Nejčastější stránky (Bing)',
    'Top pages (Google)' => 'Nejčastější stránky (Google)',
    'Top queries (Bing)' => 'Nejčastější dotazy (Bing)',
    'Top queries (Google)' => 'Nejčastější dotazy (Google)',
    'Top searches' => 'Nejčastější hledání',
    'Topic' => 'Téma',
    'Topic image' => 'Obrázek tématu',
    'Topic introduction' => 'Úvod tématu',
    'Topic page with an introduction' => 'Stránka tématu s úvodem',
    'Total:' => 'Celkem:',
    'Tracking codes run immediately. Only if you handle consent another way.' => 'Měřicí kódy se spouštějí hned. Jen když souhlas řešíte jinak.',
    'Traditional' => 'Tradiční',
    'Traffic' => 'Návštěvnost',
    'Traffic and conversions' => 'Návštěvnost a konverze',
    'Trailing slash in URLs' => 'Lomítko na konci adres',
    'Translate' => 'Přeložit',
    'Translate the Services page into German.' => 'Přeložte stránku Služby do angličtiny.',
    'Translate the home page' => 'Přeložit úvodní stránku',
    'Translate the page “%s” into %s: start the translation as a copy of the original build, translate all its texts and leave it as a draft for me to check.' => 'Přelož stránku „%s“ do jazyka %s: začni překlad jako kopii buildu originálu, přelož všechny její texty a nech ho jako koncept ke kontrole.',
    'Translate the saved version with the assistant? A draft is created for you to read before publishing. Translation can take up to a minute.' => 'Přeložit uloženou verzi asistentem? Vznikne koncept, který před vydáním přečtete. Překlad může trvat i minutu.',
    'Translate with the assistant' => 'Přeložit asistentem',
    'Translate “%s” into %s – the page starts as a copy of the original; replace the texts and publish.' => 'Překlad stránky „%s“ do jazyka %s – stránka začíná jako kopie originálu; přepište texty a zveřejněte ji.',
    'Translate “%s” into %s – the text below is a copy of the original; replace it and publish.' => 'Překlad stránky „%s“ do jazyka %s – text níže je kopie originálu; přepište ho a zveřejněte.',
    'Translation' => 'Překlad',
    'Translation: %s → %s' => 'Překlad: %s → %s',
    'Translations' => 'Překlady',
