    'Try the failed ones again' => 'Zkusit nepovedené znovu',
    'Try two versions of a headline, a section or a whole page and see which one brings more enquiries. Visitors get a random version, nothing is stored in their browser, and the counting works without cookies.' => 'Vyzkoušejte dvě verze nadpisu, sekce nebo celé stránky a zjistěte, která přináší víc poptávek. Návštěvník dostane náhodnou verzi, nic se mu neukládá v prohlížeči a počítání funguje bez cookies.',
    'Tuesday' => 'Úterý',
    'Turn off' => 'Vypnout',
    'Turn off only for a site under construction.' => 'Vypněte jen u webu ve výstavbě.',
