    'Turn on two-factor sign-in first.' => 'Nejdřív zapněte dvoufázové přihlášení.',
    'Twenty blueprints – from a software company or a restaurant to a clinic or a trade – add the collections, facts and checks such a business needs; Claude can make one for any other.' => 'Dvacet oborových plánů – od softwarové firmy nebo restaurace po ordinaci či řemeslo – přidá kolekce, údaje a kontroly, které takový podnik potřebuje; pro jakýkoli jiný obor ho připraví Claude.',
    'Two pages for the same keyword compete with each other.' => 'Dvě stránky pro stejné klíčové slovo si navzájem konkurují.',
    'Two photos with a draggable divider – a renovation, a cleaning, a makeover.' => 'Dvě fotky s posuvným dělítkem – rekonstrukce, úklid, proměna.',
    'Two rows: image with text, then the other way round.' => 'Dva řádky: obrázek s textem, podruhé obráceně.',
    'Two-factor sign-in' => 'Dvoufázové přihlášení',
