    'Two-factor sign-in is turned off.' => 'Dvoufázové přihlášení je vypnuté.',
    'Two-letter code: CZ, SK, DE…' => 'Dvoupísmenný kód: CZ, SK, DE…',
    'Two-letter codes separated by commas, e.g. RU, CN. Only when the country is known (see above).' => 'Dvoupísmenné kódy oddělené čárkou, např. RU, CN. Jen když je země známá (viz výše).',
    'Two-step sign-in for administrators' => 'Dvoufázové přihlášení správců',
    'Type' => 'Typ',
    'Type and spacing grow smoothly with the window width – from phone to large monitor. Headings are multiples of the base font size.' => 'Písmo i mezery rostou plynule s šířkou okna – od telefonu po velký monitor. Nadpisy jsou násobky základního písma.',
    'Type area names into the cells (the same name across several cells = the element spans them). Then give the nested element its “Grid area”.' => 'Do buněk napište názvy oblastí (stejný název přes víc buněk = prvek se roztáhne). Vnořenému prvku pak zadejte „Oblast v mřížce“.',
    'Type scale' => 'Poměr velikostí písma',
    'Typewriter' => 'Psací stroj',
    'Typical ones: a site review every Monday, a report on the first of the month, a triage of new enquiries every morning, the open requests from staff every day.' => 'Typické plány: kontrola webu každé pondělí, zpráva prvního v měsíci, třídění nových poptávek každé ráno, otevřené požadavky kolegů každý den.',
    'Typographic minimalism: black on white, one family, no ornament and sharp corners.' => 'Typografický minimalismus: černá na bílé, jedna rodina písma, žádné ozdoby a ostré rohy.',
