    'Upload images and attachments' => 'Nahrát obrázky a přílohy',
    'Upload new' => 'Nahrát nový',
    'Upload size limit' => 'Limit nahrávaných souborů',
    'Upload the font files (.woff2) to Media and paste their address here. One variable font file is enough, or a regular and a bold weight. After saving, choose the font above.' => 'Nahrajte soubory písma (.woff2) do Médií a vložte sem jejich adresu. Stačí jeden variabilní soubor, nebo běžný a tučný řez. Po uložení písmo vyberete výše.',
    'Upload the latest database backup (talea-….sql.gz from your FTP or S3 copy, or a downloaded one) over FTP into storage/backups/.' => 'Nahrajte poslední zálohu databáze (talea-….sql.gz z kopie na FTP nebo S3, nebo staženou) přes FTP do storage/backups/.',
    'Upload your first photos with the form above – or drag them straight into the text in the editor.' => 'Nahrajte první fotky formulářem nahoře – nebo je přetáhněte přímo do textu v editoru.',
    'Uploaded' => 'Nahráno',
    'Uploaded images and files go to the folder media/ of the same target. A file deleted on the site stays in the copy.' => 'Nahrané obrázky a soubory jdou do složky media/ na stejném místě. Soubor smazaný na webu v kopii zůstane.',
