    'Used on' => 'Použito na',
    'Used when a page has no image of its own. Ideally 1200×630 px.' => 'Použije se, když stránka nemá vlastní obrázek. Ideálně 1200×630 px.',
    'Used when no kind of business above fits.' => 'Použije se, když žádný druh podnikání výše nesedí.',
    'User' => 'Uživatel',
    'User accounts and passwords – choose below whose the posts will be.' => 'Účty a hesla uživatelů – níže vyberte, komu budou příspěvky patřit.',
    'User accounts and passwords – the news items will belong to you. Comments are not transferred.' => 'Účty a hesla uživatelů – novinky budou patřit vám. Komentáře se nepřenášejí.',
    'User does not exist.' => 'Uživatel neexistuje.',
