    'User:' => 'Uživatel:',
    'Username: 2-40 characters, only letters without diacritics, digits, period, hyphen and underscore.' => 'Přihlašovací jméno: 2-40 znaků, jen písmena bez diakritiky, číslice, tečka, pomlčka a podtržítko.',
    'Username: 2–40 characters, letters without accents, digits, dot, hyphen, underscore.' => 'Přihlašovací jméno: 2-40 znaků, písmena bez diakritiky, číslice, tečka, pomlčka, podtržítko.',
    'Users' => 'Uživatelé',
    'Users and roles' => 'Uživatelé a role',
    'Uses no cookies, loads without consent.' => 'Nepoužívá cookies, načítá se bez souhlasu.',
    'Using Brevo, MailerLite, Mailchimp, Ecomail or SmartEmailing? Once connected in Features, the site sends confirmed subscribers straight to your list.' => 'Používáte Brevo, MailerLite, Mailchimp, Ecomail nebo SmartEmailing? Po napojení ve Funkcích posílá web potvrzené odběratele rovnou do vašeho seznamu.',
    'Usual practice in %s: %d months – check with your lawyer.' => 'Obvyklá praxe v %s: %d měsíců – ověřte u svého právníka.',
    'Usually the full e-mail address of the mailbox.' => 'Obvykle celá e-mailová adresa schránky.',
