    'Version' => 'Verze',
    'Version B has no content to promote.' => 'Verze B nemá obsah k povýšení.',
    'Version B has no content yet. Publish it first.' => 'Verze B zatím nemá obsah. Nejdřív ji zveřejněte.',
    'Version B is saved as a draft of the page. Someone who may publish has to publish it.' => 'Verze B je uložena jako koncept stránky. Zveřejnit ji musí někdo s oprávněním publikovat.',
    'Version B must be a published page made in the builder.' => 'Verze B musí být zveřejněná stránka vytvořená v editoru.',
    'Version B page' => 'Stránka verze B',
    'Version B replaced the original and is published. You can undo it here.' => 'Verze B nahradila původní a je zveřejněna. Zde to můžete vrátit.',
