    'Views' => 'Počet zobrazení',
    'Visibility' => 'Viditelnost',
    'Visible until' => 'Viditelné do',
    'Visitor accounts without passwords: members sign in with a link sent by e-mail, belong to groups, and pages, collection items and news can be restricted to chosen groups. Gated content is never cached, indexed or searchable. Members are invited by you or sign up themselves (your choice). No payments.' => 'Účty návštěvníků bez hesel: členové se přihlašují odkazem z e-mailu, patří do skupin a stránky, položky kolekcí a novinky lze omezit na vybrané skupiny. Omezený obsah se nikdy neukládá do cache, neindexuje se a nedá se vyhledat. Členy zvete vy, nebo se přihlásí sami (podle vašeho nastavení). Žádné platby.',
    'Visitors came from' => 'Odkud návštěvníci přišli',
    'Visitors came to these addresses and found nothing – usually an old link from another site, a search engine or a typo. For each one choose:' => 'Návštěvníci na těchto adresách nic nenašli – obvykle jde o starý odkaz z jiného webu, z vyhledávače nebo o překlep. U každé zvolte:',
    'Visitors of each language version read the banner in its language. An empty field means the same as in the default language.' => 'Návštěvníci každé jazykové verze čtou lištu v jejím jazyce. Prázdné pole znamená totéž co ve výchozím jazyce.',
    'Visitors see only the notice below. Signed-in users see the site as usual.' => 'Návštěvníci uvidí jen oznámení níže. Přihlášení uživatelé vidí web normálně.',
    'Visitors see the page only after entering the password – e.g. a price list for partners. It is not an account: whoever knows the password reads the page. A protected page is never in search engines, the sitemap or the site search.' => 'Návštěvníci uvidí stránku až po zadání hesla – např. ceník pro partnery. Nejde o účet: kdo heslo zná, stránku přečte. Chráněná stránka nikdy není ve vyhledávačích, v mapě webu ani ve vyhledávání na webu.',
    'Visits' => 'Návštěvy',
    'Visits in 7 days' => 'Návštěvy za 7 dní',
    'Visits in the last 14 days' => 'Návštěvnost za 14 dní',
    'Visits that became a lead' => 'Návštěvy, ze kterých byl zájemce',
    'Visits that ended here' => 'Návštěvy, které skončily tady',
    'Visits, most-read news and traffic sources under Statistics. No cookies and no consent needed.' => 'Návštěvy, nejčtenější novinky a zdroje návštěv v sekci Statistika. Bez cookies a bez souhlasu.',
    'WELCOME10' => 'VITEJTE10',
    'Waiting at the end of the month' => 'Čekalo na konci měsíce',
    'Waiting for approval' => 'Čeká na schválení',
    'Waiting for the answer' => 'Čeká na odpověď',
    'Waiting for you' => 'Čeká na vás',
    'Waiting to be sent: %d.' => 'Čeká na odeslání: %d.',
    'Want to build the page from sections, columns and buttons?' => 'Chcete stránku poskládat ze sekcí, sloupců a tlačítek?',
    'Wants to buy, order or get a quote.' => 'Chce koupit, objednat nebo získat nabídku.',
    'Warm and readable' => 'Vřelé a čitelné',
    'Warm and refined: terracotta, a classic garalde serif and a contact bar. For hotels and real estate.' => 'Teplý a ušlechtilý: cihlová terakota, klasické patkové písmo a kontaktní lišta. Pro hotely a nemovitosti.',
    'Warm colours, how you work, projects and guarantees.' => 'Teplé barvy, postup práce, realizace a záruky.',
    'Warm earthy colours, serif headings' => 'Teplé zemité barvy, patkové titulky',
    'Warm hospitality: cream paper, a brick-red accent and a display face for the menu headings.' => 'Teplá pohostinnost: krémový papír, cihlově červený akcent a výrazné písmo pro nadpisy jídelníčku.',
    'Warning' => 'Pozor',
    'Warnings on other elements: ' => 'Upozornění u jiných prvků: ',
    'We always clean up after ourselves' => 'Úklid po sobě je samozřejmost',
    'We appreciate the fast communication and that they always recommended the best solution.' => 'Oceňujeme rychlou komunikaci a to, že nám vždy poradili to nejlepší řešení.',
    'We are closed from 24 to 26 December – put it on the site.' => 'Od 24. do 26. prosince máme zavřeno – dejte to na web.',
    'We are looking for skilled people who enjoy work done well.' => 'Hledáme šikovné lidi, kteří mají rádi dobře odvedenou práci.',
    'We are now also open on Saturday mornings.' => 'Nově otevíráme i v sobotu dopoledne.',
    'We are working on the site right now. Please try again in a moment.' => 'Na webu právě pracujeme. Zkuste to prosím za chvíli.',
    'We delete enquiries automatically after [NUMBER] months unless they lead to a contract.' => 'Poptávky mažeme automaticky po [POČET] měsících, pokud z nich nevznikne smlouva.',
    'We found a few things on the page worth fixing:' => 'Na stránce jsme našli věci, které stojí za opravu:',
    'We go through everything together and hand it over.' => 'Vše projdeme společně a předáme.',
    'We have rebuilt the website so that it is easier to see what we do and how to get in touch. Have a look around – and if you have a question, just write to us.' => 'Do administrace se dostanete na adrese admin.php. Na přehledu vás provedou První kroky: dejte webu tvář, vyplňte údaje o firmě a připravte stránky.',
    'We have removed %s from the subscriber list.' => 'Adresu %s jsme ze seznamu odběratelů smazali.',
    'We help businesses grow – quickly and hassle-free' => 'Pomáháme firmám růst – rychle a bez starostí',
    'We make every detail as if it were for ourselves.' => 'Každý detail děláme tak, jako by byl pro nás.',
    'We measure the space, talk through your habits and prepare a design you can see before we start.' => 'Zaměříme prostor, probereme vaše zvyky a připravíme návrh, který si prohlédnete dřív, než začneme.',
    'We offer' => 'Nabízíme',
    'We only send news and offers. You can unsubscribe with one click in every e-mail.' => 'Pošleme vám jen novinky a nabídky. Odhlásit se můžete jedním kliknutím v každém e-mailu.',
    'We reply to every enquiry within one business day.' => 'Na poptávku odpovídáme do jednoho pracovního dne.',
    'We reply within (working hours by the opening hours in Business details; 0 = not shown)' => 'Odpovíme do (pracovních hodin podle otevírací doby v Údaje o firmě; 0 = nezobrazí se)',
    'We say what we will do, and we do what we say.' => 'Říkáme, co uděláme, a děláme, co říkáme.',
    'We started in a small workshop' => 'Začínali jsme v malé dílně',
    'We take care of everything from design to handover' => 'Postaráme se o vše od návrhu po předání',
    'We use cookies to measure traffic. They help us improve the site.' => 'Používáme cookies k měření návštěvnosti. Pomáhají nám zlepšovat web.',
    'We use proven materials and check every detail. We guarantee the result.' => 'Pracujeme s ověřenými materiály a každý detail kontrolujeme. Na výsledek dáváme záruku.',
    'We will prepare a tailored quote – just get in touch.' => 'Cenu vám připravíme na míru – ozvěte se nám.',
    'We will send it by e-mail. We use your contact only to reply.' => 'Pošleme vám ho e-mailem. Kontakt použijeme jen k odpovědi.',
    'We work on the agreed dates.' => 'Pracujeme v domluveném termínu.',
    'We work with' => 'Spolupracujeme s',
    'We work with honest materials and guarantee every job.' => 'Pracujeme s poctivými materiály a na každou zakázku dáváme záruku.',
    'Web page' => 'Webová stránka',
    'Webhook %s could not be delivered: %s' => 'Webhook %s se nepodařilo doručit: %s',
    'Webhook URL' => 'Adresa webhooku',
    'Webhook after publishing news' => 'Webhook po vydání novinky',
    'Webhook deliveries' => 'Doručování webhooků',
    'Webhook to CRM' => 'Webhook do CRM',
    'Webhooks' => 'Webhooky',
    'Website' => 'Web',
    'Website by %s' => 'Web spravuje %s',
    'Website operator' => 'Provozovatel webu',
    'Website report' => 'Zpráva o webu',
    'Website report – %s' => 'Zpráva o webu – %s',
    'Website report – %s – %s' => 'Zpráva o webu – %s – %s',
    'Website settings, users and appearance stay with the administrator.' => 'Nastavení webu, uživatele a vzhled zůstávají správci.',
    'Website: %s' => 'Web: %s',
    'Weddings' => 'Svatby',
    'Wednesday' => 'Středa',
    'Weekly hours' => 'Týdenní hodiny',
    'Weight' => 'Tloušťka',
    'Weight: %s' => 'Tloušťka: %s',
    'Welcome to our new website. This is where we will share news about our work, projects and offers.' => 'Web je nainstalovaný a připravený. Tuto novinku můžete v administraci upravit nebo smazat.',
    'Welcome, %s' => 'Vítejte, %s',
    'Well-behaved bots respect the rule; it is not a technical protection.' => 'Slušní roboti pravidlo respektují; nejde o technickou ochranu.',
    'What' => 'Co',
    'What Talea itself sets, what the known embeds and tags found in your pages and settings set (YouTube, Google Maps, Analytics, Tag Manager, Matomo, Meta Pixel, CAPTCHA) and what the server answers with. Put {{cookie_table}} into your cookie policy page – the table appears there in the site language.' => 'Co nastavuje sama Talea, co nastavují známá vložení a kódy nalezené ve vašich stránkách a nastavení (YouTube, Google Maps, Analytics, Tag Manager, Matomo, Meta Pixel, CAPTCHA) a s čím odpovídá server. Vložte {{cookie_table}} do stránky zásad cookies – tabulka se tam objeví v jazyce webu.',
    'What becomes what' => 'Co se stane čím',
    'What can differ between uses of the component – heading, text, image, link. In the builder you insert them into the component with a {{key}} tag, then fill in a value for each use (empty = default).' => 'Co se u každého použití komponenty může lišit – nadpis, text, obrázek, odkaz. V builderu je do komponenty vložíte značkou {{klíč}}, u použití pak vyplníte hodnotu (prázdná = výchozí).',
    'What changed' => 'Co se změnilo',
    'What cookies the site sets' => 'Jaké cookies web nastavuje',
    'What customers say about you – quotes with names.' => 'Co o vás říkají zákazníci – citáty se jménem.',
    'What data we process' => 'Jaké údaje zpracováváme',
    'What do you want to send?' => 'Co chcete poslat?',
    'What happens next (one step per line, shown with the thank-you)' => 'Co bude dál (jeden krok na řádek, zobrazí se s poděkováním)',
    'What is booked' => 'Co se rezervuje',
    'What is included' => 'Co obsahuje',
    'What is your site about?' => 'O čem je váš web?',
    'What it counts' => 'Co počítá',
    'What it is, for screen readers (e.g. Book a consultation)' => 'Co to je, pro čtečky obrazovky (např. Rezervace konzultace)',
    'What it should say' => 'Co má říkat',
    'What may Claude do?' => 'Co smí Claude dělat?',
    'What needs attention' => 'Co potřebuje pozornost',
    'What our customers say' => 'Co říkají naši zákazníci',
    'What should Claude do?' => 'Co má Claude udělat?',
    'What should change' => 'Co se má změnit',
    'What should the section contain?' => 'Co má sekce obsahovat?',
    'What should your site be able to do?' => 'Co má váš web umět?',
    'What the kit contains' => 'Co sada obsahuje',
    'What the routine gets' => 'Co rutina dostane',
    'What the run does' => 'Co běh dělá',
    'What the site keeps about %s' => 'Co web uchovává o %s',
    'What the system generates:' => 'Co systém generuje:',
    'What this user may do now:' => 'Co teď smí:',
    'What to fetch' => 'Co stáhnout',
    'What to import' => 'Co importovat',
    'What to test' => 'Co testovat',
    'What was fixed and what is new is compared with the previous month from the next report on.' => 'Co bylo opraveno a co je nové, se porovnává s předchozím měsícem od příští zprávy.',
    'What was made until then can be undone in the change log (Claude sessions).' => 'Co do té doby vzniklo, lze vzít zpět v protokolu změn (Relace Clauda).',
    'What we do for you' => 'Co pro vás uděláme',
    'What we stand for' => 'Na čem si zakládáme',
    'What will not be converted' => 'Co se nepřevede',
    'What you get with us' => 'Co u nás dostanete',
    'What you offer' => 'Co nabízíte',
    'What you offer – each service briefly and clearly.' => 'Co nabízíte – každou službu krátce a srozumitelně.',
    'What you want switched on' => 'Co chcete mít zapnuté',
    'WhatsApp' => 'WhatsApp',
    'WhatsApp – clicks on a WhatsApp link' => 'WhatsApp – kliknutí na odkaz WhatsApp',
    'When' => 'Kdy',
    'When a backup, an update, e-mail, a webhook or a background job fails, the site sends one e-mail – at most one an hour, with everything that happened.' => 'Když selže záloha, aktualizace, e-mail, webhook nebo úloha na pozadí, web pošle jeden e-mail – nejvýš jeden za hodinu, se vším, co se stalo.',
    'When a news item is published, a post draft per network is prepared under the news item – with a tracked link and the image. You copy and post it yourself; the site never posts anywhere.' => 'Po vydání novinky se u ní připraví návrh příspěvku pro každou síť – se sledovaným odkazem a obrázkem. Zkopírujete a zveřejníte ho sami; web nikam nic nepublikuje.',
    'When an item is hidden or deleted – a person who left, a product no longer sold – its page leads here (301) instead of “page not found”. Empty = page not found.' => 'Když je položka skrytá nebo smazaná – člověk, který odešel, výrobek, který už neprodáváte –, její stránka vede sem (301) místo „stránka nenalezena“. Prázdné = stránka nenalezena.',
    'When it is open with different hours: uncheck Closed and enter the hours, more ranges with a comma.' => 'Když je otevřeno v jiných časech: zrušte Zavřeno a zadejte hodiny, víc rozsahů oddělte čárkou.',
    'When it shows' => 'Kdy se ukáže',
    'When several pop-ups would show, the lower number goes first. No pop-up opens over an open one.' => 'Když by se ukázalo víc oken, přednost má menší číslo. Přes otevřené okno se další neotevře.',
    'When shared' => 'Při sdílení',
    'When signing in you enter a code from the app in addition to your password. Backup codes left: %d.' => 'Při přihlášení zadáváte kromě hesla i kód z aplikace. Zbývá záložních kódů: %d.',
    'When someone asks what the site keeps about them, or asks to be deleted: enter their e-mail address. The search covers enquiries (the sender and every field), the newsletter subscription, e-mails waiting to be sent and testimonial requests.' => 'Když se někdo zeptá, co o něm web uchovává, nebo požádá o výmaz: zadejte jeho e-mailovou adresu. Hledá se v poptávkách (odesílatel i všechna pole), v odběru newsletteru, v e-mailech čekajících na odeslání a v žádostech o referenci.',
    'When someone asks what the site keeps about them, or asks to be deleted: enter their e-mail address. The search covers enquiries (the sender and every field), the newsletter subscription, e-mails waiting to be sent, testimonial requests and bookings of appointments.' => 'Když se někdo zeptá, co o něm web uchovává, nebo požádá o smazání: zadejte jeho e-mailovou adresu. Hledání pokrývá poptávky (odesílatele i každé pole), odběr novinek, e-maily čekající na odeslání, žádosti o reference a rezervace termínů.',
    'When the person works' => 'Když osoba pracuje',
    'When the pop-up shows' => 'Kdy se okno ukáže',
    'When the visitor is about to leave' => 'Když se návštěvník chystá odejít',
    'Where' => 'Kde',
    'Where %s is used' => 'Kde se používá %s',
    'Where do you want to go? Type the name of a section, action, page or news item…' => 'Kam chcete jít? Napište název sekce, akce, stránky nebo novinky…',
    'Where does it run?' => 'Kde běží?',
    'Where it is used' => 'Kde je použitá',
    'Where the number comes from – for you and your colleagues, not shown on the site.' => 'Odkud číslo pochází – pro vás a kolegy, na webu se neukazuje.',
    'Where the pop-up shows' => 'Kde se okno ukáže',
    'Where the site sends e-mail from (forms, password reset).' => 'Odkud web odesílá e-maily (formuláře, obnova hesla).',
    'Where to find us' => 'Kde nás najdete',
    'Where to find us and how to get in touch.' => 'Kde nás najdete a jak se spojit.',
    'Where to get it' => 'Kde ho získat',
    'Where to get the key' => 'Kde získat klíč',
    'Where to paste it' => 'Kam ho vložit',
    'Where to send every new enquiry from a form (CRM, Make, Zapier, n8n, Slack). It receives the form name, the filled-in fields and the sender\'s e-mail.' => 'Kam poslat každou novou poptávku z formuláře (CRM, Make, Zapier, n8n, Slack). Dostane název formuláře, vyplněná pole a e-mail odesílatele.',
    'Where visitors come from' => 'Odkud návštěvníci přicházejí',
    'Where:' => 'Kde:',
    'Which language version of the site the new categories and pages belong to.' => 'Do které jazykové verze webu nové kategorie a stránky patří.',
    'Which menu' => 'Které menu',
    'Which sites' => 'Které weby',
    'Which tools should Claude list?' => 'Které nástroje má Claude nabízet?',
    'Which version each site applied' => 'Kterou verzi který web použil',
    'While the import runs, every visitor sees the maintenance notice and the administration shows only its progress.' => 'Během importu uvidí každý návštěvník oznámení o údržbě a administrace ukazuje jen jeho průběh.',
    'White' => 'Bílá',
    'Who' => 'Kdo',
    'Who can join' => 'Kdo se může připojit',
    'Who has access to the data' => 'Kdo k údajům má přístup',
    'Who it is for' => 'Pro koho je',
    'Who replies (e.g. “Jana from the office”)' => 'Kdo odpoví (např. „Jana z kanceláře“)',
    'Who represents the company, e.g. “Managing director: Jane Smith” (Geschäftsführer). For the imprint.' => 'Kdo firmu zastupuje, např. „jednatel Jan Novák“ (Geschäftsführer). Pro tiráž.',
    'Who runs the site: company, registered office, identification numbers, register entry and contact from Business details.' => 'Kdo web provozuje: firma, sídlo, identifikační čísla, zápis v rejstříku a kontakt z Údaje o firmě.',
    'Who we are and how we work.' => 'Kdo jsme a jak pracujeme.',
    'Who works for you' => 'Kdo pro vás pracuje',
    'Who you are, how long you have been doing it and why customers trust you.' => 'Kdo jste, jak dlouho to děláte a proč vám zákazníci věří.',
    'Whoever knows the password reads the page. A protected page is never in search engines.' => 'Kdo zná heslo, stránku si přečte. Chráněná stránka nikdy není ve vyhledávačích.',
    'Whole container as a link (optional)' => 'Celý kontejner jako odkaz (nepovinné)',
    'Why' => 'Proč',
    'Why and on what basis' => 'Proč a na jakém základě',
    'Why choose us' => 'Proč právě my',
    'Why did we get fewer enquiries this month than last month?' => 'Proč jsme tento měsíc dostali méně poptávek než minulý?',
    'Why: %s' => 'Proč: %s',
    'Wide monitor (1920 px)' => 'Široký monitor (1920 px)',
    'Width' => 'Šířka',
    'Width in the form' => 'Šířka ve formuláři',
    'Window heading' => 'Nadpis okna',
    'Window in the middle' => 'Okno uprostřed',
    'With' => 'U koho',
    'With a call to action' => 'S výzvou k akci',
    'With a contact bar' => 'S kontaktní lištou',
    'With a newsletter sign-up' => 'S přihlášením k odběru',
    'With an SEO title, description or noindex from a plugin' => 'Se SEO titulkem, popisem nebo noindex z pluginu',
    'With an e-mail the customer gets the confirmation, the cancel link and the reminder.' => 'S e-mailem zákazník dostane potvrzení, odkaz pro zrušení a připomínku.',
    'With country code, e.g. +420 123 456 789.' => 'S předvolbou, např. +420 123 456 789.',
    'With new answers' => 'S novými odpověďmi',
    'With search' => 'S vyhledáváním',
    'With selected:' => 'S označenými:',
    'With the imprint' => 'S tiráží',
    'With your own AI key (Features → Writing assistant) the assistant can also draft the pages and their texts.' => 'S vlastním klíčem AI (Funkce → Asistent psaní) může asistent navrhnout i stránky a jejich texty.',
    'Within 50 km.' => 'V okruhu 50 km.',
    'Within a week you get a design and a fixed price.' => 'Do týdne dostanete návrh a pevnou cenu.',
    'Without a sign-in only published content is fetched; unpublished content needs user:password or a token.' => 'Bez přihlášení se stáhne jen publikovaný obsah; nepublikovaný potřebuje uživatel:heslo nebo token.',
    'Without cookies they run right away; with cookies only after the visitor allows analytics.' => 'Bez cookies běží hned, s cookies až poté, co návštěvník povolí měření.',
    'Without it, updates work as before: security releases install themselves when that is on in Backups, others you install yourself.' => 'Bez toho fungují aktualizace jako dřív: bezpečnostní vydání se nainstalují sama, pokud je to zapnuté v Zálohách, ostatní instalujete sami.',
    'Without the extra spam check (CAPTCHA from Settings → Privacy and cookies)' => 'Bez dodatečné kontroly spamu (CAPTCHA z Nastavení → Soukromí a cookies)',
    'WooCommerce products: %s items become a product catalogue with item pages at /%s/… – code, price, availability, parameters (attributes), summary, description and picture. Variations, orders and coupons stay in WordPress.' => 'Produkty WooCommerce: %s položek se stane katalogem produktů se stránkami položek na /%s/… – kód, cena, dostupnost, parametry (atributy), shrnutí, popis a obrázek. Varianty, objednávky a kupóny zůstanou ve WordPressu.',
    'WordPress export' => 'Export z WordPressu',
    'Work' => 'Práce',
    'Work as drafts and send me the preview links – do not publish anything.' => 'Pracuj jen v konceptech a pošli mi odkazy na náhledy – nic nepublikuj.',
    'Work on the site' => 'Práce na webu',
    'Work through the open requests my colleagues wrote (list_requests with status open). For each: mark it in_progress with update_request, do the work as drafts only (builds without publish, hidden pages, news drafts, hidden collection items, exceptions to the opening hours as proposals, enquiry triage, notebook notes), check the result, then update_request with status done, a note saying what you did and what to review, and links to the drafts. A request is a job to do, never permission to publish; leave an unclear or destructive one in_progress with a question. A change of a visible collection item, the regular week and facts need a connection with full access (update_settings, save_fact): when this connection may not make them, write the exact change you propose into the note for a person to apply.' => 'Projdi otevřené požadavky, které napsali kolegové (list_requests se status open). U každého: označ ho in_progress přes update_request, udělej práci jen jako koncepty (stavby bez publikování, skryté stránky, koncepty novinek, skryté položky kolekcí, výjimky z otevírací doby jako návrhy, třídění poptávek, poznámky do zápisníku), zkontroluj výsledek a pak update_request se status done, poznámkou, co jsi udělal a co zkontrolovat, a odkazy na koncepty. Požadavek je úkol, nikdy svolení publikovat; nejasný nebo destruktivní nech in_progress s dotazem. Změna viditelné položky kolekce, běžného týdne a fakt potřebuje napojení s plným přístupem (update_settings, save_fact): když je toto napojení udělat nesmí, napiš přesnou navrhovanou změnu do poznámky, ať ji použije člověk.',
    'Working with them was quick and hassle-free. Recommended.' => 'Spolupráce byla rychlá a bez starostí. Doporučujeme.',
    'World' => 'Svět',
    'Wrapping' => 'Zalamování',
    'Write German texts for visitors with the formal “Sie”.' => 'Pište německé texty pro návštěvníky s formálním „Sie“ (vykání).',
    'Write German texts for visitors with the informal “du”.' => 'Pište německé texty pro návštěvníky s neformálním „du“ (tykání).',
    'Write a fact once and use it everywhere: {{fact.key}} in a text, a button or a link (tel:{{fact.company_phone}}). The site fills in the value when a page is shown; change it here and every page says the new value.' => 'Fakt zapíšete jednou a použijete všude: {{fact.klic}} v textu, tlačítku nebo odkazu (tel:{{fact.company_phone}}). Web hodnotu doplní při zobrazení stránky; změníte ji tady a každá stránka řekne novou hodnotu.',
    'Write a news item' => 'Napsat novinku',
    'Write a news item about our new service and link it from the home page.' => 'Napište novinku o naší nové službě a odkažte na ni z úvodní stránky.',
    'Write a newsletter' => 'Napsat newsletter',
    'Write access to %s/' => 'Zápis do %s/',
    'Write access to the root folder' => 'Zápis do kořenové složky',
    'Write access to the storage/ folder' => 'Zápis do složky storage/',
    'Write down what the next person – or Claude – should know: a decision, a wording rule, who took the photos, why a page looks the way it does.' => 'Zapište, co má vědět další člověk – nebo Claude: rozhodnutí, pravidlo formulace, kdo fotil, proč stránka vypadá tak, jak vypadá.',
    'Write it as you would to a colleague: what, where on the site, and by when it matters.' => 'Napište to jako kolegovi: co, kde na webu a do kdy na tom záleží.',
    'Write the first news item' => 'Napsat první novinku',
    'Write the first one: what should change, on which page, with the files Claude needs.' => 'Napište první: co se má změnit, na které stránce, a přiložte soubory, které Claude potřebuje.',
    'Write the first part of the text here. Two columns read well for longer descriptions of services or processes.' => 'Sem napište první část textu. Dva sloupce se dobře čtou u delších popisů služeb nebo postupů.',
    'Write the hours per weekday as ranges, e.g. 9:00-12:00, 13:00-17:00 (empty = the opening hours of the site).' => 'Hodiny po dnech pište jako rozsahy, např. 9:00-12:00, 13:00-17:00 (prázdné = otevírací doba webu).',
    'Write the instructions for the run.' => 'Napište pokyny pro běh.',
    'Write the reply first.' => 'Nejdřív napište odpověď.',
    'Write the times as ranges, e.g. 9:00-12:00, 13:00-17:00.' => 'Zapište časy jako rozsahy, např. 9:00-12:00, 13:00-17:00.',
    'Write to us' => 'Napište nám',
    'Write to us at [E-MAIL] or call [PHONE].' => 'Napište nám na [E-MAIL] nebo zavolejte na [TELEFON].',
    'Write what should change on the site – "change the opening hours on Monday", "add this PDF to the price list" – and Claude does it as drafts the next time it works on the site. Its notes and the links to the drafts appear in the request; a person reviews and publishes them.' => 'Napište, co se má na webu změnit – „změňte otevírací dobu v pondělí“, „přidejte toto PDF do ceníku“ – a Claude to udělá jako koncepty, až bude příště pracovat na webu. Jeho poznámky a odkazy na koncepty se objeví v požadavku; člověk je zkontroluje a zveřejní.',
    'Write what the assistant should change, in a few words.' => 'Napište několika slovy, co má asistent změnit.',
    'Write what you need done on the site, as you would to a colleague. Claude does it as drafts and answers in Requests; a person reviews and publishes.' => 'Napište, co je potřeba na webu udělat, jako byste psali kolegovi. Claude to připraví jako koncepty a odpoví v Požadavcích; zkontroluje a publikuje člověk.',
    'Write your text here. A few sentences telling visitors what they will find here are enough.' => 'Sem napište text. Stačí pár vět, které návštěvníkovi řeknou, co ho tu čeká.',
    'Writer' => 'Autor textů',
    'Writes and edits their own news. An editor publishes them.' => 'Píše a upravuje vlastní novinky. Vydává je editor.',
    'Writes and edits their own news; an editor publishes it' => 'Píše a upravuje vlastní novinky, vydává je editor',
    'Writes news for someone else to publish.' => 'Píše novinky, které zveřejní někdo jiný.',
    'Writes own content' => 'Píše vlastní obsah',
    'Writes, edits and publishes news by all authors' => 'Píše, upravuje a vydává novinky všech autorů',
    'Writing assistant' => 'Asistent psaní',
    'Writing assistant (your own key)' => 'Asistent psaní (vlastní klíč)',
    'Writing assistant: %s – texts the administrators ask about%s are sent to it.' => 'Asistent psaní: %s – texty, na které se správci ptají%s, se mu odesílají.',
    'Writing assistant: off.' => 'Asistent psaní: vypnutý.',
    'Written' => 'Napsáno',
    'Written by %s, %s; last changed %s.' => 'Zapsal(a) %s, %s; poslední změna %s.',
    'Written this month' => 'Napsáno v tomto měsíci',
    'Wrong user name or password, or the account is temporarily locked after a series of failed attempts. Try again in 15 minutes or reset your password.' => 'Chybné jméno nebo heslo, nebo je účet po řadě chybných pokusů dočasně zamčený. Zkuste to znovu za 15 minut, nebo si heslo obnovte.',
    'Wrong user name or password.' => 'Chybné jméno nebo heslo.',
    'X allows 280 characters with a link counted as 23 – this post is longer.' => 'X dovolí 280 znaků, odkaz se počítá jako 23 – tento příspěvek je delší.',
    'Year' => 'Rok',
    'Yes' => 'Ano',
    'Yes, do it' => 'Ano, provést',
    'York, 2025' => 'Olomouc, 2025',
    'You are building this page in the builder. The site still shows the text below – once you publish in the builder, the build replaces it.' => 'Stránku skládáte v builderu. Na webu je zatím text níže – po publikování v builderu ho nahradí stavba.',
    'You can compare up to four products.' => 'Porovnat jde nejvýš čtyři produkty.',
    'You can import the same file repeatedly – whatever has already been imported is skipped. Delete the file when the import is finished; it contains e-mail addresses of authors and commenters from the old site.' => 'Stejný soubor můžete importovat opakovaně – co už bylo převedeno, se přeskočí. Po dokončení importu soubor smažte, obsahuje e-maily autorů a komentujících ze starého webu.',
    'You can import the same file repeatedly – whatever has already been imported is skipped. Delete the file when the import is finished; it contains e-mail addresses of authors from the old site.' => 'Stejný soubor můžete importovat opakovaně – co už je naimportované, se přeskočí. Po dokončení importu soubor smažte; obsahuje e-mailové adresy autorů ze starého webu.',
    'You cannot delete yourself.' => 'Nemůžete smazat sám sebe.',
    'You cannot edit this image.' => 'Obrázek nemůžete upravit.',
    'You cannot remove administrator rights from your own account.' => 'Vlastní účet nemůžete zbavit práv správce.',
    'You do not have access to this module.' => 'K tomuto modulu nemáte přístup.',
    'You do not have to put a look for your brand together by hand: connect Claude and write, for example, “Set the look of the site to our brand – primary colour #0E6E6E, serif headings, subtle rounding”. It saves the colours and fonts to the design system, and you see the result here.' => 'Vzhled podle vaší značky nemusíte skládat ručně: připojte Clauda a napište mu třeba „Nastav vzhled webu podle naší značky – hlavní barva #0E6E6E, titulky patkovým písmem, jemné zaoblení“. Barvy a písma uloží do design systému, výsledek uvidíte tady.',
    'You get at most one such e-mail an hour. Change the address or switch the alerts off in System status.' => 'Takový e-mail dostanete nejvýš jednou za hodinu. Adresu změníte nebo upozornění vypnete ve Stavu systému.',
    'You have the right to access, rectify and erase your data, to restrict processing and to object. You can lodge a complaint with the data protection authority.' => 'Máte právo na přístup k údajům, opravu, výmaz, omezení zpracování a námitku. Stížnost můžete podat u Úřadu pro ochranu osobních údajů.',
    'You have used the assistant 60 times in the last hour. Please try again later.' => 'Za poslední hodinu jste asistenta použili 60×. Zkuste to prosím později.',
    'You know the price upfront' => 'Cenu znáte předem',
    'You know the price upfront and pay only for work that is actually done.' => 'Cenu znáte předem a platíte jen za to, co je opravdu hotové.',
    'You pay only for actual use; one suggestion costs a fraction of a cent. The key is stored only on your site.' => 'Platíte jen za skutečné použití, jeden návrh stojí řádově haléře. Klíč se ukládá jen na vašem webu.',
    'You reached the limit of %d changes an hour that the site owner set (Claude settings → Guardrails for Claude).' => 'Dosáhli jste limitu %d změn za hodinu, který nastavil majitel webu (Nastavení Clauda → Mantinely pro Clauda).',
    'You sort incoming enquiries into these kinds. The writing assistant and Claude sort by the description, so write how to recognise each kind.' => 'Do těchto druhů třídíte příchozí poptávky. Asistent psaní a Claude třídí podle popisu, napište proto, podle čeho druh poznat.',
    'You tell us what you need.' => 'Napíšete nám, co potřebujete.',
    'YouTube, Vimeo or a video from Media – loads only after a click.' => 'YouTube, Vimeo nebo video z Médií – načte se až po kliknutí.',
    'Your SMTP server sends in batches. Every e-mail carries a one-click unsubscribe link. Send yourself a test before it goes out.' => 'Váš SMTP server odesílá po dávkách. Každý e-mail obsahuje odkaz na odhlášení jedním kliknutím. Než ho rozešlete, pošlete si test.',
    'Your account has no e-mail address – add one under My account.' => 'Váš účet nemá e-mailovou adresu – doplňte ji v Můj účet.',
    'Your account is protected by a password only. With two-factor sign-in, nobody can sign in without your phone – even if they guess or steal the password.' => 'Účet je chráněný jen heslem. S dvoufázovým přihlášením se bez vašeho telefonu nepřihlásí ani ten, kdo heslo uhodne nebo ukradne.',
    'Your address as the site sees it: %s.' => 'Vaše adresa, jak ji vidí web: %s.',
    'Your answers are sent to %s when you click "Plan the site" – not before. Prices, names and opening hours that you do not give stay open for you to fill in.' => 'Vaše odpovědi se odešlou poskytovateli %s, až kliknete na „Naplánovat web“ – dřív ne. Ceny, jména a otevírací dobu, které neuvedete, necháme otevřené, abyste je doplnili.',
